// The part of the figure renderer charts need beyond a drawing: each chart's layers trained into its axes, colours and legend; a
// Cartesian chart measured into its cell - legend, axes, and the plotting area left between them - and drawn; a radial chart's web of
// rings and spokes drawn. Ported from Parcel NExT's Divooka.Graphics.Plotting/Rendering/FigureRenderer.cs (FigureJob's Train,
// DrawCartesian and DrawPolar, and CartesianFrame); the figure's own layout is in plot/figure.
//
// Registered with the figure renderer when this module loads, so a page that draws only diagrams carries none of it. Axes shared
// across a grid of charts (Figure.ShareX/ShareY) are not ported: no Dhole figure shares an axis.

import { defaultAxis, defaultColorScale, defaultLegend, type Axis, type AxisSide } from "./axis";
import { AxisLayout } from "./axis-painter";
import { ChartPaints, ChartTraining, ColorAssignment, ColorTraining, LegendCollector, PolarFrame, PolarTraining, snap, type PolarLayer } from "./contracts";
import { linearNice } from "./d3";
import { insideBox, registerCharting, type ChartPlan, type DrawContext, type FigureJob, type LayerPlan, type TextAnchor } from "./figure";
import { LegendPainter } from "./legend-painter";
import { AxisTraining, ScaleDomain, type PositionScale } from "./scales";
import type { Theme } from "./theme";
import type { TextPainter } from "./figure";
import { RectF, VectorPath } from "../rendering/geometry";

/** What training gave a chart: its trained axes and colours. */
interface Trained {
  training: ChartTraining;
  x: ScaleDomain | null;
  y: ScaleDomain | null;
  y2: ScaleDomain | null;
  colors: ColorAssignment;
}

const trainedOf = (plan: ChartPlan): Trained => plan.trained as Trained;
const axisX = (plan: ChartPlan): Axis => plan.chart.x ?? defaultAxis;
const axisY = (plan: ChartPlan): Axis => plan.chart.y ?? defaultAxis;
const legendOf = (plan: ChartPlan) => plan.chart.legend ?? defaultLegend;

// ---------------------------------------------------------------- training

function train(job: FigureJob, plans: ChartPlan[]): void {
  const trainings = plans.map(
    (plan) =>
      new ChartTraining(
        new AxisTraining(axisX(plan), "horizontal"),
        new AxisTraining(axisY(plan), "vertical"),
        new AxisTraining(plan.chart.y2 ?? defaultAxis, "second vertical"),
        new ColorTraining(),
      ),
  );
  plans.forEach((plan, i) => {
    for (const layer of plan.layers) layer.train?.(trainings[i]);
  });

  plans.forEach((plan, i) => {
    const training = trainings[i];
    let x: ScaleDomain | null = null;
    let y: ScaleDomain | null = null;
    let y2: ScaleDomain | null = null;
    if (plan.frame === "cartesian") {
      x = ScaleDomain.resolve(training.x, job.notes);
      y = ScaleDomain.resolve(training.y, job.notes);
      if (training.y2.used) y2 = ScaleDomain.resolve(training.y2, job.notes);
    }
    const colors = new ColorAssignment(training.color, plan.chart.color ?? defaultColorScale, job.theme);

    const legend = new LegendCollector(colors);
    for (const layer of plan.layers) layer.addLegend?.(legend);
    const spec = legendOf(plan);
    const items = spec.items ?? legend.items;
    const auto = items.length >= 2 || legend.colorBar !== null;
    const visible = spec.visible ?? auto;
    plan.legend = new LegendPainter(job.theme, job.text, visible ? items : [], visible ? legend.colorBar : null, spec.title);
    plan.legendItems = items;
    plan.legendVisible = visible;
    plan.trained = { training, x, y, y2, colors } satisfies Trained;
    plan.drawExtras = { colors };
  });
}

// ---------------------------------------------------------------- Cartesian charts

/** A Cartesian chart measured into its cell: its legend, its axes and the plotting area left between them. */
export class CartesianFrame {
  cell!: RectF;
  xAxis!: AxisLayout;
  yAxis!: AxisLayout;
  y2Axis: AxisLayout | null = null;
  legend: RectF | null = null;
  titleTop = 0;
  plot!: RectF;
  inner!: RectF;
  planOf!: ChartPlan;
  /** The room for the vertical axis, stated by the figure when charts in a grid share it. */
  forcedLeft: number | null = null;
  /** The room for the horizontal axis, stated by the figure when charts in a grid share it. */
  forcedBottom: number | null = null;

  static measure(plan: ChartPlan, cell: RectF, theme: Theme, text: TextPainter, showX: boolean, showY: boolean, forcedLeft: number | null = null, forcedBottom: number | null = null): CartesianFrame {
    let top = cell.top;
    const titleTop = top;
    if (plan.chart.title) top += text.lineHeight("chartTitle") + theme.textGap;
    let inner = new RectF(cell.left, top, cell.right, cell.bottom);

    let legendBox: RectF | null = null;
    if (!plan.legend.isEmpty) {
      const gap = theme.textGap * 2;
      switch (legendOf(plan).position) {
        case "right": {
          const size = plan.legend.measureColumn(inner.height);
          legendBox = RectF.fromXYWH(inner.right - size.width, inner.top, size.width, size.height);
          inner = new RectF(inner.left, inner.top, inner.right - size.width - gap, inner.bottom);
          break;
        }
        case "left": {
          const size = plan.legend.measureColumn(inner.height);
          legendBox = RectF.fromXYWH(inner.left, inner.top, size.width, size.height);
          inner = new RectF(inner.left + size.width + gap, inner.top, inner.right, inner.bottom);
          break;
        }
        case "top": {
          const size = plan.legend.measureRow(inner.width);
          legendBox = RectF.fromXYWH(inner.left, inner.top, inner.width, size.height);
          inner = new RectF(inner.left, inner.top + size.height + gap, inner.right, inner.bottom);
          break;
        }
        case "bottom": {
          const size = plan.legend.measureRow(inner.width);
          legendBox = RectF.fromXYWH(inner.left, inner.bottom - size.height, inner.width, size.height);
          inner = new RectF(inner.left, inner.top, inner.right, inner.bottom - size.height - gap);
          break;
        }
        default: {
          const size = plan.legend.measureColumn(inner.height / 2);
          legendBox = RectF.fromXYWH(0, 0, size.width, size.height);
          break;
        }
      }
    }

    const frame = Object.assign(new CartesianFrame(), { cell, inner, titleTop, legend: legendBox, planOf: plan, forcedLeft, forcedBottom });
    frame.fit(theme, text, showX, showY);
    return frame;
  }

  /** Fits the axes to the room the cell has: label sizes depend on tick counts, which depend on the plotting area's size, which depends on the label sizes, so the loop runs until the bands stop changing. */
  private fit(theme: Theme, text: TextPainter, showX: boolean, showY: boolean): void {
    const plan = this.planOf;
    const trained = trainedOf(plan);
    const planX = trained.x!;
    const planY = trained.y!;
    const xSpec = planX.spec;
    const ySpec = planY.spec;
    const xVisible = xSpec.visible;
    const yVisible = ySpec.visible;
    const xSide: AxisSide = xSpec.side === "top" ? "top" : "bottom";
    const ySide: AxisSide = ySpec.side === "right" ? "right" : "left";
    const usesY2 = trained.training.y2.used;

    const overhang = plan.layers.length === 0 ? 0 : Math.max(...plan.layers.map((l: LayerPlan) => l.overhang?.(text) ?? 0));
    let plotWidth = this.inner.width * 0.8;
    let plotHeight = this.inner.height * 0.8;
    let x!: AxisLayout;
    let y!: AxisLayout;
    let y2: AxisLayout | null = null;
    const leftRoom = (xAxis: AxisLayout, yBand: number): number => this.forcedLeft ?? Math.max(yBand, xAxis.overhangStart);
    const bottomRoom = (xAxis: AxisLayout): number => (!xVisible ? 0 : this.forcedBottom ?? (showX ? xAxis.band : xAxis.tickLength));
    for (let pass = 0; pass < 4; pass++) {
      y = AxisLayout.measure(planY, false, ySide, plotHeight, text, theme, yVisible && showY, yVisible && showY);
      y2 = usesY2 && trained.y2 !== null ? AxisLayout.measure(trained.y2, false, "right", plotHeight, text, theme, trained.y2.spec.visible, trained.y2.spec.visible) : null;
      let leftBand = yVisible ? y.band : 0;
      let rightBand = y2?.band ?? 0;
      if (ySide === "right") [leftBand, rightBand] = [rightBand, leftBand];
      let newWidth = Math.max(10, this.inner.width - (this.forcedLeft ?? leftBand) - rightBand);
      x = AxisLayout.measure(planX, true, xSide, newWidth, text, theme, xVisible && showX, xVisible && showX);
      newWidth = Math.max(10, this.inner.width - leftRoom(x, leftBand) - Math.max(rightBand, x.overhangEnd));
      const topRoom = Math.max(overhang, y.overhangEnd);
      const newHeight = Math.max(10, this.inner.height - bottomRoom(x) - topRoom);
      const settled = Math.abs(newWidth - plotWidth) < 0.5 && Math.abs(newHeight - plotHeight) < 0.5;
      plotWidth = newWidth;
      plotHeight = newHeight;
      if (settled && pass > 0) break;
    }

    // The axis carrying the values takes the theme's primary gridlines: the vertical one, unless the categories run down it, as horizontal bars put them.
    const xIsValue = planX.type !== "category" && planY.type === "category";
    x.isValueAxis = xIsValue;
    y.isValueAxis = planY.type !== "category" && !xIsValue;
    if (y2 !== null) y2.isValueAxis = true;
    this.xAxis = x;
    this.yAxis = y;
    this.y2Axis = y2;

    let yBand = yVisible ? y.band : 0;
    let y2Band = y2?.band ?? 0;
    if (ySide === "right") [yBand, y2Band] = [y2Band, yBand];
    const left = this.inner.left + leftRoom(x, yBand);
    const right = this.inner.right - Math.max(y2Band, x.overhangEnd);
    let topEdge = this.inner.top + Math.max(overhang, y.overhangEnd);
    let bottomEdge = this.inner.bottom - bottomRoom(x);
    if (xSide === "top") {
      const band = this.inner.bottom - bottomEdge;
      topEdge = this.inner.top + band;
      bottomEdge = this.inner.bottom - Math.max(overhang, y.overhangStart);
    }
    let plot = new RectF(left, topEdge, Math.max(left + 10, right), Math.max(topEdge + 10, bottomEdge));

    if (plan.chart.equalAspect && planX.type !== "category" && planY.type !== "category") {
      const xUnits = planX.max - planX.min;
      const yUnits = planY.max - planY.min;
      if (xUnits > 0 && yUnits > 0) {
        const perUnit = Math.min(plot.width / xUnits, plot.height / yUnits);
        const w = xUnits * perUnit;
        const h = yUnits * perUnit;
        plot = RectF.fromXYWH(plot.left + (plot.width - w) / 2, plot.top + (plot.height - h) / 2, w, h);
      }
    }
    this.plot = plot;

    if (this.legend !== null) {
      const legend = this.legend;
      const position = legendOf(plan).position;
      this.legend =
        position === "right" || position === "left"
          ? RectF.fromXYWH(legend.left, plot.top, legend.width, legend.height)
          : position === "top" || position === "bottom"
            ? RectF.fromXYWH(plot.left, legend.top, Math.max(10, this.cell.right - plot.left), legend.height)
            : insideBox(position, plot, { width: legend.width, height: legend.height });
    }
  }
}

function drawLayers(job: FigureJob, plan: ChartPlan, context: DrawContext, plot: RectF): void {
  for (const layer of plan.layers) {
    const saved = job.sink.save();
    try {
      if (layer.clipToPlot) job.sink.clipRect(plot.inflate(2));
      layer.draw(context);
    } finally {
      job.sink.restoreToCount(saved);
    }
  }
}

function drawCartesian(job: FigureJob, plan: ChartPlan, frame: CartesianFrame): void {
  const { sink, theme, text } = job;
  const plot = frame.plot;
  const x: PositionScale = frame.xAxis.scaleOver(plot.left, plot.right, theme);
  const y: PositionScale = frame.yAxis.scaleOver(plot.bottom, plot.top, theme);
  const y2: PositionScale | null = frame.y2Axis?.scaleOver(plot.bottom, plot.top, theme) ?? null;
  const context = job.context(plan, plot, { x, y, y2 });

  const plotBackground = plan.chart.plotBackground ?? theme.plotBackground;
  if (plotBackground.a > 0) sink.drawRect(plot, ChartPaints.fill(plotBackground));

  frame.xAxis.drawGrid(sink, context, x, plot);
  frame.yAxis.drawGrid(sink, context, y, plot);

  if (plan.layers.length === 0) text.draw(sink, "No data", plot.midX, plot.midY, "dataLabel", theme.mutedInk, "center");

  drawLayers(job, plan, context, plot);

  frame.xAxis.drawZero(sink, context, x, plot);
  frame.yAxis.drawZero(sink, context, y, plot);
  if (theme.frame) {
    const hairline = theme.hairlineWidth;
    const snapped = new RectF(snap(context, plot.left, hairline), snap(context, plot.top, hairline), snap(context, plot.right, hairline), snap(context, plot.bottom, hairline));
    sink.drawRect(snapped, ChartPaints.hairline(theme.axisLine, hairline));
  }
  frame.xAxis.draw(sink, context, x, plot);
  frame.yAxis.draw(sink, context, y, plot);
  if (frame.y2Axis !== null && y2 !== null) frame.y2Axis.draw(sink, context, y2, plot);

  job.drawLegendAndTitle(plan, frame.cell, plot, frame.legend, frame.titleTop);
}

// ---------------------------------------------------------------- radial charts

function drawPolar(job: FigureJob, plan: ChartPlan, cell: RectF): void {
  const { sink, theme, text } = job;
  const { area, legend: legendBox, titleTop } = job.reserve(plan, cell);

  // Spokes are the categories every radial layer named, in order; the radius runs from zero to the largest value.
  const polar = new PolarTraining();
  for (const layer of plan.layers) (layer as unknown as Partial<PolarLayer>).trainPolar?.(polar);
  const chartY = axisY(plan);
  const radialSpec: Axis = { ...chartY, includeZero: chartY.includeZero ?? true, nice: true };
  const radialTraining = new AxisTraining(radialSpec, "radial");
  radialTraining.addValue(polar.low);
  radialTraining.addValue(polar.high);
  radialTraining.wantsZero = true;
  let radial = ScaleDomain.resolve(radialTraining, job.notes);
  const ringCount = radialSpec.tickCount ?? 4;
  if (radialSpec.max === null && radial.type === "linear") {
    // Rounded for the number of rings rather than for ten ticks, so the outermost ring is the range's end and every value sits inside the web.
    const niced = linearNice([radial.min, radial.max], ringCount);
    radial = ScaleDomain.continuous("linear", niced[0], niced[niced.length - 1], radialSpec);
  }
  const rings = radial.ticks(ringCount);

  const spokeLabel = polar.spokes.length === 0 ? 0 : Math.max(...polar.spokes.map((s) => text.measure(s, "tick").width));
  const lineHeight = text.lineHeight("tick");
  const radius = Math.max(10, Math.min(area.width / 2 - spokeLabel - 8, area.height / 2 - lineHeight - 8));
  const frame = new PolarFrame(area.midX, area.midY, radius, polar.spokes, radial, rings);
  const context = job.context(plan, area, { polar: frame });

  // The web: rings at the radial ticks, a spoke per category, labels at the spoke ends.
  const hairline = theme.hairlineWidth;
  for (const ring of rings) {
    if (ring.value <= radial.min) continue;
    let path = new VectorPath();
    for (let i = 0; i < Math.max(3, polar.spokes.length); i++) {
      const p = polar.spokes.length >= 3 ? frame.point(i, ring.value) : { x: frame.centerX, y: frame.centerY };
      if (i === 0) path.moveTo(p.x, p.y);
      else path.lineTo(p.x, p.y);
    }
    path.close();
    if (polar.spokes.length < 3) path = new VectorPath().addCircle(frame.centerX, frame.centerY, frame.radiusOf(ring.value));
    sink.drawPath(path, ChartPaints.hairline(theme.grid, hairline));
  }
  for (let i = 0; i < polar.spokes.length; i++) {
    const p = frame.point(i, radial.max);
    sink.drawLine(frame.centerX, frame.centerY, p.x, p.y, ChartPaints.hairline(theme.grid, hairline));
    const angle = frame.angle(i);
    const lx = frame.centerX + (radius + 8) * Math.sin(angle);
    const ly = frame.centerY - (radius + 8) * Math.cos(angle);
    const s = Math.sin(angle);
    const c = Math.cos(angle);
    const anchor: TextAnchor = Math.abs(s) < 0.2 ? (c > 0 ? "bottom" : "top") : s > 0 ? "left" : "right";
    text.draw(sink, polar.spokes[i], lx, ly, "tick", theme.secondaryInk, anchor);
  }
  for (const ring of rings) {
    if (ring.value <= radial.min || !ring.label) continue;
    // Halfway between the first two spokes, where no spoke or spoke label is.
    const between = polar.spokes.length >= 2 ? frame.angle(0.5) : Math.PI / 4;
    const r = frame.radiusOf(ring.value) * (polar.spokes.length >= 3 ? Math.cos(Math.PI / polar.spokes.length) : 1);
    text.draw(sink, ring.label, frame.centerX + r * Math.sin(between) + 2, frame.centerY - r * Math.cos(between), "tick", theme.mutedInk, "left");
  }

  for (const layer of plan.layers) layer.draw(context);

  const plot = RectF.fromCenter({ x: frame.centerX, y: frame.centerY }, radius * 2, radius * 2);
  job.drawLegendAndTitle(plan, cell, plot, legendBox, titleTop);
}

registerCharting({
  train,
  draw(job, plan, cell) {
    if (plan.frame === "polar") drawPolar(job, plan, cell);
    else drawCartesian(job, plan, CartesianFrame.measure(plan, cell, job.theme, job.text, true, true));
  },
});
