// Mind maps (and organisation charts), timelines and boards: the kinds whose lines are a tree of indentation.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Kinds/Trees.cs.

import type { Block, Span } from "../syntax/source";
import { isWhiteSpace } from "../syntax/source";
import { Said, type ProblemList } from "../syntax/problems";
import * as Scan from "../syntax/scan";
import { DiagramSpec, KindParser, registerKind, setting, type BuildContext, type Built, type ReadContext, type Setting } from "../syntax/reader";
import { RectF, VectorPath, vec, type Vec2 } from "../rendering/geometry";
import { Tone } from "../rendering/tones";
import { DiagramLayer, FontWeights, Scene, TextSetter, shapeMark, textBounds, type Mark, type SizeF } from "../rendering/scene";
import * as Shapes from "../rendering/shapes";
import { chartOf } from "../plot/figure";
import type { Theme } from "../plot/theme";
import type { FontWeight, TextMeasurer } from "../plot/text";
import { AttributeWords } from "./attribute-words";
import { typeFor, type TypeSizes } from "../layout/graph-diagram";

// ---------------------------------------------------------------- helpers the C# shares with other kinds

/** Whether a line is a `section` line: the word, then nothing, white space or a colon. */
export function isSectionLine(content: Span): boolean {
  return content.startsWith("section") && (content.length === 7 || isWhiteSpace(content.at(7)) || content.at(7) === ":");
}

const s = (n: number, one = "", many = "s"): string => (n === 1 ? one : many);

// ================================================================ Mind maps

/** A branch of a mind map: its words, its own colour if it says one, and what grows from it. */
export class TreeItem {
  label = "";
  hue: Tone | null = null;
  readonly children: TreeItem[] = [];
  size: SizeF = { width: 0, height: 0 };
  box: RectF = RectF.empty;
  extent = 0;
  branch = 0;
  depth = 0;

  get count(): number {
    return 1 + this.children.reduce((sum, c) => sum + c.count, 0);
  }
}

/** How a mind map spreads from its centre: both - branches to the right and to the left, balanced; right; left; down - a tree hanging down from its root, as an organisation chart. */
export type Spread = "both" | "right" | "left" | "down";

export class MindmapSpec extends DiagramSpec {
  root: TreeItem = new TreeItem();
  spread: Spread = "both";

  override get isEmpty(): boolean {
    return this.root.label.length === 0 && this.root.children.length === 0;
  }

  build(_problems: ProblemList, context: BuildContext): Built {
    const scene = TreeLayout.build(this, this.theme, context.measurer);
    const ideas = this.root.count;
    const branches = this.root.children.length;
    const layer = new DiagramLayer(scene, "Mind map", context.measurer);
    layer.label = this.title;
    return { chart: chartOf(layer), naturalWidth: scene.width, naturalHeight: scene.height, summary: `A mind map of ${ideas} idea${s(ideas)} on ${branches} branch${s(branches, "", "es")}.` };
  }
}

/**
 * A mind map: its centre and the branches indented under it, each line a word or a phrase, a colour in brackets when a branch should stand out.
 */
export class MindmapParser extends KindParser {
  private readonly own: MindmapSpec;
  private readonly roots: Block[] = [];

  constructor(context: ReadContext) {
    super(context);
    this.own = new MindmapSpec(context.kind, context.kindLine);
  }

  get spec(): MindmapSpec {
    return this.own;
  }

  protected override get settings(): Setting[] {
    return [
      setting(["direction", "spread", "layout"], (v) => {
        const spread = this.readChoice<Spread>(
          v,
          "direction",
          [["both", "centre", "center", "radial", "around"], "both"],
          [["right", "lr"], "right"],
          [["left", "rl"], "left"],
          [["down", "tree", "td", "tb", "org", "organisation", "organization"], "down"],
        );
        if (spread !== null) this.own.spread = spread;
      }),
    ];
  }

  protected content(block: Block): void {
    this.roots.push(block);
  }

  protected override finish(): void {
    const spec = this.own;
    if (this.roots.length === 0) {
      spec.root = new TreeItem();
      spec.root.label = spec.title ?? "";
      if (spec.title === null) this.problems.error(this.context.kindLine.content, "NoData");
      return;
    }
    if (this.roots.length === 1) {
      spec.root = this.item(this.roots[0], null, true);
      return;
    }
    if (spec.title !== null) {
      // Several lines at the top under a title: the title is the centre, and the figure does not say it twice.
      spec.root = new TreeItem();
      spec.root.label = spec.title;
      spec.title = null;
      for (const block of this.roots) spec.root.children.push(this.item(block, null));
      return;
    }
    this.problems.warning(this.roots[1].content, "SeveralRoots");
    spec.root = this.item(this.roots[0], null, true);
    for (const block of this.roots.slice(1)) spec.root.children.push(this.item(block, null));
  }

  /** An idea and the ideas under it; a colour it is given is the colour of the ideas under it too, unless they say their own - the centre's is its own alone, since each branch has a colour. */
  private item(block: Block, inherited: Tone | null, isCentre = false): TreeItem {
    const reference = Scan.reference(block.content, this.problems);
    const item = new TreeItem();
    item.label = reference.name;
    for (const attribute of reference.attributes) {
      const hue = AttributeWords.hue(attribute.text);
      if (hue !== null) item.hue = Tone.hue(hue);
      else this.unknownAttribute(attribute, new Said("a branch", "分支"), AttributeWords.names);
    }
    item.hue ??= inherited;
    for (const child of block.children) item.children.push(this.item(child, isCentre ? null : item.hue));
    return item;
  }
}

/**
 * A tree laid out: a mind map's branches spread right and left of its centre, balanced by how much each holds, or hanging down as an organisation chart; each subtree stacked so none overlaps another, each parent centred on its children.
 */
export const TreeLayout = {
  Gap: 34,
  Stack: 10,
  Max: 200,

  build(spec: MindmapSpec, theme: Theme, measurer: TextMeasurer): Scene {
    const text = new TextSetter(theme.fontFamilies, measurer);
    const type = typeFor(theme);
    const scene = new Scene(theme.fontFamilies);
    const root = spec.root;
    measure(root, 0, -1, text, type);

    if (spec.spread === "down") {
      layDown(root, 0, 0);
      draw(root, scene, text, type, true);
      scene.frame(12);
      return scene;
    }

    // Branches to either side, the heavier side first, in the order written; one side only when asked.
    const right: TreeItem[] = [];
    const left: TreeItem[] = [];
    let rightLoad = 0;
    let leftLoad = 0;
    for (const branch of root.children) {
      const load = extent(branch, true);
      let toRight = spec.spread === "right" || (spec.spread === "both" && rightLoad <= leftLoad);
      if (spec.spread === "left") toRight = false;
      (toRight ? right : left).push(branch);
      if (toRight) rightLoad += load + Stack * 2;
      else leftLoad += load + Stack * 2;
    }
    root.box = RectF.fromXYWH(-root.size.width / 2, -root.size.height / 2, root.size.width, root.size.height);
    side(right, root.box.right + Gap * 1.4, +1);
    side(left, root.box.left - Gap * 1.4, -1);
    draw(root, scene, text, type, false);
    scene.frame(12);
    return scene;
  },
};
const { Gap, Stack, Max } = TreeLayout;

function measure(item: TreeItem, depth: number, branch: number, text: TextSetter, type: TypeSizes): void {
  item.depth = depth;
  item.branch = branch;
  const [size, weight, padX, padY] = style(depth, type);
  const label = text.measure(item.label, size, weight, Max);
  item.size = { width: label.width + 2 * padX, height: label.height + 2 * padY };
  for (let i = 0; i < item.children.length; i++) measure(item.children[i], depth + 1, depth === 0 ? i : branch, text, type);
}

function style(depth: number, type: TypeSizes): [size: number, weight: FontWeight, padX: number, padY: number] {
  switch (depth) {
    case 0:
      return [type.label * 1.2, FontWeights.SemiBold, 22, 12];
    case 1:
      return [type.label, FontWeights.SemiBold, 14, 8];
    default:
      return [type.small, FontWeights.Normal, 4, 4];
  }
}

/** How tall (across a horizontal map) or wide (across a hanging one) a subtree is. */
function extent(item: TreeItem, horizontal: boolean): number {
  const own = horizontal ? item.size.height : item.size.width;
  const gap = horizontal ? Stack : Stack * 2;
  const children = item.children.length === 0 ? 0 : item.children.reduce((sum, c) => sum + extent(c, horizontal), 0) + gap * (item.children.length - 1);
  return (item.extent = Math.max(own, children));
}

/** Places one side's branches in a column beside the centre, each subtree as tall as it needs, the column centred on the centre. */
function side(branches: TreeItem[], x: number, sign: number): void {
  if (branches.length === 0) return;
  const total = branches.reduce((sum, b) => sum + b.extent, 0) + Stack * 2 * (branches.length - 1);
  let top = -total / 2;
  for (const branch of branches) {
    placeHorizontal(branch, x, top, sign);
    top += branch.extent + Stack * 2;
  }
}

function placeHorizontal(item: TreeItem, x: number, top: number, sign: number): void {
  const cy = top + item.extent / 2;
  const left = sign > 0 ? x : x - item.size.width;
  item.box = RectF.fromXYWH(left, cy - item.size.height / 2, item.size.width, item.size.height);
  if (item.children.length === 0) return;
  const children = item.children.reduce((sum, c) => sum + c.extent, 0) + Stack * (item.children.length - 1);
  let y = cy - children / 2;
  const next = sign > 0 ? item.box.right + Gap : item.box.left - Gap;
  for (const child of item.children) {
    placeHorizontal(child, next, y, sign);
    y += child.extent + Stack;
  }
}

function layDown(item: TreeItem, left: number, top: number): void {
  extent(item, false);
  place(item, left, top);

  function place(item: TreeItem, left: number, top: number): void {
    const cx = left + item.extent / 2;
    item.box = RectF.fromXYWH(cx - item.size.width / 2, top, item.size.width, item.size.height);
    const children = item.children.reduce((sum, c) => sum + c.extent, 0) + Stack * 2 * (item.children.length - 1);
    let x = cx - children / 2;
    for (const child of item.children) {
      place(child, x, item.box.bottom + Gap * 1.2);
      x += child.extent + Stack * 2;
    }
  }
}

function draw(root: TreeItem, scene: Scene, text: TextSetter, type: TypeSizes, vertical: boolean): void {
  const nodes: Mark[] = [];
  const visit = (item: TreeItem): void => {
    const hue = item.hue ?? (item.depth === 0 ? Tone.hue("accent") : Tone.palette(item.branch < 0 ? 0 : item.branch + 1));
    for (const child of item.children) {
      const childHue = child.hue ?? Tone.palette(child.branch + 1);
      // The line from a parent runs from its edge to the child's near edge - under a leaf, along its foot.
      let from: Vec2;
      let to: Vec2;
      if (vertical) {
        from = vec(item.box.midX, item.box.bottom);
        to = vec(child.box.midX, child.box.top);
      } else {
        const right = child.box.midX > item.box.midX;
        from = vec(right ? item.box.right : item.box.left, item.depth >= 2 ? item.box.bottom : item.box.midY);
        to =
          child.depth >= 2 && child.children.length === 0
            ? vec(right ? child.box.left : child.box.right, child.box.bottom)
            : vec(right ? child.box.left : child.box.right, child.depth >= 2 ? child.box.bottom : child.box.midY);
      }
      const width = item.depth === 0 ? 3 : item.depth === 1 ? 2.2 : 1.5;
      scene.add(shapeMark(Shapes.bump([from, to], vertical), null, childHue.washed(0.85), width));
      if (!vertical && child.depth >= 2) {
        // A leaf stands on a line in its branch's colour.
        const foot = new VectorPath();
        foot.moveTo(child.box.left, child.box.bottom).lineTo(child.box.right, child.box.bottom);
        scene.add(shapeMark(foot, null, childHue.washed(0.85), 1.5));
      }
      visit(child);
    }
    const [size, weight] = style(item.depth, type);
    if (item.depth <= 1 || vertical) {
      const box = new VectorPath();
      const radius = item.depth === 0 ? item.box.height / 2 : 8;
      box.addRoundRect(item.box, radius, radius);
      nodes.push(shapeMark(box, hue.washed(item.depth === 0 ? 0.22 : 0.16), hue.washed(0.9), item.depth === 0 ? 2 : 1.5));
    }
    nodes.push(text.centred(item.label, item.box.midX, item.box.midY, size, weight, Tone.of("ink"), Max));
  };
  visit(root);
  for (const mark of nodes) scene.add(mark);
}

// ================================================================ Timelines

export interface Period {
  readonly label: string;
  readonly events: string[];
  readonly section: number;
  readonly hue: Tone | null;
}

export class TimelineSpec extends DiagramSpec {
  readonly periods: Period[] = [];
  readonly sections: string[] = [];
  vertical = false;

  override get isEmpty(): boolean {
    return this.periods.length === 0;
  }

  build(_problems: ProblemList, context: BuildContext): Built {
    const scene = TimelineLayout.build(this, this.theme, context.measurer);
    const events = this.periods.reduce((sum, p) => sum + p.events.length, 0);
    const n = this.periods.length;
    const layer = new DiagramLayer(scene, "Timeline", context.measurer);
    layer.label = this.title;
    return { chart: chartOf(layer), naturalWidth: scene.width, naturalHeight: scene.height, summary: `A timeline of ${n} time${s(n)} and ${events} event${s(events)}.` };
  }
}

/**
 * A timeline: a time, a colon and what happened then - several events after semicolons or indented under the time - grouped into sections by `section` lines.
 */
export class TimelineParser extends KindParser {
  private readonly own: TimelineSpec;
  private section = -1;

  constructor(context: ReadContext) {
    super(context);
    this.own = new TimelineSpec(context.kind, context.kindLine);
  }

  get spec(): TimelineSpec {
    return this.own;
  }

  protected override get settings(): Setting[] {
    return [
      setting(["direction", "layout"], (v) => {
        const d = this.readDirection(v);
        if (d !== null) this.own.vertical = d === "down" || d === "up";
      }),
    ];
  }

  protected content(block: Block): void {
    const content = block.content;
    if (isSectionLine(content)) {
      let rest = content.from(7).trim();
      if (rest.length > 0 && rest.at(0) === ":") rest = rest.from(1).trim();
      this.own.sections.push(Scan.name(rest, this.problems));
      this.section = this.own.sections.length - 1;
      for (const child of block.children) this.content(child);
      return;
    }
    let { head, tail } = Scan.splitColon(content);
    // A time with its events indented under it is the whole line: 11:00 is a time, not 11 with an event called 00.
    const whole = content.text;
    if (block.children.length > 0 && !whole.includes(": ") && !whole.endsWith(":") && !whole.includes("\uFF1A")) {
      head = content;
      tail = null;
    }
    const time = Scan.reference(head, this.problems);
    if (time.name.length === 0) {
      this.problems.error(content, "EventWithoutTime");
      return;
    }
    let hue: Tone | null = null;
    for (const attribute of time.attributes) {
      const h = AttributeWords.hue(attribute.text);
      if (h !== null) hue = Tone.hue(h);
      else this.unknownAttribute(attribute, new Said("a time", "时间"), AttributeWords.names);
    }
    const events: string[] = [];
    // An event's colour in brackets is its time's: the time is what is marked on the line.
    const event = (piece: Span): void => {
      const said = Scan.reference(piece, this.problems);
      if (said.name.length > 0) events.push(said.name);
      for (const attribute of said.attributes) {
        const h = AttributeWords.hue(attribute.text);
        if (h !== null) hue = Tone.hue(h);
        else this.unknownAttribute(attribute, new Said("a time", "时间"), AttributeWords.names);
      }
    };
    if (tail !== null) for (const piece of Scan.list(tail, ";")) if (!piece.isEmpty) event(piece);
    for (const child of block.children) {
      event(child.content);
      for (const deeper of child.children) this.problems.warning(deeper.content, "IndentedUnderNothing");
    }
    this.own.periods.push({ label: time.name, events, section: this.section, hue });
  }

  protected override finish(): void {
    if (this.own.periods.length === 0) this.problems.error(this.context.kindLine.content, "NoData");
  }
}

/**
 * A timeline laid out: the times evenly along a line, each a coloured mark with its events as cards beyond it, sections as bands over the times they hold.
 */
export const TimelineLayout = {
  CardWidth: 150,
  Gap: 18,

  build(spec: TimelineSpec, theme: Theme, measurer: TextMeasurer): Scene {
    const { CardWidth, Gap } = TimelineLayout;
    const text = new TextSetter(theme.fontFamilies, measurer);
    const type = typeFor(theme);
    const scene = new Scene(theme.fontFamilies);
    const n = spec.periods.length;
    if (n === 0) {
      scene.add(text.mark(" ", 0, 0, type.small, FontWeights.Normal, Tone.of("muted")));
      scene.frame(12);
      return scene;
    }
    const hueOf = (p: Period, index: number): Tone => p.hue ?? Tone.palette(spec.sections.length > 0 && p.section >= 0 ? p.section : index);

    if (spec.vertical) {
      // Down the page: the line at the left, each time beside it, its events to the right.
      let y = 0;
      const labelWidth = Math.max(...spec.periods.map((p) => text.measure(p.label, type.label, FontWeights.SemiBold).width)) + 24;
      const axisX = labelWidth + 14;
      const cards: Mark[] = [];
      let lastSection = -1;
      for (let i = 0; i < n; i++) {
        const p = spec.periods[i];
        if (p.section !== lastSection && p.section >= 0) {
          cards.push(text.mark(spec.sections[p.section], axisX + 22, y, type.small, FontWeights.SemiBold, Tone.palette(p.section).washed(0.9)));
          y += text.measure("Ag", type.small, FontWeights.SemiBold).height + 8;
          lastSection = p.section;
        }
        const hue = hueOf(p, i);
        const label = text.mark(p.label, 0, y, type.label, FontWeights.SemiBold, Tone.of("ink"));
        cards.push({ ...label, x: axisX - 16 - label.width });
        const dot = new VectorPath();
        dot.addCircle(axisX, y + label.height / 2, 6);
        cards.push(shapeMark(dot, hue, Tone.of("background"), 2));
        let cardY = y;
        for (const e of p.events) {
          const words = text.mark(e, axisX + 30, cardY + 6, type.small, FontWeights.Normal, Tone.of("ink"), CardWidth * 1.6);
          const box = RectF.fromXYWH(axisX + 22, cardY, words.width + 16, words.height + 12);
          const card = new VectorPath();
          card.addRoundRect(box, 6, 6);
          cards.push(shapeMark(card, hue.washed(0.12), hue.washed(0.6), 1.2));
          cards.push(words);
          cardY += box.height + 6;
        }
        y = Math.max(y + label.height, cardY) + Gap;
      }
      const spine = new VectorPath();
      spine.moveTo(axisX, -6).lineTo(axisX, y);
      scene.add(shapeMark(spine, null, Tone.of("axis"), 2));
      for (const mark of cards) scene.add(mark);
      scene.frame(12);
      return scene;
    }

    // Across the page: a column per time, as wide as its widest card.
    const widths: number[] = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
      const p = spec.periods[i];
      let w = text.measure(p.label, type.label, FontWeights.SemiBold).width + 24;
      for (const e of p.events) w = Math.max(w, text.measure(e, type.small, FontWeights.Normal, CardWidth).width + 16);
      widths[i] = Math.max(w, 92);
    }
    const sectionRow = spec.sections.length > 0 ? text.measure("Ag", type.small, FontWeights.SemiBold).height + 16 : 0;
    const labelRow = Math.max(...spec.periods.map((p) => text.measure(p.label, type.label, FontWeights.SemiBold).height)) + 14;
    const axisY = sectionRow + labelRow + 14;
    let x = 0;
    const centre: number[] = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
      centre[i] = x + widths[i] / 2;
      x += widths[i] + Gap;
    }
    const right = x - Gap;
    const marks: Mark[] = [];
    // Sections: a band over their times, named at its left.
    for (let section = 0; section < spec.sections.length; section++) {
      const members = [...Array(n).keys()].filter((i) => spec.periods[i].section === section);
      if (members.length === 0) continue;
      const first = members[0];
      const last = members[members.length - 1];
      const left = centre[first] - widths[first] / 2 - Gap / 3;
      const end = centre[last] + widths[last] / 2 + Gap / 3;
      const band = new VectorPath();
      band.addRoundRect(new RectF(left, 0, end, sectionRow - 6), 6, 6);
      marks.push(shapeMark(band, Tone.palette(section).washed(0.16), null, 0));
      marks.push(text.centred(spec.sections[section], (left + end) / 2, (sectionRow - 6) / 2, type.small, FontWeights.SemiBold, Tone.of("ink")));
    }
    const axis = new VectorPath();
    axis.moveTo(-8, axisY).lineTo(right + 8, axisY);
    scene.add(shapeMark(axis, null, Tone.of("axis"), 2));
    const head = Shapes.end("arrow", vec(right + 18, axisY), vec(1, 0), 9);
    if (head !== null) scene.add(shapeMark(head.path, Tone.of("axis"), null, 0));
    for (let i = 0; i < n; i++) {
      const p = spec.periods[i];
      const hue = hueOf(p, i);
      const label = text.centred(p.label, centre[i], sectionRow + labelRow / 2 - 2, type.label, FontWeights.SemiBold, Tone.of("ink"));
      const pill = new VectorPath();
      pill.addRoundRect(textBounds(label).inflate(10, 4), label.height / 2 + 4, label.height / 2 + 4);
      marks.push(shapeMark(pill, hue.washed(0.2), hue.washed(0.9), 1.4));
      marks.push(label);
      const dot = new VectorPath();
      dot.addCircle(centre[i], axisY, 6);
      marks.push(shapeMark(dot, hue, Tone.of("background"), 2));
      let y = axisY + 22;
      if (p.events.length > 0) {
        const stem = new VectorPath();
        stem.moveTo(centre[i], axisY + 6).lineTo(centre[i], y);
        marks.push(shapeMark(stem, null, hue.washed(0.6), 1.2));
      }
      for (const e of p.events) {
        const words = text.centred(e, centre[i], 0, type.small, FontWeights.Normal, Tone.of("ink"), CardWidth);
        const cardWidth = widths[i] - 4;
        const box = RectF.fromXYWH(centre[i] - cardWidth / 2, y, cardWidth, words.height + 12);
        const card = new VectorPath();
        card.addRoundRect(box, 6, 6);
        marks.push(shapeMark(card, hue.washed(0.1), hue.washed(0.55), 1.1));
        marks.push({ ...words, y: y + 6 });
        y += box.height + 7;
      }
    }
    for (const mark of marks) scene.add(mark);
    scene.frame(12);
    return scene;
  },
};

// ================================================================ Boards

export interface Card {
  readonly text: string;
  readonly hue: Tone | null;
}

export interface Column {
  readonly name: string;
  readonly hue: Tone | null;
  readonly cards: Card[];
}

export class KanbanSpec extends DiagramSpec {
  readonly columns: Column[] = [];

  override get isEmpty(): boolean {
    return this.columns.length === 0;
  }

  build(_problems: ProblemList, context: BuildContext): Built {
    const scene = BoardLayout.build(this, this.theme, context.measurer);
    const cards = this.columns.reduce((sum, c) => sum + c.cards.length, 0);
    const n = this.columns.length;
    const layer = new DiagramLayer(scene, "Board", context.measurer);
    layer.label = this.title;
    return { chart: chartOf(layer), naturalWidth: scene.width, naturalHeight: scene.height, summary: `A board of ${n} column${s(n)} and ${cards} card${s(cards)}.` };
  }
}

/** A board: its columns at the top, the cards in each indented under it. */
export class KanbanParser extends KindParser {
  private readonly own: KanbanSpec;

  constructor(context: ReadContext) {
    super(context);
    this.own = new KanbanSpec(context.kind, context.kindLine);
  }

  get spec(): KanbanSpec {
    return this.own;
  }

  protected content(block: Block): void {
    const column = Scan.reference(block.content, this.problems);
    const made: Column = { name: column.name, hue: this.hue(column, "a column"), cards: [] };
    for (const child of block.children) {
      const card = Scan.reference(child.content, this.problems);
      made.cards.push({ text: card.name, hue: this.hue(card, "a card") });
      for (const deeper of child.children) {
        const more = Scan.reference(deeper.content, this.problems);
        made.cards.push({ text: more.name, hue: this.hue(more, "a card") });
      }
    }
    this.own.columns.push(made);
  }

  private hue(reference: Scan.Ref, what: string): Tone | null {
    let hue: Tone | null = null;
    for (const attribute of reference.attributes) {
      const h = AttributeWords.hue(attribute.text);
      if (h !== null) hue = Tone.hue(h);
      else this.unknownAttribute(attribute, new Said(what, what === "a card" ? "卡片" : "列"), AttributeWords.names);
    }
    return hue;
  }

  protected override finish(): void {
    if (this.own.columns.length === 0) this.problems.error(this.context.kindLine.content, "NoData");
  }
}

/** A board laid out: columns side by side, each headed by its name and how many cards it holds, its cards stacked under it with a stripe of their colour. */
export const BoardLayout = {
  Width: 196,
  Gap: 14,
  Pad: 10,

  build(spec: KanbanSpec, theme: Theme, measurer: TextMeasurer): Scene {
    const { Width, Gap, Pad } = BoardLayout;
    const text = new TextSetter(theme.fontFamilies, measurer);
    const type = typeFor(theme);
    const scene = new Scene(theme.fontFamilies);
    let x = 0;
    let tallest = 0;
    const columns: { x: number; height: number; column: Column; index: number }[] = [];
    const marks: Mark[] = [];
    for (let c = 0; c < spec.columns.length; c++) {
      const column = spec.columns[c];
      const hue = column.hue ?? Tone.palette(c);
      let y = 0;
      const name = text.mark(column.name, x + Pad + 4, y + Pad, type.label, FontWeights.SemiBold, Tone.of("ink"), Width - 60);
      const count = text.mark(String(column.cards.length), 0, y + Pad, type.small, FontWeights.SemiBold, Tone.of("secondary"));
      marks.push(name);
      const badge = new VectorPath();
      const badgeBox = RectF.fromXYWH(x + Width - Pad - count.width - 12, y + Pad + (name.height - count.height) / 2 - 2, count.width + 12, count.height + 4);
      badge.addRoundRect(badgeBox, badgeBox.height / 2, badgeBox.height / 2);
      marks.push(shapeMark(badge, hue.washed(0.2), null, 0));
      marks.push({ ...count, x: badgeBox.left + 6, y: badgeBox.top + 2 });
      y += Pad + name.height + 10;
      for (const card of column.cards) {
        const words = text.mark(card.text, x + Pad + 12, y + 8, type.small, FontWeights.Normal, Tone.of("ink"), Width - 2 * Pad - 22);
        const box = RectF.fromXYWH(x + Pad, y, Width - 2 * Pad, words.height + 16);
        const outline = new VectorPath();
        outline.addRoundRect(box, 6, 6);
        marks.push(shapeMark(outline, Tone.of("background"), Tone.of("grid"), 1.2));
        const stripe = new VectorPath();
        stripe.addRoundRect(RectF.fromXYWH(box.left + 3, box.top + 4, 4, box.height - 8), 2, 2);
        marks.push(shapeMark(stripe, card.hue ?? hue, null, 0));
        marks.push(words);
        y += box.height + 8;
      }
      y += Pad - 8 + (column.cards.length === 0 ? 24 : 0);
      columns.push({ x, height: y, column, index: c });
      tallest = Math.max(tallest, y);
      x += Width + Gap;
    }
    for (const { x: cx, column, index } of columns) {
      const lane = new VectorPath();
      lane.addRoundRect(RectF.fromXYWH(cx, 0, Width, tallest), 10, 10);
      scene.add(shapeMark(lane, (column.hue ?? Tone.palette(index)).washed(0.07), null, 0));
    }
    for (const mark of marks) scene.add(mark);
    scene.frame(12);
    return scene;
  },
};

