// Points, rectangles and paths, in a figure's pixels: what Divooka's canvas (Divooka.Graphics.Canvas) gives the C# Dhole, as
// much of it as Dhole draws with.

export interface Vec2 {
  readonly x: number;
  readonly y: number;
}

export function vec(x: number, y: number): Vec2 {
  return { x, y };
}
export const add = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x + b.x, y: a.y + b.y });
export const sub = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x - b.x, y: a.y - b.y });
export const mul = (a: Vec2, k: number): Vec2 => ({ x: a.x * k, y: a.y * k });
export const lengthSquared = (a: Vec2): number => a.x * a.x + a.y * a.y;
export const length = (a: Vec2): number => Math.sqrt(lengthSquared(a));
export function normalize(a: Vec2): Vec2 {
  const l = length(a);
  return l === 0 ? { x: Number.NaN, y: Number.NaN } : { x: a.x / l, y: a.y / l };
}
export const distance = (a: Vec2, b: Vec2): number => length(sub(a, b));

/** A rectangle by its edges. */
export class RectF {
  readonly left: number;
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  constructor(left: number, top: number, right: number, bottom: number) {
    this.left = left;
    this.top = top;
    this.right = right;
    this.bottom = bottom;
  }
  static fromXYWH(x: number, y: number, width: number, height: number): RectF {
    return new RectF(x, y, x + width, y + height);
  }
  static fromCenter(center: Vec2, width: number, height: number): RectF {
    return new RectF(center.x - width / 2, center.y - height / 2, center.x + width / 2, center.y + height / 2);
  }
  static readonly empty = new RectF(0, 0, 0, 0);
  get width(): number {
    return this.right - this.left;
  }
  get height(): number {
    return this.bottom - this.top;
  }
  get midX(): number {
    return (this.left + this.right) / 2;
  }
  get midY(): number {
    return (this.top + this.bottom) / 2;
  }
  get center(): Vec2 {
    return { x: this.midX, y: this.midY };
  }
  get isEmpty(): boolean {
    return !(this.right > this.left && this.bottom > this.top);
  }
  inflate(dx: number, dy: number = dx): RectF {
    return new RectF(this.left - dx, this.top - dy, this.right + dx, this.bottom + dy);
  }
  offset(dx: number, dy: number): RectF {
    return new RectF(this.left + dx, this.top + dy, this.right + dx, this.bottom + dy);
  }
  contains(p: Vec2): boolean {
    return p.x >= this.left && p.x < this.right && p.y >= this.top && p.y < this.bottom;
  }
  intersectsWith(other: RectF): boolean {
    return this.left < other.right && other.left < this.right && this.top < other.bottom && other.top < this.bottom;
  }
  union(other: RectF): RectF {
    return new RectF(Math.min(this.left, other.left), Math.min(this.top, other.top), Math.max(this.right, other.right), Math.max(this.bottom, other.bottom));
  }
  toString(): string {
    return `(${this.left}, ${this.top}, ${this.right}, ${this.bottom})`;
  }
}

/** A 2D affine transform: x' = a x + c y + e, y' = b x + d y + f. */
export interface Matrix {
  readonly a: number;
  readonly b: number;
  readonly c: number;
  readonly d: number;
  readonly e: number;
  readonly f: number;
}

export const identity: Matrix = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 };
export function translation(dx: number, dy: number): Matrix {
  return { a: 1, b: 0, c: 0, d: 1, e: dx, f: dy };
}
export function scaling(sx: number, sy: number = sx): Matrix {
  return { a: sx, b: 0, c: 0, d: sy, e: 0, f: 0 };
}
/** A rotation by `degrees`, clockwise on a page whose y runs down, about (cx, cy). */
export function rotationDegrees(degrees: number, cx = 0, cy = 0): Matrix {
  const r = (degrees * Math.PI) / 180;
  const cos = Math.cos(r);
  const sin = Math.sin(r);
  return { a: cos, b: sin, c: -sin, d: cos, e: cx - cos * cx + sin * cy, f: cy - sin * cx - cos * cy };
}
/** `first` then `second`. */
export function multiply(first: Matrix, second: Matrix): Matrix {
  return {
    a: second.a * first.a + second.c * first.b,
    b: second.b * first.a + second.d * first.b,
    c: second.a * first.c + second.c * first.d,
    d: second.b * first.c + second.d * first.d,
    e: second.a * first.e + second.c * first.f + second.e,
    f: second.b * first.e + second.d * first.f + second.f,
  };
}
export function apply(m: Matrix, p: Vec2): Vec2 {
  return { x: m.a * p.x + m.c * p.y + m.e, y: m.b * p.x + m.d * p.y + m.f };
}
export function isIdentity(m: Matrix): boolean {
  return m.a === 1 && m.b === 0 && m.c === 0 && m.d === 1 && m.e === 0 && m.f === 0;
}

type Segment =
  | { readonly kind: "M"; readonly p: Vec2 }
  | { readonly kind: "L"; readonly p: Vec2 }
  | { readonly kind: "C"; readonly c1: Vec2; readonly c2: Vec2; readonly p: Vec2 }
  | { readonly kind: "Z" };

/** An outline of straight and curved pieces, in one or more figures. Arcs and quadratics are kept as cubics. */
export class VectorPath {
  private readonly segments: Segment[] = [];
  private current: Vec2 = { x: 0, y: 0 };
  private start: Vec2 = { x: 0, y: 0 };
  private open = false;

  get isEmpty(): boolean {
    return this.segments.length === 0;
  }

  moveTo(x: number | Vec2, y?: number): this {
    const p = typeof x === "number" ? { x, y: y as number } : x;
    this.segments.push({ kind: "M", p });
    this.current = p;
    this.start = p;
    this.open = true;
    return this;
  }
  lineTo(x: number | Vec2, y?: number): this {
    const p = typeof x === "number" ? { x, y: y as number } : x;
    if (!this.open) this.moveTo(this.current);
    this.segments.push({ kind: "L", p });
    this.current = p;
    return this;
  }
  cubicTo(c1: Vec2, c2: Vec2, p: Vec2): this {
    if (!this.open) this.moveTo(this.current);
    this.segments.push({ kind: "C", c1, c2, p });
    this.current = p;
    return this;
  }
  quadTo(c: Vec2, p: Vec2): this {
    const from = this.current;
    return this.cubicTo(add(from, mul(sub(c, from), 2 / 3)), add(p, mul(sub(c, p), 2 / 3)), p);
  }
  close(): this {
    if (this.open) {
      this.segments.push({ kind: "Z" });
      this.current = this.start;
      this.open = false;
    }
    return this;
  }

  /**
   * An arc of the ellipse inscribed in `oval`, from `startAngle` through `sweepAngle` degrees - clockwise on a page whose y runs
   * down - joined to the current point by a line unless `forceMoveTo`, as Skia's arcTo draws one.
   */
  arcTo(oval: RectF, startAngle: number, sweepAngle: number, forceMoveTo: boolean): this {
    const cx = oval.midX;
    const cy = oval.midY;
    const rx = oval.width / 2;
    const ry = oval.height / 2;
    const point = (deg: number): Vec2 => {
      const r = (deg * Math.PI) / 180;
      return { x: cx + rx * Math.cos(r), y: cy + ry * Math.sin(r) };
    };
    const first = point(startAngle);
    if (forceMoveTo || !this.open) this.moveTo(first);
    else this.lineTo(first);
    const pieces = Math.max(1, Math.ceil(Math.abs(sweepAngle) / 90 - 1e-9));
    const step = sweepAngle / pieces;
    for (let i = 0; i < pieces; i++) {
      const a0 = ((startAngle + step * i) * Math.PI) / 180;
      const a1 = ((startAngle + step * (i + 1)) * Math.PI) / 180;
      const k = (4 / 3) * Math.tan((a1 - a0) / 4);
      const p0 = { x: cx + rx * Math.cos(a0), y: cy + ry * Math.sin(a0) };
      const p1 = { x: cx + rx * Math.cos(a1), y: cy + ry * Math.sin(a1) };
      const c1 = { x: p0.x - k * rx * Math.sin(a0), y: p0.y + k * ry * Math.cos(a0) };
      const c2 = { x: p1.x + k * rx * Math.sin(a1), y: p1.y - k * ry * Math.cos(a1) };
      this.cubicTo(c1, c2, p1);
    }
    return this;
  }

  addRect(r: RectF): this {
    return this.moveTo(r.left, r.top).lineTo(r.right, r.top).lineTo(r.right, r.bottom).lineTo(r.left, r.bottom).close();
  }
  addRoundRect(r: RectF, rx: number, ry: number = rx): this {
    rx = Math.max(0, Math.min(rx, r.width / 2));
    ry = Math.max(0, Math.min(ry, r.height / 2));
    if (rx <= 0 || ry <= 0) return this.addRect(r);
    this.moveTo(r.left + rx, r.top);
    this.lineTo(r.right - rx, r.top);
    this.arcTo(new RectF(r.right - 2 * rx, r.top, r.right, r.top + 2 * ry), 270, 90, false);
    this.lineTo(r.right, r.bottom - ry);
    this.arcTo(new RectF(r.right - 2 * rx, r.bottom - 2 * ry, r.right, r.bottom), 0, 90, false);
    this.lineTo(r.left + rx, r.bottom);
    this.arcTo(new RectF(r.left, r.bottom - 2 * ry, r.left + 2 * rx, r.bottom), 90, 90, false);
    this.lineTo(r.left, r.top + ry);
    this.arcTo(new RectF(r.left, r.top, r.left + 2 * rx, r.top + 2 * ry), 180, 90, false);
    return this.close();
  }
  addOval(r: RectF): this {
    this.arcTo(r, 0, 360, true);
    return this.close();
  }
  addCircle(cx: number, cy: number, radius: number): this {
    return this.addOval(new RectF(cx - radius, cy - radius, cx + radius, cy + radius));
  }
  /** Another path's figures, after this one's. */
  addPath(other: VectorPath): this {
    for (const s of other.segments) this.segments.push(s);
    this.current = other.current;
    this.start = other.start;
    this.open = other.open;
    return this;
  }

  /** The path moved by a transform. */
  transformed(m: Matrix): VectorPath {
    const copy = new VectorPath();
    for (const s of this.segments) {
      switch (s.kind) {
        case "M":
          copy.segments.push({ kind: "M", p: apply(m, s.p) });
          break;
        case "L":
          copy.segments.push({ kind: "L", p: apply(m, s.p) });
          break;
        case "C":
          copy.segments.push({ kind: "C", c1: apply(m, s.c1), c2: apply(m, s.c2), p: apply(m, s.p) });
          break;
        default:
          copy.segments.push(s);
      }
    }
    copy.current = apply(m, this.current);
    copy.start = apply(m, this.start);
    copy.open = this.open;
    return copy;
  }

  /** The smallest rectangle the outline lies in, curves measured at their extremes rather than their handles. */
  tightBounds(): RectF {
    let left = Infinity;
    let top = Infinity;
    let right = -Infinity;
    let bottom = -Infinity;
    const take = (p: Vec2) => {
      left = Math.min(left, p.x);
      top = Math.min(top, p.y);
      right = Math.max(right, p.x);
      bottom = Math.max(bottom, p.y);
    };
    let from: Vec2 = { x: 0, y: 0 };
    let figureStart: Vec2 = from;
    for (const s of this.segments) {
      if (s.kind === "M") {
        take(s.p);
        from = s.p;
        figureStart = s.p;
      } else if (s.kind === "L") {
        take(s.p);
        from = s.p;
      } else if (s.kind === "C") {
        take(s.p);
        for (const t of cubicExtrema(from.x, s.c1.x, s.c2.x, s.p.x).concat(cubicExtrema(from.y, s.c1.y, s.c2.y, s.p.y))) take(cubicAt(from, s.c1, s.c2, s.p, t));
        from = s.p;
      } else from = figureStart;
    }
    return left > right ? RectF.empty : new RectF(left, top, right, bottom);
  }

  /** The path as SVG's d attribute. */
  toSvg(): string {
    const n = (v: number) => fmt(v);
    const parts: string[] = [];
    for (const s of this.segments) {
      switch (s.kind) {
        case "M":
          parts.push(`M${n(s.p.x)},${n(s.p.y)}`);
          break;
        case "L":
          parts.push(`L${n(s.p.x)},${n(s.p.y)}`);
          break;
        case "C":
          parts.push(`C${n(s.c1.x)},${n(s.c1.y)} ${n(s.c2.x)},${n(s.c2.y)} ${n(s.p.x)},${n(s.p.y)}`);
          break;
        default:
          parts.push("Z");
      }
    }
    return parts.join(" ");
  }

  /** The points the path passes through, curves flattened: what a test checks a line's ends and course by. */
  points(stepsPerCurve = 8): Vec2[] {
    const out: Vec2[] = [];
    let from: Vec2 = { x: 0, y: 0 };
    let figureStart = from;
    for (const s of this.segments) {
      if (s.kind === "M" || s.kind === "L") {
        out.push(s.p);
        from = s.p;
        if (s.kind === "M") figureStart = s.p;
      } else if (s.kind === "C") {
        for (let i = 1; i <= stepsPerCurve; i++) out.push(cubicAt(from, s.c1, s.c2, s.p, i / stepsPerCurve));
        from = s.p;
      } else {
        out.push(figureStart);
        from = figureStart;
      }
    }
    return out;
  }
}

/** A number as a picture's coordinates are written: at most four decimals. */
export function fmt(v: number): string {
  const r = Math.round(v * 10000) / 10000;
  return (Object.is(r, -0) ? 0 : r).toString();
}

function cubicAt(p0: Vec2, p1: Vec2, p2: Vec2, p3: Vec2, t: number): Vec2 {
  const u = 1 - t;
  return {
    x: u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x + t * t * t * p3.x,
    y: u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y + t * t * t * p3.y,
  };
}

function cubicExtrema(a: number, b: number, c: number, d: number): number[] {
  // Derivative: 3[(b-a)(1-t)^2 + 2(c-b)t(1-t) + (d-c)t^2] = 0 → At^2 + Bt + C = 0.
  const A = -a + 3 * b - 3 * c + d;
  const B = 2 * (a - 2 * b + c);
  const C = b - a;
  const roots: number[] = [];
  if (Math.abs(A) < 1e-12) {
    if (Math.abs(B) > 1e-12) roots.push(-C / B);
  } else {
    const disc = B * B - 4 * A * C;
    if (disc >= 0) {
      const s = Math.sqrt(disc);
      roots.push((-B + s) / (2 * A), (-B - s) / (2 * A));
    }
  }
  return roots.filter((t) => t > 0 && t < 1);
}
