// The D3 time scale a Gantt chart is drawn on - d3.scaleUtc: a linear scale over dates with calendar-aware ticks and the multi-scale tick format - as much of it as Dhole uses.
// Ported from Parcel NExT's Divooka.Graphics.Canvas.D3: Scales/TimeScale.cs, Time/TimeTicks.cs, Time/TimeInterval.cs, Time/TimeInterval.Statics.cs, TimeFormat/TimeFormatter.cs, TimeFormat/TimeFormatLocale.cs (formatting), Arrays/Sequence.Ticks.cs (tickStep), Arrays/Sequence.Search.cs (bisectRight), Scales/ContinuousScale.cs (the bimap) and Interpolate/Interpolators.cs (number).
//
// A date here is what C#'s DateTime is to the D3 port: milliseconds since 1970-01-01 in UTC, read by calendar fields and never through the local time zone. The C# DateTime counts 100-nanosecond ticks; every date Dhole makes is whole milliseconds, so nothing is lost.

const DurationSecond = 1000;
const DurationMinute = DurationSecond * 60;
const DurationHour = DurationMinute * 60;
const DurationDay = DurationHour * 24;
const DurationWeek = DurationDay * 7;
const DurationMonth = DurationDay * 30;
const DurationYear = DurationDay * 365;

// ---------------------------------------------------------------- calendar fields of a UTC date

/** The UTC date of a year, a zero-based month and a day - with JavaScript's overflow, and years below 100 kept as written. */
export function utcDate(year: number, month0: number, day = 1, hour = 0, minute = 0, second = 0, millisecond = 0): number {
  const date = new Date(0);
  date.setUTCFullYear(year, month0, day);
  date.setUTCHours(hour, minute, second, millisecond);
  return date.getTime();
}
const year = (ms: number): number => new Date(ms).getUTCFullYear();
const month = (ms: number): number => new Date(ms).getUTCMonth() + 1;
const day = (ms: number): number => new Date(ms).getUTCDate();
const hour = (ms: number): number => new Date(ms).getUTCHours();
const minute = (ms: number): number => new Date(ms).getUTCMinutes();
const second = (ms: number): number => new Date(ms).getUTCSeconds();
const millisecond = (ms: number): number => new Date(ms).getUTCMilliseconds();
/** The day of the week, Sunday 0 - DateTime.DayOfWeek. */
export function dayOfWeek(ms: number): number {
  return new Date(ms).getUTCDay();
}
/** The date at midnight - DateTime.Date. */
export function dateOf(ms: number): number {
  return Math.floor(ms / DurationDay) * DurationDay;
}
/** The time since midnight - DateTime.TimeOfDay. */
export function timeOfDay(ms: number): number {
  return ms - dateOf(ms);
}
function truncateTo(ms: number, unit: number): number {
  return ms - mod(ms, unit);
}
function mod(a: number, b: number): number {
  return ((a % b) + b) % b;
}

/** JavaScript setMonth semantics: day-of-month overflow rolls into the next month. */
function addMonthsJs(date: number, months: number): number {
  const zeroBased = year(date) * 12 + month(date) - 1 + months;
  const y = Math.trunc(zeroBased / 12);
  const m = zeroBased - y * 12;
  return utcDate(y, m, 1) + (day(date) - 1) * DurationDay + timeOfDay(date);
}

/** JavaScript setFullYear semantics: Feb 29 rolls to Mar 1 in a non-leap year. */
function addYearsJs(date: number, years: number): number {
  return utcDate(year(date) + years, month(date) - 1, 1) + (day(date) - 1) * DurationDay + timeOfDay(date);
}

/** C#'s Math.Round: to the nearest whole number, halves to the even one. */
function roundHalfEven(x: number): number {
  const r = Math.round(x);
  return Math.abs(x % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
}

// ---------------------------------------------------------------- intervals

/**
 * A calendar-aware time interval with d3-time's algebra: floor, ceil, offset, range, count, every, and filter.
 *
 * C# adaptation of d3's local/UTC split: every interval here is the UTC one, since a date is UTC milliseconds; the local ones the C# keeps differ only in the kind they stamp on a DateTime.
 */
export class TimeInterval {
  /** A replacement for every(), for the intervals d3 gives their own. */
  everyOverride: ((step: number) => TimeInterval | null) | null = null;

  constructor(
    private readonly floorOf: (date: number) => number,
    private readonly offsetOf: (date: number, step: number) => number,
    private readonly countOf: ((start: number, end: number) => number) | null = null,
    private readonly field: ((date: number) => number) | null = null,
  ) {}

  /** The latest interval boundary at or before the date. */
  floor(date: number): number {
    return this.floorOf(date);
  }

  /** The earliest interval boundary at or after the date. */
  ceil(date: number): number {
    let d = this.floorOf(date - 1);
    d = this.offsetOf(d, 1);
    return this.floorOf(d);
  }

  /** The date advanced by step intervals (which may be negative); no rounding. */
  offset(date: number, step = 1): number {
    return this.offsetOf(date, step);
  }

  /** Every boundary in [start, stop), stepping by the given whole number of intervals - interval.range. */
  range(start: number, stop: number, step = 1): number[] {
    const range: number[] = [];
    start = this.ceil(start);
    if (!(start < stop) || step <= 0) return range;
    let previous: number;
    do {
      previous = start;
      range.push(previous);
      start = this.floorOf(this.offsetOf(start, step));
    } while (previous < start && start < stop);
    return range;
  }

  /** A new interval holding only boundaries that pass the test - interval.filter. */
  filter(test: (date: number) => boolean): TimeInterval {
    return new TimeInterval(
      (date) => {
        for (;;) {
          date = this.floorOf(date);
          if (test(date)) return date;
          date -= 1;
        }
      },
      (date, step) => {
        if (step < 0) {
          while (++step <= 0)
            do date = this.offsetOf(date, -1);
            while (!test(date));
        } else {
          while (--step >= 0)
            do date = this.offsetOf(date, 1);
            while (!test(date));
        }
        return date;
      },
    );
  }

  /** The number of boundaries after start and at or before end - interval.count. */
  count(start: number, end: number): number {
    if (this.countOf === null) throw new Error("This derived interval does not support counting.");
    return Math.floor(this.countOf(this.floorOf(start), this.floorOf(end)));
  }

  /** A filtered interval keeping every step-th boundary, aligned on the interval's natural field (e.g. every 3 months lands on Jan/Apr/Jul/Oct) - interval.every. Null when step is not a positive finite number. */
  every(step: number): TimeInterval | null {
    if (this.everyOverride !== null) return this.everyOverride(step);
    step = Math.floor(step);
    if (!Number.isFinite(step) || !(step > 0)) return null;
    if (!(step > 1)) return this;
    if (this.countOf === null) return null;
    const field = this.field;
    return this.filter(field !== null ? (d) => field(d) % step === 0 : (d) => this.count(0, d) % step === 0);
  }

  /** Milliseconds - the atomic interval; floor is the identity. */
  static readonly millisecond: TimeInterval = (() => {
    const interval = new TimeInterval(
      (date) => date,
      (date, step) => date + step,
      (start, end) => end - start,
    );
    interval.everyOverride = (k) => {
      k = Math.floor(k);
      if (!Number.isFinite(k) || !(k > 0)) return null;
      if (!(k > 1)) return interval;
      return new TimeInterval(
        (date) => Math.floor(date / k) * k,
        (date, step) => date + step * k,
        (start, end) => (end - start) / k,
      );
    };
    return interval;
  })();

  /** Seconds (both local and UTC, like d3's shared second interval). */
  static readonly second = new TimeInterval(
    (date) => truncateTo(date, DurationSecond),
    (date, step) => date + step * DurationSecond,
    (start, end) => (end - start) / DurationSecond,
    (date) => second(date),
  );

  /** UTC minutes. */
  static readonly utcMinute = new TimeInterval(
    (date) => truncateTo(date, DurationMinute),
    (date, step) => date + step * DurationMinute,
    (start, end) => (end - start) / DurationMinute,
    (date) => minute(date),
  );

  /** UTC hours. */
  static readonly utcHour = new TimeInterval(
    (date) => truncateTo(date, DurationHour),
    (date, step) => date + step * DurationHour,
    (start, end) => (end - start) / DurationHour,
    (date) => hour(date),
  );

  /** UTC calendar days. */
  static readonly utcDay = TimeInterval.makeDay((date) => day(date) - 1);

  /** UTC days aligned to the Unix epoch (field is epoch day number) - d3's unixDay. */
  static readonly unixDay = TimeInterval.makeDay((date) => Math.floor(date / DurationDay));

  private static makeDay(field: (date: number) => number): TimeInterval {
    return new TimeInterval(
      (date) => dateOf(date),
      (date, step) => date + step * DurationDay,
      (start, end) => (end - start) / DurationDay,
      field,
    );
  }

  private static weekday(i: number): TimeInterval {
    return new TimeInterval(
      (date) => dateOf(date) - ((dayOfWeek(date) + 7 - i) % 7) * DurationDay,
      (date, step) => date + step * 7 * DurationDay,
      (start, end) => (end - start) / DurationWeek,
    );
  }

  static readonly utcSunday = TimeInterval.weekday(0);
  static readonly utcMonday = TimeInterval.weekday(1);
  static readonly utcThursday = TimeInterval.weekday(4);

  /** UTC calendar months. */
  static readonly utcMonth = new TimeInterval(
    (date) => utcDate(year(date), month(date) - 1, 1),
    (date, step) => addMonthsJs(date, step),
    (start, end) => month(end) - month(start) + (year(end) - year(start)) * 12,
    (date) => month(date) - 1, // d3's getMonth is zero-based.
  );

  /** UTC calendar years. */
  static readonly utcYear: TimeInterval = (() => {
    const interval = new TimeInterval(
      (date) => utcDate(year(date), 0, 1),
      (date, step) => addYearsJs(date, step),
      (start, end) => year(end) - year(start),
      (date) => year(date),
    );
    interval.everyOverride = (k) => {
      k = Math.floor(k);
      if (!Number.isFinite(k) || !(k > 0)) return null;
      return new TimeInterval(
        (date) => utcDate(Math.max(1, Math.trunc(year(date) / k) * k), 0, 1),
        (date, step) => addYearsJs(date, step * k),
      );
    };
    return interval;
  })();
}

// ---------------------------------------------------------------- ticks

/** Insertion point for x in sorted values, after (to the right of) any equal values - d3.bisectRight. */
function bisectRight(values: readonly number[], x: number, lo = 0, hi = values.length): number {
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (values[mid] <= x) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

const e10 = Math.sqrt(50);
const e5 = Math.sqrt(10);
const e2 = Math.sqrt(2);

function tickSpec(start: number, stop: number, count: number): [number, number, number] {
  const step = (stop - start) / Math.max(0, count);
  const power = Math.floor(Math.log10(step));
  const error = step / Math.pow(10, power);
  const factor = error >= e10 ? 10 : error >= e5 ? 5 : error >= e2 ? 2 : 1;
  let i1: number;
  let i2: number;
  let inc: number;
  if (power < 0) {
    inc = Math.pow(10, -power) / factor;
    i1 = roundHalfEven(start * inc);
    i2 = roundHalfEven(stop * inc);
    if (i1 / inc < start) ++i1;
    if (i2 / inc > stop) --i2;
    inc = -inc;
  } else {
    inc = Math.pow(10, power) * factor;
    i1 = roundHalfEven(start / inc);
    i2 = roundHalfEven(stop / inc);
    if (i1 * inc < start) ++i1;
    if (i2 * inc > stop) --i2;
  }
  if (i2 < i1 && 0.5 <= count && count < 2) return tickSpec(start, stop, count * 2);
  return [i1, i2, inc];
}

/** The tick increment d3.ticks would use; negative means an inverse increment - d3.tickIncrement. */
function tickIncrement(start: number, stop: number, count: number): number {
  return tickSpec(start, stop, count)[2];
}

/** The positive step between adjacent tick values (sign follows direction) - d3.tickStep. */
export function tickStep(start: number, stop: number, count: number): number {
  const reverse = stop < start;
  const inc = reverse ? tickIncrement(stop, start, count) : tickIncrement(start, stop, count);
  return (reverse ? -1 : 1) * (inc < 0 ? 1 / -inc : inc);
}

/** The tick-interval ladder (seconds through years) a UTC time scale chooses from, with each rung's step and length. */
const utcLadder: readonly [TimeInterval, number, number][] = [
  [TimeInterval.second, 1, DurationSecond],
  [TimeInterval.second, 5, 5 * DurationSecond],
  [TimeInterval.second, 15, 15 * DurationSecond],
  [TimeInterval.second, 30, 30 * DurationSecond],
  [TimeInterval.utcMinute, 1, DurationMinute],
  [TimeInterval.utcMinute, 5, 5 * DurationMinute],
  [TimeInterval.utcMinute, 15, 15 * DurationMinute],
  [TimeInterval.utcMinute, 30, 30 * DurationMinute],
  [TimeInterval.utcHour, 1, DurationHour],
  [TimeInterval.utcHour, 3, 3 * DurationHour],
  [TimeInterval.utcHour, 6, 6 * DurationHour],
  [TimeInterval.utcHour, 12, 12 * DurationHour],
  [TimeInterval.unixDay, 1, DurationDay],
  [TimeInterval.unixDay, 2, 2 * DurationDay],
  [TimeInterval.utcSunday, 1, DurationWeek],
  [TimeInterval.utcMonth, 1, DurationMonth],
  [TimeInterval.utcMonth, 3, 3 * DurationMonth],
  [TimeInterval.utcYear, 1, DurationYear],
];
const ladderDurations = utcLadder.map((rung) => rung[2]);

/** The UTC interval the ladder chooses for about count ticks - d3.utcTickInterval. */
export function utcTickInterval(start: number, stop: number, count: number): TimeInterval | null {
  const target = Math.abs(stop - start) / count;
  const i = bisectRight(ladderDurations, target);
  if (i === utcLadder.length) return TimeInterval.utcYear.every(tickStep(start / DurationYear, stop / DurationYear, count));
  if (i === 0) return TimeInterval.millisecond.every(Math.max(tickStep(start, stop, count), 1));
  const [interval, step] = utcLadder[target / utcLadder[i - 1][2] < utcLadder[i][2] / target ? i - 1 : i];
  return interval.every(step);
}

/** About count nicely placed UTC ticks in [start, stop] - d3.utcTicks. */
export function utcTicks(start: number, stop: number, count: number): number[] {
  const reverse = stop < start;
  if (reverse) [start, stop] = [stop, start];
  const interval = utcTickInterval(start, stop, count);
  const ticks = interval === null ? [] : interval.range(start, stop + 1); // Inclusive stop.
  if (reverse) ticks.reverse();
  return ticks;
}

// ---------------------------------------------------------------- formats

/** d3's default en-US time locale. */
const EnUs = {
  dateTime: "%x, %X",
  date: "%-m/%-d/%Y",
  time: "%-I:%M:%S %p",
  periods: ["AM", "PM"],
  days: ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
  shortDays: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
  months: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
  shortMonths: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
};

function padJs(value: number, fill: string, width: number): string {
  const sign = value < 0 ? "-" : "";
  const body = String(Math.abs(value));
  return sign + (body.length < width && fill.length > 0 ? fill[0].repeat(width - body.length) + body : body);
}

/** A strftime-style UTC format of a date in d3's en-US locale - d3.utcFormat(specifier)(date). */
export function utcFormat(specifier: string, date: number): string {
  let result = "";
  let j = 0;
  const n = specifier.length;
  for (let i = 0; i < n; ++i) {
    if (specifier[i] === "%") {
      result += specifier.substring(j, i);
      let pad: string;
      let c = ++i < n ? specifier[i] : "\0";
      if (c === "-" || c === "_" || c === "0") {
        pad = c === "-" ? "" : c === "_" ? " " : "0";
        c = ++i < n ? specifier[i] : "\0";
      } else pad = c === "e" ? " " : "0";
      result += formatDirective(c, date, pad);
      j = i + 1;
    }
  }
  result += specifier.substring(j, n);
  return result;
}

function isoThursday(d: number): number {
  const w = dayOfWeek(d);
  return w >= 4 || w === 0 ? TimeInterval.utcThursday.floor(d) : TimeInterval.utcThursday.ceil(d);
}

function formatDirective(c: string, d: number, pad: string): string {
  switch (c) {
    case "a":
      return EnUs.shortDays[dayOfWeek(d)];
    case "A":
      return EnUs.days[dayOfWeek(d)];
    case "b":
      return EnUs.shortMonths[month(d) - 1];
    case "B":
      return EnUs.months[month(d) - 1];
    case "c":
      return utcFormat(EnUs.dateTime, d);
    case "d":
    case "e":
      return padJs(day(d), pad, 2);
    case "f":
      return padJs(millisecond(d), pad, 3) + "000";
    case "g":
      return padJs(year(isoThursday(d)) % 100, pad, 2);
    case "G":
      return padJs(year(isoThursday(d)) % 10000, pad, 4);
    case "H":
      return padJs(hour(d), pad, 2);
    case "I":
      return padJs(hour(d) % 12 === 0 ? 12 : hour(d) % 12, pad, 2);
    case "j":
      return padJs(1 + TimeInterval.utcDay.count(TimeInterval.utcYear.floor(d), d), pad, 3);
    case "L":
      return padJs(millisecond(d), pad, 3);
    case "m":
      return padJs(month(d), pad, 2);
    case "M":
      return padJs(minute(d), pad, 2);
    case "p":
      return EnUs.periods[hour(d) >= 12 ? 1 : 0];
    case "q":
      return String(1 + Math.trunc((month(d) - 1) / 3));
    case "Q":
      return String(Math.trunc(d));
    case "s":
      return String(Math.floor(d / 1000));
    case "S":
      return padJs(second(d), pad, 2);
    case "u":
      return String(dayOfWeek(d) === 0 ? 7 : dayOfWeek(d));
    case "U":
      return padJs(TimeInterval.utcSunday.count(TimeInterval.utcYear.floor(d) - 1, d), pad, 2);
    case "V": {
      const iso = isoThursday(d);
      const yearStart = TimeInterval.utcYear.floor(iso);
      const week = TimeInterval.utcThursday.count(yearStart, iso) + (dayOfWeek(yearStart) === 4 ? 1 : 0);
      return padJs(week, pad, 2);
    }
    case "w":
      return String(dayOfWeek(d));
    case "W":
      return padJs(TimeInterval.utcMonday.count(TimeInterval.utcYear.floor(d) - 1, d), pad, 2);
    case "x":
      return utcFormat(EnUs.date, d);
    case "X":
      return utcFormat(EnUs.time, d);
    case "y":
      return padJs(year(d) % 100, pad, 2);
    case "Y":
      return padJs(year(d) % 10000, pad, 4);
    case "Z":
      // A UTC date's zone is always +0000.
      return "+0000";
    case "%":
      return "%";
    default:
      return "%" + c;
  }
}

/**
 * The multi-scale tick formatter over UTC intervals: milliseconds show ".%L", seconds ":%S", minutes "%I:%M", hours "%I %p", days "%a %d", weeks "%b %d", months "%B", years "%Y" - choosing the coarsest unit the tick is a boundary of.
 */
export function utcMultiScale(date: number): string {
  const specifier =
    TimeInterval.second.floor(date) < date
      ? ".%L"
      : TimeInterval.utcMinute.floor(date) < date
        ? ":%S"
        : TimeInterval.utcHour.floor(date) < date
          ? "%I:%M"
          : TimeInterval.utcDay.floor(date) < date
            ? "%I %p"
            : TimeInterval.utcMonth.floor(date) < date
              ? TimeInterval.utcSunday.floor(date) < date
                ? "%a %d"
                : "%b %d"
              : TimeInterval.utcYear.floor(date) < date
                ? "%B"
                : "%Y";
  return utcFormat(specifier, date);
}

// ---------------------------------------------------------------- the scale

/** A linear scale over UTC dates with calendar-aware ticks and the multi-scale tick format - d3.scaleUtc. */
export class TimeScale {
  private domain0 = utcDate(2000, 0, 1);
  private domain1 = utcDate(2000, 0, 2);
  private range0 = 0;
  private range1 = 1;

  domain(first: number, last: number): this {
    this.domain0 = first;
    this.domain1 = last;
    return this;
  }

  range(first: number, last: number): this {
    this.range0 = first;
    this.range1 = last;
    return this;
  }

  /** Map a date to the range: the bimap of d3-scale's continuous.js, with d3.interpolateNumber. */
  apply(date: number): number {
    if (Number.isNaN(date)) return Number.NaN;
    let d0 = this.domain0;
    let d1 = this.domain1;
    let r0 = this.range0;
    let r1 = this.range1;
    if (d1 < d0) {
      [d0, d1] = [d1, d0];
      [r0, r1] = [r1, r0];
    }
    const span = d1 - d0;
    const t = span !== 0 && !Number.isNaN(span) ? (date - d0) / span : Number.isNaN(span) ? Number.NaN : 0.5;
    return r0 * (1 - t) + r1 * t;
  }

  /** Calendar-aware ticks: about count boundaries from the interval ladder. */
  ticks(count = 10): number[] {
    return utcTicks(this.domain0, this.domain1, count);
  }

  /** The multi-scale tick format when no specifier is given, or a fixed strftime format. */
  tickFormat(specifier?: string | null): (date: number) => string {
    if (specifier === null || specifier === undefined) return utcMultiScale;
    return (date) => utcFormat(specifier, date);
  }
}

/** d3.scaleUtc - UTC calendar time; machine independent. */
export function scaleUtc(): TimeScale {
  return new TimeScale();
}
