// A named column of values a chart reads: numbers or text categories.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Data/Series.cs. Dates and times are not ported: no Dhole chart binds them.
//
// This is the whole of the data model. A layer binds a series to a channel - the x position, the y position, a colour, a label - and
// the channel's scale reads the series' kind: numbers become a continuous scale, text a band of categories. A series copies what it
// is given, so a chart drawn later draws what it held when it was made.

import { formatNumber } from "./formatting";

/** What a series holds: numbers, text categories, or dates and times. */
export type SeriesKind = "number" | "text" | "time";

export class Series {
  readonly name: string;
  readonly kind: SeriesKind;
  private readonly numbers: readonly number[] | null;
  private readonly texts: readonly string[] | null;

  private constructor(name: string, kind: SeriesKind, numbers: readonly number[] | null, texts: readonly string[] | null) {
    this.name = name;
    this.kind = kind;
    this.numbers = numbers;
    this.texts = texts;
  }

  /** A series of numbers. Not-a-number entries are gaps: a line breaks there and a point is not drawn. */
  static ofNumbers(values: Iterable<number>, name?: string | null): Series {
    return new Series(name ?? "", "number", [...values], null);
  }

  /** A series of text categories, in the order given; a null entry is a gap. */
  static ofTexts(categories: Iterable<string | null>, name?: string | null): Series {
    return new Series(name ?? "", "text", null, [...categories].map((c) => c ?? ""));
  }

  /** The numbers 0, 1, 2 ... up to one less than `count`: the x positions of a series given without any. */
  static index(count: number, name?: string | null): Series {
    return new Series(name ?? "", "number", Array.from({ length: count }, (_, i) => i), null);
  }

  /** A series of numbers or of text, by what the array holds - C#'s implicit conversions from double[] and string[]. */
  static of(values: readonly number[] | readonly string[] | Series): Series {
    if (values instanceof Series) return values;
    return values.length > 0 && typeof values[0] === "string" ? Series.ofTexts(values as readonly string[]) : Series.ofNumbers(values as readonly number[]);
  }

  /** How many values the series holds. */
  get count(): number {
    return this.numbers?.length ?? this.texts?.length ?? 0;
  }

  /** The numbers of a number series. */
  get numbersOf(): readonly number[] {
    if (!this.numbers) throw this.wrongKind("number");
    return this.numbers;
  }

  /** The categories of a text series. */
  get textsOf(): readonly string[] {
    if (!this.texts) throw this.wrongKind("text");
    return this.texts;
  }

  /** The value at `index` as a number on a continuous axis; not a number for text, and for a gap. */
  position(index: number): number {
    return this.kind === "number" ? this.numbers![index] : NaN;
  }

  /** The value at `index` as text, whatever the kind - what a label or a legend shows for it. */
  text(index: number): string {
    return this.kind === "text" ? this.texts![index] : formatNumber(this.numbers![index]);
  }

  /** The distinct categories of a text series in the order they first appear. */
  distinctTexts(): string[] {
    if (!this.texts) throw this.wrongKind("text");
    return [...new Set(this.texts)];
  }

  private wrongKind(wanted: SeriesKind): Error {
    return new Error(`The series ${this.name.length === 0 ? "" : `'${this.name}' `}holds ${describeKind(this.kind)}, not ${describeKind(wanted)}.`);
  }

  toString(): string {
    return `${this.name.length === 0 ? "Series" : this.name}: ${this.count} ${describeKind(this.kind)}`;
  }
}

export function describeKind(kind: SeriesKind): string {
  return kind === "number" ? "numbers" : kind === "text" ? "text" : "dates and times";
}
