// Measuring and setting text: what every word in a figure is laid out with, so what is measured is exactly what is drawn.
//
// Divooka lays text out with its own paragraph engine over the fonts it finds (Divooka.Graphics.Canvas.Text). A page has the
// browser's fonts instead, so here a measurer asks the browser - a canvas measures in the same faces the SVG's text is drawn
// in - and the engine breaks lines as Divooka's does: greedily, at the opportunities Unicode's line breaking gives, a word wider
// than the line broken between its characters, and spaces at a break left at the end of the line they follow.

/** How heavy a face is, as CSS numbers it: 400 normal, 600 semi-bold, 700 bold. */
export type FontWeight = number;
export const FontWeights = { Normal: 400, Medium: 500, SemiBold: 600, Bold: 700 } as const;

/** The face and size a piece of text is set in. */
export interface FontSpec {
  /** The font families to use, first available wins. */
  readonly families: readonly string[];
  /** The size, in pixels. */
  readonly size: number;
  readonly weight: FontWeight;
  readonly italic?: boolean;
}

/** How tall a face's lines are, in pixels at its size. */
export interface LineMetrics {
  /** From the top of a line to its baseline. */
  readonly ascent: number;
  /** From the baseline to the bottom of a line. */
  readonly descent: number;
}

/** What text is measured with: the width of a run of text on one line, and the height of a line. */
export interface TextMeasurer {
  width(text: string, font: FontSpec): number;
  metrics(font: FontSpec): LineMetrics;
}

/** A CSS font shorthand for a font spec. */
export function cssFont(font: FontSpec): string {
  const families = font.families.map((f) => (/^[\w-]+$/.test(f) && !/^\d/.test(f) ? f : `"${f.replaceAll('"', "")}"`)).join(", ");
  return `${font.italic ? "italic " : ""}${font.weight} ${font.size}px ${families}, sans-serif`;
}

/** The family list as an SVG font-family attribute. */
export function cssFamilies(families: readonly string[]): string {
  return [...families.map((f) => (/^[\w-]+$/.test(f) ? f : `'${f.replaceAll("'", "")}'`)), "sans-serif"].join(", ");
}

// ---------------------------------------------------------------- measurers

/**
 * Measures with a canvas, in whatever face the browser resolves the families to: the face the SVG's text will be drawn in.
 */
export class CanvasMeasurer implements TextMeasurer {
  private readonly context: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D;
  private readonly widths = new Map<string, number>();
  private readonly lineMetrics = new Map<string, LineMetrics>();

  constructor(context?: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D) {
    if (context) this.context = context;
    else if (typeof OffscreenCanvas !== "undefined") this.context = new OffscreenCanvas(1, 1).getContext("2d") as OffscreenCanvasRenderingContext2D;
    else this.context = document.createElement("canvas").getContext("2d") as CanvasRenderingContext2D;
    if (!this.context) throw new Error("This page cannot measure text: it has no 2D canvas.");
  }

  /** Whether this page can measure with a canvas at all. */
  static get available(): boolean {
    return typeof OffscreenCanvas !== "undefined" || typeof document !== "undefined";
  }

  width(text: string, font: FontSpec): number {
    const css = cssFont(font);
    const key = `${css}\u0000${text}`;
    let w = this.widths.get(key);
    if (w === undefined) {
      this.context.font = css;
      w = this.context.measureText(text).width;
      if (this.widths.size > 20000) this.widths.clear();
      this.widths.set(key, w);
    }
    return w;
  }

  metrics(font: FontSpec): LineMetrics {
    // Browsers round a face's ascent and descent to whole pixels at the size asked for - Open Sans at 12.5 px is 13 + 4 rather
    // than 13.36 + 3.66 - which over a block of lines drifts from Divooka, whose engine keeps the fractions. Measured once at a
    // thousand pixels per em and scaled, they keep theirs too.
    const unit = cssFont({ ...font, size: MetricsSize });
    let perEm = this.lineMetrics.get(unit);
    if (!perEm) {
      this.context.font = unit;
      const measured = this.context.measureText("Ag");
      const ascent = measured.fontBoundingBoxAscent / MetricsSize;
      const descent = measured.fontBoundingBoxDescent / MetricsSize;
      perEm = Number.isFinite(ascent) && Number.isFinite(descent) && ascent + descent > 0 ? { ascent, descent } : { ascent: 1.06884765625, descent: 0.29296875 };
      this.lineMetrics.set(unit, perEm);
    }
    return { ascent: perEm.ascent * font.size, descent: perEm.descent * font.size };
  }
}

/**
 * Measures by a table of Open Sans's advance widths, without a browser: for a page with no canvas, a Worker, and tests, which need
 * the same measurement on every machine. Characters outside the table are measured as their kind usually is - an ideograph a
 * whole em, anything else an average letter. Kerning is not applied, so a word measures a little wider than a browser sets it.
 */
export class MetricsMeasurer implements TextMeasurer {
  width(text: string, font: FontSpec): number {
    const table = font.weight >= 550 ? OpenSansSemibold : OpenSansRegular;
    let em = 0;
    for (const ch of text) {
      const code = ch.codePointAt(0) ?? 32;
      if (code >= 32 && code < 127) em += table[code - 32];
      else if (isWide(code)) em += 1;
      else if (code >= 0x300 && code < 0x370) em += 0;
      else em += 0.58;
    }
    return em * font.size;
  }

  metrics(font: FontSpec): LineMetrics {
    return { ascent: font.size * 1.06884765625, descent: font.size * 0.29296875 };
  }
}

