/** Whether a code point is set a whole em wide: an ideograph, a kana, a Hangul syllable, or a full-width form. */
function isWide(code: number): boolean {
  return (
    (code >= 0x1100 && code <= 0x115f) ||
    (code >= 0x2e80 && code <= 0xa4cf) ||
    (code >= 0xac00 && code <= 0xd7a3) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xfe30 && code <= 0xfe4f) ||
    (code >= 0xff00 && code <= 0xff60) ||
    (code >= 0xffe0 && code <= 0xffe6) ||
    (code >= 0x20000 && code <= 0x3fffd)
  );
}

/** The size a face's vertical metrics are measured at, so whole-pixel rounding costs nothing. */
const MetricsSize = 1000;

let defaultMeasurer: TextMeasurer | null = null;

/** The measurer text is set with when none is given: a canvas where the page has one, the metrics table where it has not. */
export function getDefaultMeasurer(): TextMeasurer {
  if (!defaultMeasurer) {
    try {
      defaultMeasurer = CanvasMeasurer.available ? new CanvasMeasurer() : new MetricsMeasurer();
    } catch {
      defaultMeasurer = new MetricsMeasurer();
    }
  }
  return defaultMeasurer;
}

/** Sets the measurer text is set with when none is given. */
export function setDefaultMeasurer(measurer: TextMeasurer | null): void {
  defaultMeasurer = measurer;
}

// ---------------------------------------------------------------- setting

/** How lines line up in a block. */
export type ParagraphAlignment = "left" | "center" | "right";

/** One line of a laid-out block: its words, how wide they are, and where the line starts within the block. */
export interface TextLine {
  readonly text: string;
  readonly width: number;
  /** The line's left edge within the block, for its alignment. */
  readonly left: number;
  /** The line's top within the block. */
  readonly top: number;
  /** The line's baseline within the block. */
  readonly baseline: number;
}

/** A block of text laid out: its lines, its size, and the face it was set in. */
export interface TextLayout {
  readonly font: FontSpec;
  readonly lines: readonly TextLine[];
  /** The widest line. */
  readonly width: number;
  /** Every line's height together. */
  readonly height: number;
  readonly align: ParagraphAlignment;
}

/** One piece of a text between two places a line may break, with the white space after it. */
interface Piece {
  readonly text: string;
  /** Whether a line must break after it. */
  readonly hard: boolean;
}

const closing = /[\p{Pe}\p{Pf}\u3001\u3002\uFF0C\uFF0E\uFF1A\uFF1B\uFF01\uFF1F\u30FC\u3005\u300D\u300F!,.:;?)\]}%]/u;
const opening = /[\p{Ps}\p{Pi}\u300C\u300E([{]/u;

function isIdeographic(c: string): boolean {
  const code = c.codePointAt(0) ?? 0;
  return isWide(code);
}

/**
 * A text cut where a line may break: after a run of spaces, after a hyphen inside a word, before and after an ideograph (but
 * never before closing punctuation or after opening), and - mandatorily - at a line break.
 */
function pieces(text: string): Piece[] {
  const result: Piece[] = [];
  const chars = [...text];
  let current = "";
  for (let i = 0; i < chars.length; i++) {
    const c = chars[i];
    if (c === "\n") {
      result.push({ text: current, hard: true });
      current = "";
      continue;
    }
    if (c === "\r") continue;
    current += c;
    const next = chars[i + 1];
    if (next === undefined || next === "\n") continue;
    const space = /\s/u.test(c);
    const nextSpace = /\s/u.test(next);
    let breakAfter = false;
    if (space && !nextSpace) breakAfter = true;
    else if (!space && (c === "-" || c === "\u2010" || c === "\u2013") && /[\p{L}]/u.test(chars[i - 1] ?? "") && /[\p{L}]/u.test(next)) breakAfter = true;
    else if (!space && !nextSpace && (isIdeographic(c) || isIdeographic(next)) && !closing.test(next) && !opening.test(c)) breakAfter = true;
    if (breakAfter) {
      result.push({ text: current, hard: false });
      current = "";
    }
  }
  result.push({ text: current, hard: false });
  return result;
}

function trimEndSpaces(text: string): string {
  return text.replace(/\s+$/u, "");
}

/**
 * Lays text out: lines broken greedily to fit `maxWidth` (or only at line breaks when it is infinite), each aligned within the
 * widest, each as tall as the face's line.
 */
export function layoutText(measurer: TextMeasurer, text: string, font: FontSpec, maxWidth = Number.POSITIVE_INFINITY, align: ParagraphAlignment = "left"): TextLayout {
  const source = text.length === 0 ? " " : text;
  const wrap = Number.isFinite(maxWidth);
  const raw: string[] = [];
  // The lines that end where they were broken to fit, rather than at a line break or the end of the text.
  const wrapped = new Set<number>();
  let line = "";
  const measure = (s: string): number => measurer.width(trimEndSpaces(s), font);
  for (const piece of pieces(source)) {
    if (!wrap) {
      line += piece.text;
      if (piece.hard) {
        raw.push(line);
        line = "";
      }
      continue;
    }
    if (line.length > 0 && measure(line + piece.text) > maxWidth && trimEndSpaces(piece.text).length > 0) {
      wrapped.add(raw.length);
      raw.push(line);
      line = "";
    }
    if (line.length === 0 && measure(piece.text) > maxWidth) {
      // Nothing offers a break, so the word itself is wider than the measure: it breaks between its characters.
      let part = "";
      for (const c of piece.text) {
        if (part.length > 0 && !/\s/u.test(c) && measure(part + c) > maxWidth) {
          wrapped.add(raw.length);
          raw.push(part);
          part = "";
        }
        part += c;
      }
      line = part;
    } else line += piece.text;
    if (piece.hard) {
      raw.push(line);
      line = "";
    }
  }
  raw.push(line);

  const metrics = measurer.metrics(font);
  const lineHeight = metrics.ascent + metrics.descent;
  const lines = raw.map((t, i) => {
    const shown = trimEndSpaces(t);
    if (shown.length === 0) return { text: "", width: 0 };
    // Divooka's paragraph engine (TextBlock.BuildLine) draws the spaces at a line's end ("wrap " then "onto"), and counts them in the line's width unless the line was broken by wrapping and is not flush left, or they no longer fit inside the measure.
    if (shown.length < t.length) {
      const whole = measurer.width(t, font);
      if ((!wrapped.has(i) || align === "left") && whole < maxWidth) return { text: t, width: whole };
    }
    return { text: t, width: measurer.width(shown, font) };
  });
  const widest = lines.reduce((w, l) => Math.max(w, l.width), 0);
  // Lines line up within the measure when there is one, as Divooka's paragraph engine aligns them, and within the widest when there is not.
  const box = Number.isFinite(maxWidth) ? maxWidth : widest;
  return {
    font,
    align,
    width: widest,
    height: lines.length * lineHeight,
    lines: lines.map((l, i) => ({
      text: l.text,
      width: l.width,
      left: align === "center" ? (box - l.width) / 2 : align === "right" ? box - l.width : 0,
      top: i * lineHeight,
      baseline: i * lineHeight + metrics.ascent,
    })),
  };
}
