// Pies and donuts, and radar charts. Ported from Parcel NExT's Divooka.Graphics.Plotting/Layers/RadialLayers.cs (Pie and Radar; the
// hierarchies and networks of that file are not drawn by Dhole).

import { inkOn, withOpacity } from "../color-math";
import { ChartLayerPlan, ChartPaints, chartContext, type ChartTraining, type LegendCollector, type PolarLayer, type PolarTraining } from "../contracts";
import { arcPath, pie, type PieArc } from "../d3-shapes";
import { Layer, type DrawContext, type FrameKind, type PlanContext } from "../figure";
import { formatNumber, formatWith } from "../formatting";
import { Series } from "../series";
import type { Colour } from "../theme";
import { Check } from "./lines";
import { drawPoint } from "./marks";
import { VectorPath, type Vec2 } from "../../rendering/geometry";

/** What a pie's slices say: each slice's share of the whole, its value, its name, its name and share, or nothing (the legend names the slices). */
export type SliceLabel = "percent" | "value" | "name" | "nameAndPercent" | "none";

type Slice = { name: string; value: number };

/**
 * A pie or, with a hole, a donut: parts of a whole as slices, largest first from twelve o'clock. Each slice is a category in the
 * palette's colours, taken in the order the slices go round, and the legend lists them in that order too; its share is written on it
 * when it fits, or beside it with a leader line when it does not. A pie reads well for a few parts of one whole and badly for close
 * values: past six slices, bars say it better.
 */
export class Pie extends Layer {
  /** Each slice's name; a value with no name is left out, since the legend could not say what its slice is. */
  readonly categories: Series;
  /** Each slice's size; zero and negative sizes are left out. */
  readonly values: Series;
  /** The hole's radius as a share of the pie's: 0 for a pie, about 0.6 for a donut. */
  hole = 0;
  /** Whether slices keep the order given instead of largest first. */
  keepOrder = false;
  /** What each slice says. */
  sliceLabels: SliceLabel = "percent";
  /** A line of text in the hole of a donut: a total, a title. */
  centerText: string | null = null;

  constructor(categories: readonly string[], values: readonly number[]) {
    super();
    this.categories = Series.ofTexts(categories);
    this.values = Series.ofNumbers(values);
  }

  plan(_context: PlanContext): PiePlan {
    Check.sameLength(this.categories, this.values, "category", "value");
    Check.numbers(this.values, "slice sizes");
    return new PiePlan(this);
  }
}

class PiePlan extends ChartLayerPlan {
  private readonly slices: Slice[] = [];
  private arcsCache: PieArc<Slice>[] | null = null;

  constructor(private readonly pie: Pie) {
    super(pie);
    const index = new Map<string, number>();
    for (let i = 0; i < pie.categories.count; i++) {
      const v = pie.values.numbersOf[i];
      if (!(v > 0)) continue;
      const name = pie.categories.text(i);
      // A missing category - a table's empty cell - would be a slice the legend leaves out, its share drawn with nothing to say whose it is.
      if (!name.trim()) continue;
      const at = index.get(name);
      if (at !== undefined) this.slices[at] = { name, value: this.slices[at].value + v };
      else {
        index.set(name, this.slices.length);
        this.slices.push({ name, value: v });
      }
    }
  }

  override get frame(): FrameKind {
    return "free";
  }

  /** The slices' angles, which depend on their sizes alone: largest first from twelve o'clock, or in the order given. */
  private arcs(): PieArc<Slice>[] {
    return (this.arcsCache ??= pie(this.slices, (s) => s.value, this.pie.keepOrder));
  }

  /** The slices' names in the order they go round. The colours are dealt and the legend is written in this order, so the legend reads down the way the pie reads round - in the data's order it listed the smallest region of Sales first, beside the largest slice. */
  private roundThePie(): string[] {
    return [...this.arcs()].sort((a, b) => a.index - b.index).map((arc) => arc.data.name);
  }

  override train(training: ChartTraining): void {
    for (const name of this.roundThePie()) training.color.addCategory(name);
  }

  draw(context: DrawContext): void {
    if (this.slices.length === 0) return;
    const pie = this.pie;
    const colors = chartContext(context).colors;
    const area = context.plot;
    const text = context.text;
    const labelRoom = pie.sliceLabels === "none" ? 8 : text.lineHeight("dataLabel") * 2.2;
    const outer = Math.max(10, Math.min(area.width, area.height) / 2 - labelRoom);
    const inner = Math.min(Math.max(pie.hole, 0), 0.95) * outer;
    const center: Vec2 = { x: area.midX, y: area.midY };
    const total = this.slices.reduce((sum, s) => sum + s.value, 0);
    const arcs = this.arcs();

    for (const arc of arcs) {
      const path = arcPath(center.x, center.y, inner, outer, arc.startAngle, arc.endAngle);
      const fill = withOpacity(colors.forCategory(arc.data.name), pie.opacity);
      context.sink.drawPath(path, ChartPaints.fill(fill));
      // The surface gap between slices, as a stroke of the background along every edge.
      context.sink.drawPath(path, ChartPaints.stroke(context.surface, 2, null, false));
    }

    for (const arc of arcs) {
      const label =
        pie.sliceLabels === "percent"
          ? formatWith(arc.data.value / total, ".0%")
          : pie.sliceLabels === "value"
            ? formatNumber(arc.data.value)
            : pie.sliceLabels === "name"
              ? arc.data.name
              : pie.sliceLabels === "nameAndPercent"
                ? `${arc.data.name} ${formatWith(arc.data.value / total, ".0%")}`
                : "";
      if (label.length === 0) continue;
      const mid = (arc.startAngle + arc.endAngle) / 2;
      const s = Math.sin(mid);
      const c = -Math.cos(mid);
      const inside = (inner + outer) / 2;
      const size = text.measure(label, "dataLabel");
      const arcLength = (arc.endAngle - arc.startAngle) * inside;
      const fill = colors.forCategory(arc.data.name);
      if (arcLength > size.width + 6 && outer - inner > size.height + 4) {
        text.draw(context.sink, label, center.x + s * inside, center.y + c * inside, "dataLabel", inkOn(fill, context.theme.ink, { r: 255, g: 255, b: 255, a: 255 }), "center");
        continue;
      }
      // Outside, on a short leader from the slice's middle.
      const from = { x: center.x + s * (outer - 2), y: center.y + c * (outer - 2) };
      const to = { x: center.x + s * (outer + 10), y: center.y + c * (outer + 10) };
      context.sink.drawLine(from.x, from.y, to.x, to.y, ChartPaints.stroke(context.theme.secondaryInk, 1));
      text.draw(context.sink, label, to.x + (s >= 0 ? 3 : -3), to.y, "dataLabel", context.theme.secondaryInk, s >= 0 ? "left" : "right");
    }

    if (pie.centerText && inner > 0) text.draw(context.sink, pie.centerText, center.x, center.y, "chartTitle", context.theme.ink, "center");
  }

  override addLegend(legend: LegendCollector): void {
    legend.addCategories(this.roundThePie(), "fill");
  }
}

/** A radar (spider) chart: one value per spoke, joined into a shape; several layers compare several subjects across the same spokes. */
export class Radar extends Layer {
  /** Each value's spoke, in order round the circle from twelve o'clock. */
  readonly spokes: Series;
  /** The values, measured out from the centre. */
  readonly values: Series;
  /** Whether the shape is washed with its colour. */
  fill = true;
  /** Whether each value is marked with a point. */
  markers = true;

  constructor(spokes: readonly string[], values: readonly number[]) {
    super();
    this.spokes = Series.ofTexts(spokes);
    this.values = Series.ofNumbers(values);
  }

  plan(context: PlanContext): RadarPlan {
    Check.sameLength(this.spokes, this.values, "spoke", "value");
    Check.numbers(this.values, "radar's values");
    return new RadarPlan(this, context.seriesColor(this));
  }
}

class RadarPlan extends ChartLayerPlan implements PolarLayer {
  constructor(
    private readonly radar: Radar,
    private readonly color: Colour,
  ) {
    super(radar);
  }

  override get frame(): FrameKind {
    return "polar";
  }
  override get clipToPlot(): boolean {
    return false;
  }

  trainPolar(training: PolarTraining): void {
    for (let i = 0; i < this.radar.spokes.count; i++) {
      training.addSpoke(this.radar.spokes.text(i));
      training.addValue(this.radar.values.numbersOf[i]);
    }
  }

  draw(context: DrawContext): void {
    const radar = this.radar;
    const frame = chartContext(context).polar;
    if (!frame) throw new Error("A radar layer needs a radial chart.");
    const values = new Map<string, number>();
    for (let i = 0; i < radar.spokes.count; i++) values.set(radar.spokes.text(i), radar.values.numbersOf[i]);
    const points: Vec2[] = [];
    for (let s = 0; s < frame.spokes.length; s++) {
      const v = values.get(frame.spokes[s]) ?? frame.radial.min;
      points.push(frame.point(s, Number.isFinite(v) ? v : frame.radial.min));
    }
    if (points.length === 0) return;
    const shape = new VectorPath();
    points.forEach((p, i) => (i === 0 ? shape.moveTo(p.x, p.y) : shape.lineTo(p.x, p.y)));
    shape.close();
    const ink = withOpacity(this.color, radar.opacity);
    if (radar.fill) context.sink.drawPath(shape, ChartPaints.fill(withOpacity(this.color, context.theme.areaOpacity * 1.5 * radar.opacity)));
    context.sink.drawPath(shape, ChartPaints.stroke(ink, context.theme.lineWidth));
    if (radar.markers) for (const p of points) drawPoint(context.sink, p.x, p.y, "circle", context.theme.pointSize * 0.75, ink, context.surface, context.theme.pointRing);
  }

  override addLegend(legend: LegendCollector): void {
    legend.add(this.radar.label, this.color, "lineAndPoint");
  }
}
