// The parts of D3's shapes a chart draws with: the line generator and its curves (linear, monotone in x, steps), the pie generator
// and the arc generator of a pie's slices. Ported from Parcel NExT's Divooka.Graphics.Canvas.D3 (Shapes/*.cs), itself a port of
// d3-shape. A generator writes into a path context - the commands of a canvas path - which a chart turns into a VectorPath.

import { RectF, VectorPath } from "../rendering/geometry";

/** One command of a path as a d3 path context receives it. */
export type PathCommand =
  | { readonly verb: "M"; readonly x: number; readonly y: number }
  | { readonly verb: "L"; readonly x: number; readonly y: number }
  | { readonly verb: "C"; readonly x1: number; readonly y1: number; readonly x2: number; readonly y2: number; readonly x: number; readonly y: number }
  | { readonly verb: "Z" };

/** A path context that records what a generator draws. */
export class PathRecorder {
  readonly commands: PathCommand[] = [];
  moveTo(x: number, y: number): void {
    this.commands.push({ verb: "M", x, y });
  }
  lineTo(x: number, y: number): void {
    this.commands.push({ verb: "L", x, y });
  }
  bezierCurveTo(x1: number, y1: number, x2: number, y2: number, x: number, y: number): void {
    this.commands.push({ verb: "C", x1, y1, x2, y2, x, y });
  }
  closePath(): void {
    this.commands.push({ verb: "Z" });
  }

  /** The recorded commands as a vector path. */
  toPath(path = new VectorPath()): VectorPath {
    for (const c of this.commands) {
      if (c.verb === "M") path.moveTo(c.x, c.y);
      else if (c.verb === "L") path.lineTo(c.x, c.y);
      else if (c.verb === "C") path.cubicTo({ x: c.x1, y: c.y1 }, { x: c.x2, y: c.y2 }, { x: c.x, y: c.y });
      else path.close();
    }
    return path;
  }
}

/** A d3 curve: told where each defined run of points starts and ends, and each point in between. */
export interface Curve {
  lineStart(): void;
  lineEnd(): void;
  point(x: number, y: number): void;
}

export type CurveFactory = (context: PathRecorder) => Curve;

/** Straight segments from point to point - d3.curveLinear. */
export const curveLinear: CurveFactory = (context) => {
  let line: number | undefined;
  let state = 0;
  return {
    lineStart() {
      state = 0;
    },
    lineEnd() {
      if (line || (line !== 0 && state === 1)) context.closePath();
      line = 1 - (line as number);
    },
    point(x, y) {
      switch (state) {
        case 0:
          state = 1;
          if (line) context.lineTo(x, y);
          else context.moveTo(x, y);
          break;
        default:
          // The second point and every one after it (d3 falls through from the second to the rest).
          if (state === 1) state = 2;
          context.lineTo(x, y);
          break;
      }
    },
  };
};

/** Steps: `t` 0.5 changes level halfway between points, 1 at each point holding the new level after it, 0 holding each level up to its point - d3.curveStep, curveStepAfter, curveStepBefore. */
function curveStepWith(t0: number): CurveFactory {
  return (context) => {
    let line: number | undefined;
    let state = 0;
    let t = t0;
    let px = NaN;
    let py = NaN;
    return {
      lineStart() {
        px = py = NaN;
        state = 0;
      },
      lineEnd() {
        if (0 < t && t < 1 && state === 2) context.lineTo(px, py);
        if (line || (line !== 0 && state === 1)) context.closePath();
        if ((line as number) >= 0) {
          t = 1 - t;
          line = 1 - (line as number);
        }
      },
      point(x, y) {
        switch (state) {
          case 0:
            state = 1;
            if (line) context.lineTo(x, y);
            else context.moveTo(x, y);
            break;
          default: {
            // The second point and every one after it (d3 falls through from the second to the rest).
            if (state === 1) state = 2;
            if (t <= 0) {
              context.lineTo(px, y);
              context.lineTo(x, y);
            } else {
              const x1 = px * (1 - t) + x * t;
              context.lineTo(x1, py);
              context.lineTo(x1, y);
            }
            break;
          }
        }
        px = x;
        py = y;
      },
    };
  };
}

export const curveStep = curveStepWith(0.5);
export const curveStepAfter = curveStepWith(1);
export const curveStepBefore = curveStepWith(0);

function sign(x: number): number {
  return x < 0 ? -1 : 1;
}

/** A smooth curve that never overshoots, monotone in x: it rises where the data rises and falls where it falls - d3.curveMonotoneX (Steffen's method). */
export const curveMonotoneX: CurveFactory = (context) => {
  let line: number | undefined;
  let state = 0;
  let x0 = NaN;
  let y0 = NaN;
  let x1 = NaN;
  let y1 = NaN;
  let t0 = NaN;

  // Calculate the slopes of the tangents (Hermite-type interpolation) based on the following paper: Steffen, M. 1990. A Simple Method for Monotonic Interpolation in One Dimension.
  const slope3 = (x2: number, y2: number): number => {
    const h0 = x1 - x0;
    const h1 = x2 - x1;
    const s0 = (y1 - y0) / (h0 || (h1 < 0 && -0) || 0);
    const s1 = (y2 - y1) / (h1 || (h0 < 0 && -0) || 0);
    const p = (s0 * h1 + s1 * h0) / (h0 + h1);
    return (sign(s0) + sign(s1)) * Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(p)) || 0;
  };
  // Calculate a one-sided slope.
  const slope2 = (t: number): number => {
    const h = x1 - x0;
    return h ? ((3 * (y1 - y0)) / h - t) / 2 : t;
  };
  // According to https://en.wikipedia.org/wiki/Cubic_Hermite_spline#Representations "you can express cubic Hermite interpolation in terms of cubic Bézier curves with respect to the four values p0, p0 + m0 / 3, p1 - m1 / 3, p1".
  const point = (ta: number, tb: number): void => {
    const dx = (x1 - x0) / 3;
    context.bezierCurveTo(x0 + dx, y0 + dx * ta, x1 - dx, y1 - dx * tb, x1, y1);
  };

  return {
    lineStart() {
      x0 = x1 = y0 = y1 = t0 = NaN;
      state = 0;
    },
    lineEnd() {
      switch (state) {
        case 2:
          context.lineTo(x1, y1);
          break;
        case 3:
          point(t0, slope2(t0));
          break;
      }
      if (line || (line !== 0 && state === 1)) context.closePath();
      line = 1 - (line as number);
    },
    point(x, y) {
      let t1 = NaN;
      if (x === x1 && y === y1) return; // Ignore coincident points.
      switch (state) {
        case 0:
          state = 1;
          if (line) context.lineTo(x, y);
          else context.moveTo(x, y);
          break;
        case 1:
          state = 2;
          break;
        case 2:
          state = 3;
          t1 = slope3(x, y);
          point(slope2(t1), t1);
          break;
        default:
          t1 = slope3(x, y);
          point(t0, t1);
          break;
      }
      x0 = x1;
      x1 = x;
      y0 = y1;
      y1 = y;
      t0 = t1;
    },
  };
};

/** A line through points, broken where `defined` says a point is not drawn - d3.line. */
export function linePath<T>(points: readonly T[], x: (p: T) => number, y: (p: T) => number, defined: (p: T) => boolean, curve: CurveFactory, context: PathRecorder): void {
  const output = curve(context);
  const n = points.length;
  let defined0 = false;
  for (let i = 0; i <= n; ++i) {
    if (!(i < n && defined(points[i])) === defined0) {
      if ((defined0 = !defined0)) output.lineStart();
      else output.lineEnd();
    }
    if (defined0) output.point(+x(points[i]), +y(points[i]));
  }
}

// ---------------------------------------------------------------- pies and arcs

const tau = 2 * Math.PI;
const epsilon = 1e-12;

/** One slice of a pie: its datum, its place in the order the slices go round, and its angles from twelve o'clock, clockwise. */
export interface PieArc<T> {
  readonly data: T;
  readonly value: number;
  readonly index: number;
  readonly startAngle: number;
  readonly endAngle: number;
  readonly padAngle: number;
}

/** The angles of a pie's slices - d3.pie, from 0 to 2π with no padding, sorted by descending value unless `keepOrder`, which keeps the data's order. */
export function pie<T>(data: readonly T[], value: (d: T) => number, keepOrder: boolean): PieArc<T>[] {
  const n = data.length;
  let sum = 0;
  const index = new Array<number>(n);
  const values = new Array<number>(n);
  const arcs = new Array<PieArc<T>>(n);
  const a0 = 0;
  const da = Math.min(tau, Math.max(-tau, tau - a0));
  for (let i = 0; i < n; ++i) {
    index[i] = i;
    const v = (values[i] = +value(data[i]));
    if (v > 0) sum += v;
  }
  // The sort is stable, so equal values keep the data's order.
  if (!keepOrder) index.sort((i, j) => values[j] - values[i]);
  const k = sum ? da / sum : 0;
  let start = a0;
  for (let i = 0; i < n; ++i) {
    const j = index[i];
    const v = values[j];
    const end = start + (v > 0 ? v * k : 0);
    arcs[j] = { data: data[j], index: i, value: v, startAngle: start, endAngle: end, padAngle: 0 };
    start = end;
  }
  return arcs;
}

/** An annular sector - d3.arc with no corner rounding and no padding - centred on (cx, cy). */
export function arcPath(cx: number, cy: number, innerRadius: number, outerRadius: number, startAngle: number, endAngle: number): VectorPath {
  let r0 = innerRadius;
  let r1 = outerRadius;
  const a0 = startAngle - Math.PI / 2;
  const a1 = endAngle - Math.PI / 2;
  const da = Math.abs(a1 - a0);
  const cw = a1 > a0;
  const path = new VectorPath();
  const deg = (r: number) => (r * 180) / Math.PI;
  // Ensure that the outer radius is always larger than the inner radius.
  if (r1 < r0) [r0, r1] = [r1, r0];
  // Arcs on a circle of radius r from a to b, drawn the way d3-path's arc draws one: a line from the current point to its start, then the arc.
  const arc = (r: number, from: number, to: number, anticlockwise: boolean): void => {
    let sweep = to - from;
    if (anticlockwise && sweep > 0) sweep -= tau * Math.ceil(sweep / tau);
    if (!anticlockwise && sweep < 0) sweep += tau * Math.ceil(-sweep / tau);
    path.arcTo(rectOf(cx, cy, r), deg(from), deg(Math.abs(sweep) > tau ? Math.sign(sweep) * tau : sweep), false);
  };

  // Is it a point?
  if (!(r1 > epsilon)) path.moveTo(cx, cy);
  // Or is it a circle or annulus?
  else if (da > tau - epsilon) {
    path.moveTo(cx + r1 * Math.cos(a0), cy + r1 * Math.sin(a0));
    arc(r1, a0, a1, !cw);
    if (r0 > epsilon) {
      path.moveTo(cx + r0 * Math.cos(a1), cy + r0 * Math.sin(a1));
      arc(r0, a1, a0, cw);
    }
  }
  // Or is it a circular or annular sector?
  else {
    path.moveTo(cx + r1 * Math.cos(a0), cy + r1 * Math.sin(a0));
    arc(r1, a0, a1, !cw);
    // Is there no inner ring, and it's a circular sector? Or perhaps it's an annular sector collapsed due to padding?
    if (!(r0 > epsilon)) path.lineTo(cx, cy);
    else arc(r0, a1, a0, cw);
  }
  path.close();
  return path;
}


function rectOf(cx: number, cy: number, r: number): RectF {
  return new RectF(cx - r, cy - r, cx + r, cy + r);
}
