// Text placed at data points: names beside points, values on a line's end, a note on a peak.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Layers/Annotations.cs (Labels; the rectangles, rules and bands of that file are
// not drawn by Dhole).

import { withOpacity } from "../color-math";
import { ChartLayerPlan, xScale, yOf, type ChartTraining } from "../contracts";
import { Layer, type DrawContext, type PlanContext, type TextAnchor } from "../figure";
import { Series } from "../series";
import { Check, project } from "./lines";
import { drawPoint } from "./marks";

/** Which point of a label sits on its data point. */
export type LabelAnchor = "center" | "above" | "below" | "left" | "right";

/** Text placed at data points, set in the theme's ink rather than a series colour so it reads on any background; the layer's colour overrides that when the words must match something. */
export class Labels extends Layer {
  readonly x: Series;
  readonly y: Series;
  readonly text: Series;
  /** Which side of its point each label sits on. */
  anchor: LabelAnchor = "above";
  /** How far from its point a label sits, in pixels. */
  offset = 4;
  /** Whether a dot marks each point as well. */
  dots = false;

  constructor(x: readonly number[], y: readonly number[], text: readonly string[]) {
    super();
    this.x = Series.ofNumbers(x);
    this.y = Series.ofNumbers(y);
    this.text = Series.ofTexts(text);
  }

  plan(_context: PlanContext): LabelsPlan {
    Check.sameLength(this.x, this.y, "x", "y");
    Check.sameLength(this.x, this.text, "x", "text");
    return new LabelsPlan(this);
  }
}

class LabelsPlan extends ChartLayerPlan {
  constructor(private readonly labels: Labels) {
    super(labels);
  }

  override train(training: ChartTraining): void {
    training.x.add(this.labels.x);
    training.yOf(this.labels).add(this.labels.y);
  }

  override get clipToPlot(): boolean {
    return false;
  }

  draw(context: DrawContext): void {
    const labels = this.labels;
    const x = xScale(context);
    const y = yOf(context, labels);
    const ink = labels.color ?? context.theme.ink;
    const offset = labels.offset;
    for (let i = 0; i < labels.x.count; i++) {
      const px = project(x, labels.x, i);
      const py = project(y, labels.y, i);
      if (!Number.isFinite(px) || !Number.isFinite(py)) continue;
      if (labels.dots) drawPoint(context.sink, px, py, "circle", context.theme.pointSize * 0.75, ink, context.surface, context.theme.pointRing);
      const [dx, dy, anchor]: [number, number, TextAnchor] =
        labels.anchor === "above" ? [0, -offset, "bottom"] : labels.anchor === "below" ? [0, offset, "top"] : labels.anchor === "left" ? [-offset, 0, "right"] : labels.anchor === "right" ? [offset, 0, "left"] : [0, 0, "center"];
      context.text.draw(context.sink, labels.text.text(i), px + dx, py + dy, "dataLabel", withOpacity(ink, labels.opacity), anchor);
    }
  }
}
