// The colour arithmetic a chart needs: blending, opacity, and which ink reads on a fill.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Styling/ColorMath.cs.

import type { Colour } from "./theme";
import { roundHalfEven } from "../rendering/tones";

const byte = (v: number): number => Math.min(255, Math.max(0, roundHalfEven(v)));

/** The colour a fraction `t` of the way from `a` to `b`, alpha included, rounded rather than truncated. */
export function lerp(a: Colour, b: Colour, t: number): Colour {
  t = Math.min(Math.max(t, 0), 1);
  return { r: byte(a.r + (b.r - a.r) * t), g: byte(a.g + (b.g - a.g) * t), b: byte(a.b + (b.b - a.b) * t), a: byte(a.a + (b.a - a.a) * t) };
}

/** The colour with its alpha multiplied by `opacity`. */
export function withOpacity(colour: Colour, opacity: number): Colour {
  return { ...colour, a: byte(colour.a * Math.min(Math.max(opacity, 0), 1)) };
}

/** WCAG relative luminance, 0 for black to 1 for white. */
export function luminance(colour: Colour): number {
  const channel = (value: number): number => {
    const c = value / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * channel(colour.r) + 0.7152 * channel(colour.g) + 0.0722 * channel(colour.b);
}

/** The WCAG contrast ratio between two opaque colours. */
export function contrast(a: Colour, b: Colour): number {
  const la = luminance(a);
  const lb = luminance(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

/** A translucent colour as it looks over an opaque background. */
export function over(colour: Colour, background: Colour): Colour {
  const a = colour.a / 255;
  return { r: byte(colour.r * a + background.r * (1 - a)), g: byte(colour.g * a + background.g * (1 - a)), b: byte(colour.b * a + background.b * (1 - a)), a: 255 };
}

/** Whichever of `dark` and `light` reads better on `fill`: the text set inside a bar, a tile or a slice. */
export function inkOn(fill: Colour, dark: Colour, light: Colour): Colour {
  return contrast(fill, dark) >= contrast(fill, light) ? dark : light;
}
