// The chart kinds: pies and donuts; bar, line, scatter and radar charts; quadrant charts. Ported from Parcel NExT's
// Divooka.Visualization.Dhole/Kinds/Charts.cs.
//
// Unlike the diagrams, a pie, a bar, a line, a scatter or a radar chart is not laid out here: it becomes a chart of the plotting
// framework's layers (Pie, Bars, Line, Area, Points, TrendLine, Labels, Radar), which the figure renderer draws with axes, ticks,
// gridlines and a legend - exactly as Divooka draws them. A quadrant chart is a scene laid out here, like the diagrams. Importing this
// module registers the chart machinery with the renderer (plot/frames), so a page that draws only diagrams carries none of it.

import { registerKind, KindParser, DiagramSpec, setting, type Built, type BuildContext, type ReadContext, type Setting } from "../syntax/reader";
import type { Block, Span } from "../syntax/source";
import { isWhiteSpace } from "../syntax/source";
import { Said, type ProblemList } from "../syntax/problems";
import * as Scan from "../syntax/scan";
import { DiagramLayer, Scene, TextSetter, shapeMark, type TextMark } from "../rendering/scene";
import { Tone } from "../rendering/tones";
import { RectF, VectorPath } from "../rendering/geometry";
import { FontWeights } from "../plot/text";
import type { Theme, Colour } from "../plot/theme";
import { type Chart, type Layer } from "../plot/figure";
import { defaultAxis } from "../plot/axis";
import { customDecimal } from "../plot/formatting";
import { Series } from "../plot/series";
import { Pie, Radar, type SliceLabel } from "../plot/layers/radial-layers";
import { Bars } from "../plot/layers/bars";
import { Area, Line, Points, type StackMode } from "../plot/layers/lines";
import { Labels } from "../plot/layers/annotations";
import { TrendLine } from "../plot/layers/statistical-layers";
import type { LineShape } from "../plot/layers/marks";
import "../plot/frames";
import { AttributeWords } from "./attribute-words";


/** "1 slice" or "2 slices": the plural of a count. */
const s = (count: number): string => (count === 1 ? "" : "s");

/** The ends of a list, as C#'s Enumerable.Range(1, n) gives them. */
const oneTo = (n: number): number[] => Array.from({ length: n }, (_, i) => i + 1);

// ---------------------------------------------------------------- pies

export class PieSpec extends DiagramSpec {
  readonly slices: { name: string; value: number }[] = [];
  hole = 0;
  labels: SliceLabel = "percent";
  keepOrder = false;
  centre: string | null = null;

  override get isEmpty(): boolean {
    return this.slices.length === 0;
  }

  build(_problems: ProblemList, _context: BuildContext): Built {
    const pie = new Pie(
      this.slices.map((x) => x.name),
      this.slices.map((x) => x.value),
    );
    pie.hole = this.hole;
    pie.keepOrder = this.keepOrder;
    pie.sliceLabels = this.labels;
    pie.centerText = this.hole > 0 ? this.centre : null;
    const total = this.slices.reduce((sum, x) => sum + x.value, 0);
    return {
      chart: chartOf(pie),
      naturalWidth: null,
      naturalHeight: null,
      summary: `A ${this.hole > 0 ? "donut" : "pie"} chart of ${this.slices.length} slice${s(this.slices.length)} adding up to ${customDecimal(total, 3, false)}.`,
    };
  }
}

/** A pie: a slice per line, its name, a colon and its amount; `hole` makes it a donut. */
class PieParser extends KindParser {
  private readonly own: PieSpec;

  constructor(context: ReadContext) {
    super(context);
    this.own = new PieSpec(context.kind, context.kindLine);
    if (context.kindWord === "donut" || context.kindWord === "doughnut" || context.kindWord === "ring") this.own.hole = 0.6;
  }

  get spec(): DiagramSpec {
    return this.own;
  }

  protected override get settings(): Setting[] {
    const spec = this.own;
    return [
      setting(["hole", "donut"], (v) => {
        const on = Scan.switchValue(v.text);
        if (on !== null) {
          spec.hole = on ? 0.6 : 0;
          return;
        }
        const hole = this.readNumber(v, true);
        if (hole !== null) spec.hole = Math.min(Math.max(hole > 1 ? hole / 100 : hole, 0), 0.9);
      }),
      setting(["labels", "show", "slices"], (v) => {
        const l = this.readChoice<SliceLabel>(
          v,
          "labels",
          [["percent", "percentage", "share", "shares"], "percent"],
          [["value", "values", "amount", "amounts"], "value"],
          [["name", "names"], "name"],
          [["name and percent", "both", "all"], "nameAndPercent"],
          [["none", "off", "nothing"], "none"],
        );
        if (l !== null) spec.labels = l;
      }),
      setting(["order", "sort"], (v) => {
        const keep = this.readChoice<boolean>(v, "order", [["size", "largest first", "biggest first", "value"], false], [["written", "as written", "given", "keep", "text"], true]);
        if (keep !== null) spec.keepOrder = keep;
      }),
      setting(["centre", "center", "middle", "total"], (v) => (spec.centre = this.text(v))),
    ];
  }

  protected content(block: Block): void {
    const content = block.content;
    let { head, tail } = Scan.splitColon(content);
    // Mermaid writes a slice as "Name" : 30, and old Dhole as Slice: Name, 30: both are read.
    if (tail !== null && Scan.key(head.text) === "slice") {
      const parts = Scan.list(tail);
      if (parts.length === 2) {
        head = parts[0];
        tail = parts[1];
      }
    }
    if (tail === null || head.isEmpty) {
      this.problems.error(content, "NoData");
      return;
    }
    if (this.settingSlip(head, tail)) return;
    const name = Scan.name(head, this.problems);
    const value = this.readNumber(tail);
    if (value !== null) {
      if (value <= 0) this.problems.warning(content, "SliceNotPositive", name);
      else this.own.slices.push({ name, value });
    }
    this.unindent(block, (b) => this.content(b));
  }

  protected override finish(): void {
    if (this.own.slices.length === 0) this.problems.error(this.context.kindLine.content, "NoData");
  }
}

// ---------------------------------------------------------------- bars, lines, points and webs

type ChartShape = "bar" | "line" | "xy" | "radar";

/** One series as read: its name, its values (or its points, on a scatter chart) and its colour. */
export class SeriesData {
  readonly values: number[] = [];
  readonly points: { x: number; y: number }[] = [];
  hue: Tone | null = null;
  constructor(readonly name: string) {}
}

export class SeriesSpec extends DiagramSpec {
  readonly shape: ChartShape;
  labels: string[] | null = null;
  readonly series: SeriesData[] = [];
  xTitle: string | null = null;
  yTitle: string | null = null;
  yRange: { low: number; high: number } | null = null;
  xRange: { low: number; high: number } | null = null;
  stack: StackMode = "grouped";
  horizontal = false;
  valueLabels = false;
  curve: LineShape = "straight";
  markers = false;
  area = false;
  trend = false;
  connect = false;

  constructor(context: ReadContext, shape: ChartShape) {
    super(context.kind, context.kindLine);
    this.shape = shape;
  }

  override get isEmpty(): boolean {
    return this.series.length === 0;
  }

  build(_problems: ProblemList, _context: BuildContext): Built {
    const layers: Layer[] = [];
    let summary: string;
    const maxCount = (): number => (this.series.length === 0 ? 0 : Math.max(...this.series.map((x) => x.values.length)));
    switch (this.shape) {
      case "bar":
        if (this.labels === null) {
          // A bar per line, each line's one value.
          const bars = new Bars(
            this.series.map((x) => x.name),
            this.series.map((x) => x.values[0] ?? 0),
          );
          bars.horizontal = this.horizontal;
          bars.valueLabels = this.valueLabels;
          layers.push(bars);
          summary = `A bar chart of ${this.series.length} bar${s(this.series.length)}.`;
        } else {
          const categories: string[] = [];
          const groups: string[] = [];
          const values: number[] = [];
          for (const series of this.series)
            for (let i = 0; i < this.labels.length; i++) {
              categories.push(this.labels[i]);
              groups.push(series.name);
              values.push(i < series.values.length ? series.values[i] : NaN);
            }
          const bars = new Bars(Series.ofTexts(categories), values);
          bars.colorBy = this.series.length > 1 ? Series.ofTexts(groups) : null;
          bars.mode = this.stack;
          bars.horizontal = this.horizontal;
          bars.valueLabels = this.valueLabels;
          layers.push(bars);
          summary = `A bar chart of ${this.series.length} series over ${this.labels.length} label${s(this.labels.length)}.`;
        }
        break;
      case "line": {
        const x = this.labels !== null ? Series.ofTexts(this.labels) : Series.ofNumbers(oneTo(maxCount()));
        for (const series of this.series) {
          const y = Array.from({ length: x.count }, (_, i) => (i < series.values.length ? series.values[i] : NaN));
          if (this.area) {
            const area = new Area(x, y);
            area.label = series.name;
            area.shape = this.curve;
            area.stack = this.stack;
            area.color = this.colour(series);
            layers.push(area);
          } else {
            const line = new Line(x, y);
            line.label = series.name;
            line.shape = this.curve;
            line.markers = this.markers;
            line.color = this.colour(series);
            layers.push(line);
          }
        }
        summary = `A line chart of ${this.series.length} line${s(this.series.length)} over ${x.count} point${s(x.count)}.`;
        break;
      }
      case "xy": {
        const named: { name: string; x: number; y: number }[] = [];
        let colour = 0;
        for (const series of this.series) {
          if (series.points.length === 1 && series.values.length === 0 && SeriesSpec.isLabelledPoint(series)) {
            named.push({ name: series.name, x: series.points[0].x, y: series.points[0].y });
            continue;
          }
          const xs = series.points.map((p) => p.x);
          const ys = series.points.map((p) => p.y);
          // A series and its trend share a colour, so the fit reads as the points' own.
          const own = this.colour(series) ?? this.theme.palette.at(colour++);
          if (this.connect) {
            const line = new Line(xs, ys);
            line.label = series.name;
            line.markers = true;
            line.color = own;
            layers.push(line);
          } else {
            const points = new Points(xs, ys);
            points.label = series.name;
            points.color = own;
            layers.push(points);
          }
          if (this.trend && xs.length >= 2) {
            const fit = new TrendLine(xs, ys);
            fit.label = null;
            fit.confidenceBand = false;
            fit.color = own;
            layers.push(fit);
          }
        }
        if (named.length > 0) {
          layers.push(
            new Points(
              named.map((p) => p.x),
              named.map((p) => p.y),
            ),
          );
          const labels = new Labels(
            named.map((p) => p.x),
            named.map((p) => p.y),
            named.map((p) => p.name),
          );
          labels.anchor = "right";
          labels.offset = 8;
          layers.push(labels);
        }
        const points = this.series.reduce((sum, x) => sum + x.points.length, 0);
        summary = `A scatter chart of ${points} point${s(points)}${this.series.length - named.length > 1 ? ` in ${this.series.length - named.length} series` : ""}.`;
        break;
      }
      default: {
        const spokes = this.labels ?? oneTo(maxCount()).map(String);
        for (const series of this.series) {
          const radar = new Radar(
            spokes,
            spokes.map((_, i) => (i < series.values.length ? series.values[i] : 0)),
          );
          radar.label = series.name;
          radar.color = this.colour(series);
          layers.push(radar);
        }
        summary = `A radar chart of ${this.series.length} subject${s(this.series.length)} on ${spokes.length} spoke${s(spokes.length)}.`;
        break;
      }
    }
    let chart: Chart = { layers, x: defaultAxis, y: defaultAxis };
    const across = this.horizontal && this.shape === "bar";
    if (this.xTitle !== null || this.yTitle !== null)
      chart = across ? { ...chart, x: { ...chart.x!, title: this.yTitle }, y: { ...chart.y!, title: this.xTitle } } : { ...chart, x: { ...chart.x!, title: this.xTitle }, y: { ...chart.y!, title: this.yTitle } };
    if (this.yRange !== null) {
      const { low, high } = this.yRange;
      chart = across ? { ...chart, x: { ...chart.x!, min: low, max: high } } : { ...chart, y: { ...chart.y!, min: low, max: high } };
    }
    if (this.xRange !== null) chart = { ...chart, x: { ...chart.x!, min: this.xRange.low, max: this.xRange.high } };
    return { chart, naturalWidth: null, naturalHeight: null, summary };
  }

  private static isLabelledPoint(series: SeriesData): boolean {
    return series.name.length > 0 && !series.name.toLowerCase().startsWith("series");
  }

  private colour(series: SeriesData): Colour | null {
    return series.hue !== null ? series.hue.in(this.theme) : null;
  }
}

/** A bar, line, scatter or radar chart: a line per bar or per series - a name, a colon and its numbers - with `labels` naming what the numbers are of. */
class SeriesParser extends KindParser {
  private readonly own: SeriesSpec;
  private sawOne = false;
  private sawMany = false;
  private mixedAt: Span | null = null;
  /** The line each series was read from, for a problem with its values. */
  private readonly lines = new Map<SeriesData, Span>();

  constructor(context: ReadContext, kind: ChartShape) {
    super(context);
    this.own = new SeriesSpec(context, kind);
  }

  get spec(): DiagramSpec {
    return this.own;
  }

  protected override get settings(): Setting[] {
    const spec = this.own;
    const settings: Setting[] = [
      setting(["labels", "categories", "x labels", "spokes", "axes", "columns"], (v) => (spec.labels = Scan.list(v).filter((p) => !p.isEmpty).map((p) => Scan.name(p, this.problems)))),
      setting(["x axis", "x title", "xaxis", "horizontal axis"], (v) => (spec.xTitle = this.text(v))),
      setting(["y axis", "y title", "yaxis", "vertical axis"], (v) => (spec.yTitle = this.text(v))),
      setting(["range", "y range", "scale"], (v) => (spec.yRange = this.readRange(v))),
    ];
    switch (spec.shape) {
      case "bar":
        settings.push(
          setting(["stack", "stacked"], (v) => {
            const k = Scan.key(v.text);
            if (k === "percent" || k === "100" || k === "100percent" || k === "share") {
              spec.stack = "percent";
              return;
            }
            const on = this.readSwitch(v);
            if (on !== null) spec.stack = on ? "stacked" : "grouped";
          }),
        );
        settings.push(
          setting(["direction", "orientation", "bars"], (v) => {
            const across = this.readChoice<boolean>(v, "direction", [["up", "vertical", "columns", "column"], false], [["right", "horizontal", "across", "sideways", "rows"], true]);
            if (across !== null) spec.horizontal = across;
          }),
        );
        settings.push(
          setting(["values", "value labels", "numbers"], (v) => {
            const on = this.readSwitch(v);
            if (on !== null) spec.valueLabels = on;
          }),
        );
        break;
      case "line":
        settings.push(
          setting(["shape", "curve", "lines"], (v) => {
            const shape = this.readChoice<LineShape>(v, "shape", [["straight", "linear"], "straight"], [["smooth", "curved", "round"], "smooth"], [["step", "steps", "stepped"], "stepAfter"]);
            if (shape !== null) spec.curve = shape;
          }),
        );
        settings.push(
          setting(["points", "markers", "dots"], (v) => {
            const on = this.readSwitch(v);
            if (on !== null) spec.markers = on;
          }),
        );
        settings.push(
          setting(["area", "fill", "filled"], (v) => {
            const on = this.readSwitch(v);
            if (on !== null) spec.area = on;
          }),
        );
        settings.push(
          setting(["stack", "stacked"], (v) => {
            const on = this.readSwitch(v);
            if (on !== null) spec.stack = on ? "stacked" : "grouped";
          }),
        );
        break;
      case "xy":
        settings.push(setting(["x range"], (v) => (spec.xRange = this.readRange(v))));
        settings.push(
          setting(["trend", "fit", "trend line"], (v) => {
            const on = this.readSwitch(v);
            if (on !== null) spec.trend = on;
          }),
        );
        settings.push(
          setting(["lines", "connect", "joined"], (v) => {
            const on = this.readSwitch(v);
            if (on !== null) spec.connect = on;
          }),
        );
        break;
    }
    return settings;
  }

  protected content(block: Block): void {
    const content = block.content;
    const { head, tail } = Scan.splitColon(content);
    if (tail === null) {
      // Old Dhole's "Series: 10, 20" and a bare list of numbers both read as a series of their own.
      this.problems.error(content, "NoData");
      return;
    }
    if (this.settingSlip(head, tail)) return;
    const name = Scan.reference(head, this.problems);
    const data = new SeriesData(name.name);
    for (const attribute of name.attributes) {
      const hue = AttributeWords.hue(attribute.text);
      if (hue !== null) data.hue = Tone.hue(hue);
      else this.unknownAttribute(attribute, new Said("a series", "数据系列"), AttributeWords.names);
    }
    const values = tail;
    if (this.own.shape === "xy" && values.text.includes("(")) {
      for (const point of SeriesParser.points(values)) {
        const inner = trimEnd(trimStart(point.text.trim(), "("), ")");
        const parts = inner.split(",").map((p) => p.trim());
        const px = parts.length === 2 ? Scan.tryNumber(parts[0]) : NaN;
        const py = parts.length === 2 ? Scan.tryNumber(parts[1]) : NaN;
        if (parts.length === 2 && !Number.isNaN(px) && !Number.isNaN(py)) data.points.push({ x: px, y: py });
        else this.problems.error(point, "PointNotPair", point.text.trim());
      }
    } else {
      let pieces = Scan.list(values);
      // Numbers apart by spaces read as well as by commas.
      if (pieces.length === 1 && pieces[0].text.includes(" ")) pieces = SeriesParser.splitSpaces(pieces[0]);
      for (const piece of pieces) {
        if (piece.isEmpty) continue;
        const number = Scan.tryNumber(piece.text);
        if (!Number.isNaN(number)) data.values.push(number);
        else this.problems.error(piece, "BadNumber", piece.text);
      }
      if (this.own.shape === "xy" && data.values.length === 2) {
        data.points.push({ x: data.values[0], y: data.values[1] });
        data.values.length = 0;
      }
    }
    if (data.values.length === 1) this.sawOne = true;
    if (data.values.length > 1) this.sawMany = true;
    if (this.sawOne && this.sawMany && this.mixedAt === null) this.mixedAt = content;
    this.own.series.push(data);
    this.lines.set(data, content);
    this.unindent(block, (b) => this.content(b));
  }

  private static points(values: Span): Span[] {
    const out: Span[] = [];
    let start = -1;
    for (let i = 0; i < values.length; i++) {
      if (values.at(i) === "(") start = i;
      else if (values.at(i) === ")" && start >= 0) {
        out.push(values.slice(start, i - start + 1));
        start = -1;
      }
    }
    return out;
  }

  private static splitSpaces(span: Span): Span[] {
    const pieces: Span[] = [];
    let start = -1;
    for (let i = 0; i <= span.length; i++) {
      const space = i === span.length || isWhiteSpace(span.at(i));
      if (!space && start < 0) start = i;
      else if (space && start >= 0) {
        pieces.push(span.slice(start, i - start));
        start = -1;
      }
    }
    return pieces;
  }

  protected override finish(): void {
    const spec = this.own;
    // Old Dhole's xy: two lines called X and Y are one series' coordinates.
    if (spec.shape === "xy" && spec.series.length === 2 && Scan.key(spec.series[0].name) === "x" && Scan.key(spec.series[1].name) === "y") {
      const [xs, ys] = spec.series;
      const xv = [...xs.values, ...xs.points.flatMap((p) => [p.x, p.y])];
      const yv = [...ys.values, ...ys.points.flatMap((p) => [p.x, p.y])];
      const joined = new SeriesData("Series");
      for (let i = 0; i < Math.min(xv.length, yv.length); i++) joined.points.push({ x: xv[i], y: yv[i] });
      spec.series.length = 0;
      spec.series.push(joined);
    }
    if (spec.series.length === 0) {
      this.problems.error(this.context.kindLine.content, "NoData");
      return;
    }
    if (spec.shape === "bar" && spec.labels === null && this.sawMany) {
      // Several numbers on a line with no labels: the numbers are counted 1, 2, 3 along the axis.
      spec.labels = oneTo(Math.max(...spec.series.map((x) => x.values.length))).map(String);
      if (this.sawOne && this.mixedAt !== null) this.problems.warning(this.mixedAt, "MixedSeries", spec.kind.name);
    }
    if (spec.labels !== null)
      for (const series of spec.series)
        if (series.values.length > 0 && series.values.length !== spec.labels.length) {
          // Said on the series' own line, where its values are to be mended.
          const line = this.lines.get(series);
          if (line !== undefined) this.problems.warning(line, "ValueCountMismatch", series.name, series.values.length, spec.labels.length);
          else this.problems.warningAt(this.context.kindLine.number, 1, 1, "ValueCountMismatch", series.name, series.values.length, spec.labels.length);
        }
  }
}

/** C#'s TrimStart(char): every leading `c` removed. */
function trimStart(text: string, chars: string): string {
  let i = 0;
  while (i < text.length && chars.includes(text[i])) i++;
  return text.slice(i);
}

/** C#'s TrimEnd(char): every trailing `c` removed. */
function trimEnd(text: string, chars: string): string {
  let i = text.length;
  while (i > 0 && chars.includes(text[i - 1])) i--;
  return text.slice(0, i);
}

// ---------------------------------------------------------------- quadrants

interface QuadrantItem {
  readonly name: string;
  readonly x: number;
  readonly y: number;
  readonly hue: Tone | null;
}

export class QuadrantSpec extends DiagramSpec {
  xLow = "";
  xHigh = "";
  yLow = "";
  yHigh = "";
  readonly names = ["", "", "", ""];
  readonly items: QuadrantItem[] = [];
  low = 0;
  high = 1;

  build(_problems: ProblemList, context: BuildContext): Built {
    const scene = QuadrantLayout.build(this, this.theme, context);
    const layer = new DiagramLayer(scene, "Quadrant chart", context.measurer);
    layer.label = this.title;
    return { chart: chartOf(layer), naturalWidth: scene.width, naturalHeight: scene.height, summary: `A quadrant chart of ${this.items.length} point${s(this.items.length)}.` };
  }
}

/** A quadrant chart: what each axis runs from and to, the four quadrants' names, and a point per line - its name, a colon and where it lies. */
class QuadrantParser extends KindParser {
  private readonly own: QuadrantSpec;
  private readonly pending: { where: Span; name: string; x: number; y: number; hue: Tone | null }[] = [];

  constructor(context: ReadContext) {
    super(context);
    this.own = new QuadrantSpec(context.kind, context.kindLine);
  }

  get spec(): DiagramSpec {
    return this.own;
  }

  protected override get settings(): Setting[] {
    const spec = this.own;
    return [
      setting(["x axis", "x", "horizontal", "xaxis"], (v) => ([spec.xLow, spec.xHigh] = QuadrantParser.ends(v))),
      setting(["y axis", "y", "vertical", "yaxis"], (v) => ([spec.yLow, spec.yHigh] = QuadrantParser.ends(v))),
      setting(["top right", "quadrant 1", "quadrant1", "q1"], (v) => (spec.names[0] = this.text(v))),
      setting(["top left", "quadrant 2", "quadrant2", "q2"], (v) => (spec.names[1] = this.text(v))),
      setting(["bottom left", "quadrant 3", "quadrant3", "q3"], (v) => (spec.names[2] = this.text(v))),
      setting(["bottom right", "quadrant 4", "quadrant4", "q4"], (v) => (spec.names[3] = this.text(v))),
      setting(["range"], (v) => {
        const range = this.readRange(v);
        if (range !== null) {
          spec.low = range.low;
          spec.high = range.high;
        }
      }),
    ];
  }

  /** An axis' two ends: `Low effort .. High effort`, or `Low effort -> High effort`. */
  private static ends(value: Span): [string, string] {
    const text = value.text;
    for (const separator of ["..", "-->", "->", "→", " to "]) {
      const at = text.toLowerCase().indexOf(separator);
      if (at > 0) return [QuadrantParser.unquote(text.slice(0, at)), QuadrantParser.unquote(text.slice(at + separator.length))];
    }
    return ["", QuadrantParser.unquote(text)];
  }

  private static unquote(text: string): string {
    return trimEnd(trimStart(text.trim(), '"“”'), '"“”').trim();
  }

  protected content(block: Block): void {
    const content = block.content;
    const { head, tail } = Scan.splitColon(content);
    const name = Scan.reference(head, this.problems);
    if (tail === null || name.name.length === 0) {
      this.problems.error(content, "PointNotPair", content.text);
      return;
    }
    if (this.settingSlip(head, tail)) return;
    const text = trimEnd(trimStart(tail.text.trim(), "[("), "])");
    const parts = text.split(",").map((p) => p.trim());
    const x = parts.length === 2 ? Scan.tryNumber(parts[0]) : NaN;
    const y = parts.length === 2 ? Scan.tryNumber(parts[1]) : NaN;
    if (parts.length !== 2 || Number.isNaN(x) || Number.isNaN(y)) {
      this.problems.error(tail, "PointNotPair", tail.text);
      return;
    }
    let hue: Tone | null = null;
    for (const attribute of name.attributes) {
      const h = AttributeWords.hue(attribute.text);
      if (h !== null) hue = Tone.hue(h);
      else this.unknownAttribute(attribute, new Said("a point", "点"), AttributeWords.names);
    }
    this.pending.push({ where: content, name: name.name, x, y, hue });
  }

  protected override finish(): void {
    const spec = this.own;
    for (const { where, name, x, y, hue } of this.pending) {
      if (x < spec.low || x > spec.high || y < spec.low || y > spec.high) this.problems.warning(where, "OutsideRange", name);
      spec.items.push({ name, x: Math.min(Math.max(x, spec.low), spec.high), y: Math.min(Math.max(y, spec.low), spec.high), hue });
    }
  }
}

/** The sizes text is set in, scaled with the theme's own - GraphDiagram.Type of Layout/GraphDiagram.cs. */
function typeFor(theme: Theme): { label: number; small: number; heading: number } {
  const k = theme.fontSize / 11.0;
  return { label: 14 * k, small: 12.5 * k, heading: 14 * k };
}

/** A quadrant chart laid out: a square split at its middles, each quarter washed in its own colour and named in its corner, the axes' ends written along them, the points named beside them. */
export const QuadrantLayout = {
  side: 440,

  build(spec: QuadrantSpec, theme: Theme, context: BuildContext): Scene {
    const Side = QuadrantLayout.side;
    const text = new TextSetter(theme.fontFamilies, context.measurer);
    const type = typeFor(theme);
    const scene = new Scene(theme.fontFamilies);
    const axisRoom = text.measure("Ag", type.small, FontWeights.Normal).height + 12;
    const plot = RectF.fromXYWH(axisRoom, 0, Side, Side);
    const half = Side / 2;
    const quarters: [number, RectF, number][] = [
      [0, RectF.fromXYWH(plot.left + half, plot.top, half, half), 0],
      [1, RectF.fromXYWH(plot.left, plot.top, half, half), 1],
      [2, RectF.fromXYWH(plot.left, plot.top + half, half, half), 2],
      [3, RectF.fromXYWH(plot.left + half, plot.top + half, half, half), 3],
    ];
    for (const [hue, box, name] of quarters) {
      scene.add(shapeMark(new VectorPath().addRect(box), Tone.palette(hue).washed(0.09), null, 0));
      if (spec.names[name].length > 0) scene.add(text.centred(spec.names[name], box.midX, box.top + 22, type.label, FontWeights.SemiBold, Tone.palette(hue).deepened(0.35), half - 24));
    }
    const frame = new VectorPath();
    frame.addRect(plot);
    frame.moveTo(plot.midX, plot.top).lineTo(plot.midX, plot.bottom);
    frame.moveTo(plot.left, plot.midY).lineTo(plot.right, plot.midY);
    scene.add(shapeMark(frame, null, Tone.of("axis"), 1.2));

    // The axes' ends: low at the start, high at the end, an arrow between.
    const below = plot.bottom + 8;
    if (spec.xLow.length > 0) scene.add(text.mark(spec.xLow, plot.left, below, type.small, FontWeights.Normal, Tone.of("secondary")));
    if (spec.xHigh.length > 0) {
      const high = text.mark(spec.xHigh, 0, below, type.small, FontWeights.Normal, Tone.of("secondary"));
      scene.add({ ...high, x: plot.right - high.width });
    }
    if (spec.yLow.length > 0) {
      const low = text.mark(spec.yLow, 0, 0, type.small, FontWeights.Normal, Tone.of("secondary"));
      scene.add({ ...low, x: plot.left - 8 - low.height / 2 - low.width / 2, y: plot.bottom - low.width / 2 - low.height / 2, rotation: -90 });
    }
    if (spec.yHigh.length > 0) {
      const high = text.mark(spec.yHigh, 0, 0, type.small, FontWeights.Normal, Tone.of("secondary"));
      scene.add({ ...high, x: plot.left - 8 - high.height / 2 - high.width / 2, y: plot.top + high.width / 2 - high.height / 2, rotation: -90 });
    }

    const span = spec.high - spec.low;
    for (const item of spec.items) {
      const px = plot.left + ((item.x - spec.low) / span) * Side;
      const py = plot.bottom - ((item.y - spec.low) / span) * Side;
      const hue = item.hue ?? Tone.hue("accent");
      scene.add(shapeMark(new VectorPath().addCircle(px, py, 6.5), hue, Tone.of("background"), 2));
      const label: TextMark = text.mark(item.name, 0, py - text.measure(item.name, type.small, FontWeights.Normal).height / 2, type.small, FontWeights.Normal, Tone.of("ink"));
      const leftSide = px + 12 + label.width > plot.right - 4;
      scene.add({ ...label, x: leftSide ? px - 12 - label.width : px + 12 });
    }
    scene.frame(12);
    return scene;
  },
};

function chartOf(...layers: Layer[]): Chart {
  return { layers };
}

