// Gantt charts: tasks on a calendar, each starting on a date or after the tasks it waits for.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Kinds/Gantt.cs.
//
// A date is a C# DateTime of kind Utc, here milliseconds since 1970 in UTC; a length of time a C# TimeSpan, here milliseconds. Nothing reads the local time zone or the clock.

import type { Block, Span } from "../syntax/source";
import { Said, type ProblemList } from "../syntax/problems";
import * as Scan from "../syntax/scan";
import { DayMs } from "../syntax/scan";
import { DiagramSpec, KindParser, registerKind, setting, type BuildContext, type Built, type ReadContext, type Setting } from "../syntax/reader";
import { RectF, VectorPath, vec } from "../rendering/geometry";
import { Tone } from "../rendering/tones";
import { DiagramLayer, FontWeights, Scene, TextSetter, shapeMark } from "../rendering/scene";
import * as Shapes from "../rendering/shapes";
import { chartOf } from "../plot/figure";
import type { Theme } from "../plot/theme";
import type { TextMeasurer } from "../plot/text";
import { isSectionLine } from "./trees";
import { AttributeWords } from "./attribute-words";
import { typeFor } from "../layout/graph-diagram";
import { dateOf, dayOfWeek, scaleUtc, timeOfDay, utcDate } from "./time-scale";

export type Status = "planned" | "done" | "active" | "critical";

export class Task {
  readonly name: string;
  readonly where: Span;
  readonly section: number;
  start: number | null = null;
  readonly after: { name: string; where: Span }[] = [];
  length: number | null = null;
  end: number | null = null;
  milestone = false;
  state: Status = "planned";
  hue: Tone | null = null;
  from = 0;
  to = 0;
  resolved = false;
  resolving = false;

  constructor(name: string, where: Span, section = -1) {
    this.name = name;
    this.where = where;
    this.section = section;
  }
}

/** C#'s default(DateTime), 0001-01-01, for a summary of no tasks. */
const MinDate = utcDate(1, 0, 1);

/** A date as yyyy-MM-dd. */
export function isoDay(ms: number): string {
  const d = new Date(ms);
  const pad = (n: number, w: number): string => String(n).padStart(w, "0");
  return `${pad(d.getUTCFullYear(), 4)}-${pad(d.getUTCMonth() + 1, 2)}-${pad(d.getUTCDate(), 2)}`;
}

/** Whether two names are one, ignoring case - StringComparison.OrdinalIgnoreCase. */
function sameName(a: string, b: string): boolean {
  return a.toUpperCase() === b.toUpperCase();
}

export class GanttSpec extends DiagramSpec {
  readonly tasks: Task[] = [];
  readonly sections: string[] = [];
  projectStart: number | null = null;
  skipWeekends = false;
  readonly holidays = new Set<number>();
  today: number | null = null;
  dateFormat: string | null = null;

  override get isEmpty(): boolean {
    return this.tasks.length === 0;
  }

  build(_problems: ProblemList, context: BuildContext): Built {
    const scene = GanttLayout.build(this, this.theme, context.measurer);
    const first = this.tasks.length === 0 ? MinDate : Math.min(...this.tasks.map((t) => t.from));
    const last = this.tasks.length === 0 ? MinDate : Math.max(...this.tasks.map((t) => t.to));
    const n = this.tasks.length;
    const layer = new DiagramLayer(scene, "Gantt chart", context.measurer);
    layer.label = this.title;
    return { chart: chartOf(layer), naturalWidth: scene.width, naturalHeight: scene.height, summary: `A Gantt chart of ${n} task${n === 1 ? "" : "s"} from ${isoDay(first)} to ${isoDay(last)}.` };
  }

  /** The day after `from` plus `length`, counting only working days when weekends are skipped. */
  add(from: number, length: number): number {
    if (!this.skipWeekends && this.holidays.size === 0) return from + length;
    let at = from;
    const days = Math.floor(length / DayMs);
    const rest = length - days * DayMs;
    for (let i = 0; i < days; i++) {
      at += DayMs;
      while (this.skipped(at - DayMs)) at += DayMs;
    }
    return at + rest;
  }

  /** Whether a day is not worked: a weekend when weekends are skipped, or a holiday. */
  skipped(day: number): boolean {
    const w = dayOfWeek(day);
    return (this.skipWeekends && (w === 6 || w === 0)) || this.holidays.has(dateOf(day));
  }
}

/**
 * A Gantt chart: `section` lines grouping tasks, and a task per line - its name, a colon, then when it starts (a date, or after other tasks), how long it takes or when it ends, and in brackets whether it is done, active or critical.
 */
export class GanttParser extends KindParser {
  private readonly own: GanttSpec;
  private section = -1;

  constructor(context: ReadContext) {
    super(context);
    this.own = new GanttSpec(context.kind, context.kindLine);
  }

  get spec(): GanttSpec {
    return this.own;
  }

  protected override get settings(): Setting[] {
    return [
      setting(["start", "starts", "begin", "from"], (v) => {
        const d = this.date(v);
        if (d !== null) this.own.projectStart = d;
      }),
      setting(["today", "now", "status date"], (v) => {
        const d = this.date(v);
        if (d !== null) this.own.today = d;
      }),
      setting(["skip", "excludes", "exclude", "holidays"], (v) => {
        for (const part of Scan.list(v)) {
          const key = Scan.key(part.text);
          if (key === "weekends" || key === "weekend" || key === "saturdays" || key === "sundays") this.own.skipWeekends = true;
          else {
            const day = this.date(part);
            if (day !== null) this.own.holidays.add(dateOf(day));
          }
        }
      }),
      setting(["dates", "date format", "axis format", "format"], (v) => (this.own.dateFormat = v.text.trim())),
    ];
  }

  private date(value: Span): number | null {
    const date = Scan.tryDate(value.text);
    if (!Number.isNaN(date)) return date;
    this.problems.error(value, "BadDate", value.text);
    return null;
  }

  protected content(block: Block): void {
    const content = block.content;
    if (isSectionLine(content)) {
      let rest = content.from(7).trim();
      if (rest.length > 0 && rest.at(0) === ":") rest = rest.from(1).trim();
      this.own.sections.push(Scan.name(rest, this.problems));
      this.section = this.own.sections.length - 1;
      for (const child of block.children) this.content(child);
      return;
    }
    const { head, tail } = Scan.splitColon(content);
    const name = Scan.reference(head, this.problems);
    if (name.name.length === 0) {
      this.problems.error(content, "EmptyName");
      return;
    }
    if (this.own.tasks.some((t) => sameName(t.name, name.name))) this.problems.warning(name.nameSpan, "TaskRepeated", name.name);
    const task = new Task(name.name, name.nameSpan, this.section);
    const flags: Span[] = [...name.attributes];
    if (tail !== null) {
      const { remainder: parts, attributes: more } = Scan.trailingAttributes(tail, this.problems);
      flags.push(...more);
      for (const part of Scan.list(parts)) this.part(task, part);
    }
    for (const flag of flags) {
      switch (Scan.key(flag.text)) {
        case "done":
        case "complete":
        case "completed":
        case "finished":
          task.state = "done";
          break;
        case "active":
        case "current":
        case "now":
        case "inprogress":
        case "doing":
          task.state = "active";
          break;
        case "critical":
        case "crit":
        case "urgent":
          task.state = "critical";
          break;
        case "milestone":
          task.milestone = true;
          break;
        default: {
          const hue = AttributeWords.hue(flag.text);
          if (hue !== null) task.hue = Tone.hue(hue);
          else this.unknownAttribute(flag, new Said("a task", "任务"), ["done", "active", "critical", "milestone", "blue", "green", "red"]);
          break;
        }
      }
    }
    this.own.tasks.push(task);
  }

  /** One part of a task's timing: a start date, `after` other tasks, a length, an end, or the word milestone. */
  private part(task: Task, part: Span): void {
    const text = part.text.trim();
    const key = Scan.key(text);
    if (text.length === 0) return;
    if (key === "milestone") {
      task.milestone = true;
      return;
    }
    const lower = text.toLowerCase();
    if (lower.startsWith("after ")) {
      const names = part.trim().from(6);
      for (const name of splitAnd(names)) if (!name.isEmpty) task.after.push({ name: Scan.name(name, this.problems), where: name });
      return;
    }
    for (const word of ["until ", "to ", "ends ", "end "])
      if (lower.startsWith(word)) {
        const end = this.date(part.trim().from(word.length).trim());
        if (end !== null) task.end = end;
        return;
      }
    if (lower.startsWith("from ") || lower.startsWith("on ")) {
      const rest = part.trim().from(text.indexOf(" ") + 1).trim();
      const from = this.date(rest);
      if (from !== null) task.start = from;
      return;
    }
    const length = Scan.tryDuration(text);
    if (!Number.isNaN(length)) {
      task.length = length;
      return;
    }
    const date = Scan.tryDate(text);
    if (!Number.isNaN(date)) {
      // A first date is the start; a second, the end.
      if (task.start === null) task.start = date;
      else task.end = date;
      return;
    }
    this.problems.error(part, "BadDuration", text);
  }

  protected override finish(): void {
    if (this.own.tasks.length === 0) {
      this.problems.error(this.context.kindLine.content, "NoData");
      return;
    }
    let previous: Task | null = null;
    for (const task of this.own.tasks) {
      this.resolve(task, previous);
      previous = task;
    }
  }

  /** When a task starts and ends: after the tasks it waits for, or on its date, or after the task above it, or at the chart's start. */
  private resolve(task: Task, previous: Task | null): void {
    const spec = this.own;
    if (task.resolved) return;
    if (task.resolving) {
      this.problems.error(task.where, "StartsAfterItself", task.name);
      task.from = task.to = spec.projectStart ?? utcDate(2026, 0, 1);
      task.resolved = true;
      return;
    }
    task.resolving = true;
    let start = task.start;
    for (const { name, where } of task.after) {
      const before = spec.tasks.find((t) => sameName(t.name, name));
      if (before === undefined) {
        this.problems.error(where, "UnknownTask", name);
        continue;
      }
      this.resolve(before, null);
      if (start === null || before.to > start) start = before.to;
    }
    if (start === null && task.after.length === 0) start = previous !== null ? previous.to : spec.projectStart;
    if (start === null) {
      this.problems.error(task.where, "NoStartDate", task.name);
      const dated = spec.tasks.filter((t) => t.start !== null).map((t) => t.start!);
      start = dated.length === 0 ? utcDate(2026, 0, 5) : Math.min(...dated);
    }
    // Work does not start on a day off.
    let from = start;
    while ((spec.skipWeekends || spec.holidays.size > 0) && spec.skipped(from) && timeOfDay(from) === 0) from += DayMs;
    let to: number;
    if (task.milestone) to = from;
    else if (task.end !== null) {
      const end = task.end;
      to = timeOfDay(end) === 0 ? end + DayMs : end;
      if (to < from) {
        this.problems.error(task.where, "EndsBeforeStart", task.name);
        to = from + DayMs;
      }
    } else to = spec.add(from, task.length ?? DayMs);
    task.from = from;
    task.to = to;
    task.resolving = false;
    task.resolved = true;
  }
}

/** The names after `after`: apart by commas, or by " and ". */
function* splitAnd(names: Span): Generator<Span> {
  for (const piece of Scan.list(names)) {
    const lower = piece.text.toLowerCase();
    let start = 0;
    let at: number;
    while ((at = lower.indexOf(" and ", start)) >= 0) {
      yield piece.slice(start, at - start).trim();
      start = at + 5;
    }
    yield piece.from(start).trim();
  }
}

/**
 * A Gantt chart laid out: the tasks' names in a column, a bar for each on a calendar axis with D3's time ticks, sections as bands, done tasks quiet, active ones strong, critical ones outlined in red, milestones as diamonds, and a line from each task to the tasks it waits for.
 */
export const GanttLayout = {
  Row: 30,
  Bar: 18,

  build(spec: GanttSpec, theme: Theme, measurer: TextMeasurer): Scene {
    const { Row, Bar } = GanttLayout;
    const text = new TextSetter(theme.fontFamilies, measurer);
    const type = typeFor(theme);
    const scene = new Scene(theme.fontFamilies);
    if (spec.tasks.length === 0) {
      scene.add(text.mark(" ", 0, 0, type.small, FontWeights.Normal, Tone.of("muted")));
      scene.frame(12);
      return scene;
    }
    let first = Math.min(...spec.tasks.map((t) => t.from));
    let last = Math.max(...spec.tasks.map((t) => t.to));
    if (spec.today !== null) {
      const today = spec.today;
      if (today < first) first = today;
      if (today > last) last = today;
    }
    if (last <= first) last = first + DayMs;
    const days = (last - first) / DayMs;
    const axisWidth = Math.min(Math.max(days * 26, 520), 1100);
    const nameWidth =
      Math.max(
        Math.max(...spec.tasks.map((t) => text.measure(t.name, type.small, FontWeights.Normal).width)),
        spec.sections.length === 0 ? 0 : Math.max(...spec.sections.map((s) => text.measure(s, type.small, FontWeights.SemiBold).width)),
      ) + 24;
    const left = nameWidth + 10;
    const scale = scaleUtc().domain(first, last).range(left, left + axisWidth);
    const tickRow = text.measure("Ag", type.small, FontWeights.Normal).height + 12;

    // Rows: a section's name above its tasks, then each task.
    const rows: { task: Task | null; section: number; y: number }[] = [];
    let y = tickRow + 6;
    let section = -2;
    for (const task of spec.tasks) {
      if (task.section !== section && task.section >= 0) {
        rows.push({ task: null, section: task.section, y });
        y += Row * 0.9;
      }
      section = task.section;
      rows.push({ task, section: task.section, y });
      y += Row;
    }
    const bottom = y + 4;

    // Days off, washed, when they are few enough to see.
    if ((spec.skipWeekends || spec.holidays.size > 0) && days <= 120)
      for (let day = dateOf(first); day < last; day += DayMs)
        if (spec.skipped(day)) {
          const x0 = scale.apply(day);
          const x1 = scale.apply(day + DayMs);
          const off = new VectorPath();
          off.addRect(new RectF(Math.max(left, x0), tickRow, Math.min(left + axisWidth, x1), bottom));
          scene.add(shapeMark(off, Tone.of("ink").washed(0.04), null, 0));
        }

    // Sections: a band behind their rows.
    for (let s = 0; s < spec.sections.length; s++) {
      const ys = rows.filter((r) => r.section === s).map((r) => r.y);
      if (ys.length === 0) continue;
      const band = new VectorPath();
      band.addRect(new RectF(0, Math.min(...ys) - 2, left + axisWidth, Math.max(...ys) + Row - 4));
      scene.add(shapeMark(band, Tone.palette(s).washed(0.06), null, 0));
    }

    // Ticks along the top, with lines down through the rows.
    const ticks = scale.ticks(Math.max(2, axisWidth / 90));
    const format = spec.dateFormat !== null && spec.dateFormat.length > 0 ? scale.tickFormat(spec.dateFormat) : scale.tickFormat();
    const grid = new VectorPath();
    for (const tick of ticks) {
      const tx = scale.apply(tick);
      grid.moveTo(tx, tickRow).lineTo(tx, bottom);
      scene.add(text.centred(format(tick), tx, tickRow / 2 - 2, type.small * 0.92, FontWeights.Normal, Tone.of("secondary")));
    }
    scene.add(shapeMark(grid, null, Tone.of("grid"), 1));
    const baseline = new VectorPath();
    baseline.moveTo(left, tickRow).lineTo(left + axisWidth, tickRow);
    scene.add(shapeMark(baseline, null, Tone.of("axis"), 1));

    // Dependencies under the bars: from a task's end to the start of the task waiting for it.
    const rowOf = new Map<Task, number>();
    for (const r of rows) if (r.task !== null) rowOf.set(r.task, r.y + Row / 2 - 2);
    for (const task of spec.tasks)
      for (const { name } of task.after) {
        const before = spec.tasks.find((t) => sameName(t.name, name));
        if (before === undefined || !rowOf.has(before) || !rowOf.has(task)) continue;
        const x0 = scale.apply(before.to);
        const y0 = rowOf.get(before)!;
        const x1 = scale.apply(task.from);
        const y1 = rowOf.get(task)!;
        const link = new VectorPath();
        const elbow = Math.max(x0 + 6, x1 - 8);
        link.moveTo(x0, y0).lineTo(elbow, y0).lineTo(elbow, y1).lineTo(x1 - 6, y1);
        scene.add(shapeMark(link, null, Tone.of("muted"), 1));
        const head = Shapes.end("arrow", vec(x1, y1), vec(1, 0), 7);
        if (head !== null) scene.add(shapeMark(head.path, Tone.of("muted"), null, 0));
      }

    for (const { task, section: s, y: rowY } of rows) {
      if (task === null) {
        scene.add(text.mark(spec.sections[s], 6, rowY + 2, type.small, FontWeights.SemiBold, Tone.palette(s).washed(0.95)));
        continue;
      }
      scene.add(text.mark(task.name, 14, rowY + (Row - 4) / 2 - text.measure(task.name, type.small, FontWeights.Normal).height / 2, type.small, FontWeights.Normal, Tone.of("ink")));
      const hue = task.hue ?? Tone.palette(Math.max(0, task.section));
      const x0 = scale.apply(task.from);
      const x1 = scale.apply(task.to);
      const cy = rowY + Row / 2 - 2;
      if (task.milestone) {
        const box = RectF.fromXYWH(x0 - 8, cy - 8, 16, 16);
        scene.add(
          shapeMark(
            Shapes.outline("diamond", box),
            task.state === "done" ? Tone.of("muted") : hue,
            task.state === "critical" ? Tone.hue("red") : Tone.of("background"),
            task.state === "critical" ? 2 : 1.5,
          ),
        );
        continue;
      }
      const bar = new RectF(x0, cy - Bar / 2, Math.max(x0 + 3, x1), cy + Bar / 2);
      const shape = new VectorPath();
      shape.addRoundRect(bar, 4, 4);
      let fill: Tone;
      let stroke: Tone;
      let width: number;
      switch (task.state) {
        case "done":
          [fill, stroke, width] = [Tone.of("ink").washed(0.12), Tone.of("muted"), 1];
          break;
        case "active":
          [fill, stroke, width] = [hue.washed(0.75), hue, 1.4];
          break;
        case "critical":
          [fill, stroke, width] = [hue.washed(0.35), Tone.hue("red"), 2.2];
          break;
        default:
          [fill, stroke, width] = [hue.washed(0.35), hue.washed(0.9), 1.2];
      }
      scene.add(shapeMark(shape, fill, stroke, width));
    }

    if (spec.today !== null) {
      const tx = scale.apply(spec.today);
      const line = new VectorPath();
      line.moveTo(tx, tickRow - 2).lineTo(tx, bottom);
      scene.add(shapeMark(line, null, Tone.hue("red"), 1.6, "dashed"));
    }
    scene.frame(12);
    return scene;
  },
};

registerKind("gantt", (context) => new GanttParser(context));
