// The colour words every kind shares: the palette's hues by name, and the roles that stand for them.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Kinds/GraphKinds.cs (AttributeWords), where every kind's parser reads them.

import * as Scan from "../syntax/scan";
import type { NamedHue } from "../rendering/tones";

/** The colour words every kind shares: the palette's hues by name, and the roles that stand for them. */
export const AttributeWords = {
  /** Colours by name, and good, bad and warn as the colours they read as. */
  hues: new Map<string, NamedHue>([
    ["blue", "blue"], ["orange", "orange"], ["green", "green"], ["yellow", "yellow"], ["amber", "yellow"], ["gold", "yellow"],
    ["pink", "pink"], ["magenta", "pink"], ["purple", "purple"], ["violet", "purple"], ["red", "red"], ["teal", "teal"], ["cyan", "teal"],
    ["grey", "grey"], ["gray", "grey"], ["accent", "accent"], ["highlight", "accent"], ["primary", "accent"],
    ["good", "green"], ["ok", "green"], ["success", "green"], ["done", "green"], ["yes", "green"],
    ["bad", "red"], ["error", "red"], ["fail", "red"], ["failure", "red"], ["danger", "red"], ["no", "red"],
    ["warn", "yellow"], ["warning", "yellow"], ["caution", "yellow"],
  ]),

  /** The hue a word names, or null. */
  hue(word: string): NamedHue | null {
    return AttributeWords.hues.get(Scan.key(word)) ?? null;
  },

  /** The colour words, for a hint. */
  names: ["blue", "orange", "green", "yellow", "pink", "purple", "red", "teal", "grey", "good", "bad", "warn", "accent"] as readonly string[],
};
