// The drawing every layer shares: paths through points, point symbols, bars with a rounded data end.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Layers/Marks.cs. Of the point symbols only the circle and the ring are ported:
// every point a Dhole chart draws is a circle.

import { ChartPaints } from "../contracts";
import { curveLinear, curveMonotoneX, curveStep, curveStepAfter, curveStepBefore, linePath, PathRecorder, type CurveFactory } from "../d3-shapes";
import type { Sink } from "../sink";
import type { Colour } from "../theme";
import { RectF, VectorPath, type Vec2 } from "../../rendering/geometry";

/** How a line passes through its points: straight segments; a smooth curve that never overshoots; steps changing level halfway between points, at each point (holding the new level after it), or holding each level up to its point; a natural cubic spline. */
export type LineShape = "straight" | "smooth" | "step" | "stepAfter" | "stepBefore" | "spline";

/** The shape of a point. */
export type PointShape = "circle" | "square" | "diamond" | "triangle" | "cross" | "star" | "wye" | "plus" | "times" | "ring";

/** How a line is dashed. */
export type LineDash = "solid" | "dashed" | "dotted" | "dashDot";

/** The D3 curve for a line shape. */
export function curveOf(shape: LineShape): CurveFactory {
  switch (shape) {
    case "smooth":
      return curveMonotoneX;
    case "step":
      return curveStep;
    case "stepAfter":
      return curveStepAfter;
    case "stepBefore":
      return curveStepBefore;
    case "spline":
      throw new Error("A spline is not drawn on this page.");
    default:
      return curveLinear;
  }
}

/** The dash pattern for a dash style at a line width. */
export function dashOf(dash: LineDash, width: number): number[] | null {
  switch (dash) {
    case "dashed":
      return [width * 3 + 2, width * 2 + 2];
    case "dotted":
      return [0.01, width * 2 + 1];
    case "dashDot":
      return [width * 3 + 2, width + 2, 0.01, width + 2];
    default:
      return null;
  }
}

/** The commands of a path through pixel points, broken at every point that is not a number. */
export function polylineCommands(points: readonly Vec2[], shape: LineShape): PathRecorder {
  const context = new PathRecorder();
  linePath(
    points,
    (p) => p.x,
    (p) => p.y,
    (p) => Number.isFinite(p.x) && Number.isFinite(p.y),
    curveOf(shape),
    context,
  );
  return context;
}

/** A path through pixel points, broken at every point that is not a number. */
export function polyline(points: readonly Vec2[], shape: LineShape): VectorPath {
  return polylineCommands(points, shape).toPath();
}

/**
 * The points of a long series thinned to what a plotting area this wide can show: per column of pixels, the first, lowest, highest
 * and last point. Only for x increasing left to right, which is what a signal is; the shape a reader sees is unchanged, because every
 * extreme in every pixel column is kept. A series no denser than four points a pixel is returned whole.
 */
export function decimate(points: readonly Vec2[], plotWidth: number): readonly Vec2[] {
  if (points.length <= Math.max(2000, plotWidth * 4)) return points;
  for (let i = 1; i < points.length; i++) if (points[i].x < points[i - 1].x) return points;

  const kept: Vec2[] = [];
  let start = 0;
  while (start < points.length) {
    const first = points[start];
    if (!Number.isFinite(first.x) || !Number.isFinite(first.y)) {
      kept.push(first);
      start++;
      continue;
    }
    const column = Math.floor(first.x);
    let end = start;
    let low = first;
    let high = first;
    let last = first;
    while (end < points.length && Number.isFinite(points[end].x) && Number.isFinite(points[end].y) && Math.floor(points[end].x) === column) {
      const p = points[end];
      if (p.y < low.y) low = p;
      if (p.y > high.y) high = p;
      last = p;
      end++;
    }
    kept.push(first);
    if (low.x <= high.x) kept.push(low, high);
    else kept.push(high, low);
    kept.push(last);
    start = end;
  }
  return kept;
}

/** Draws a point symbol of the given diameter, with a ring of the surface colour round a filled one. */
export function drawPoint(sink: Sink, x: number, y: number, shape: PointShape, diameter: number, colour: Colour, surface: Colour, ring: number): void {
  if (!Number.isFinite(x) || !Number.isFinite(y) || colour.a === 0) return;
  const r = diameter / 2;
  if (shape === "circle" || shape === "ring") {
    if (shape === "circle" && ring > 0) sink.drawPath(new VectorPath().addCircle(x, y, r + ring), ChartPaints.fill(surface));
    if (shape === "circle") sink.drawPath(new VectorPath().addCircle(x, y, r), ChartPaints.fill(colour));
    else sink.drawPath(new VectorPath().addCircle(x, y, r - 0.75), ChartPaints.stroke(colour, 1.5));
    return;
  }
  throw new Error(`A ${shape} point is not drawn on this page.`);
}

/** A rounded corner from the current point - which lies on the line towards `corner` - turning towards `next`, as Skia's arcTo(x1, y1, x2, y2, radius) draws one: a line to where the arc starts, and the arc. */
function cornerTo(path: VectorPath, from: Vec2, corner: Vec2, next: Vec2, radius: number): void {
  const ax = from.x - corner.x;
  const ay = from.y - corner.y;
  const bx = next.x - corner.x;
  const by = next.y - corner.y;
  const la = Math.hypot(ax, ay);
  const lb = Math.hypot(bx, by);
  const ux = ax / la;
  const uy = ay / la;
  const vx = bx / lb;
  const vy = by / lb;
  const theta = Math.acos(Math.min(1, Math.max(-1, ux * vx + uy * vy)));
  const along = radius / Math.tan(theta / 2);
  const t1 = { x: corner.x + ux * along, y: corner.y + uy * along };
  const t2 = { x: corner.x + vx * along, y: corner.y + vy * along };
  const bisector = Math.hypot(ux + vx, uy + vy);
  const reach = radius / Math.sin(theta / 2);
  const center = { x: corner.x + ((ux + vx) / bisector) * reach, y: corner.y + ((uy + vy) / bisector) * reach };
  const start = (Math.atan2(t1.y - center.y, t1.x - center.x) * 180) / Math.PI;
  const end = (Math.atan2(t2.y - center.y, t2.x - center.x) * 180) / Math.PI;
  let sweep = end - start;
  while (sweep > 180) sweep -= 360;
  while (sweep < -180) sweep += 360;
  path.lineTo(t1.x, t1.y);
  path.arcTo(new RectF(center.x - radius, center.y - radius, center.x + radius, center.y + radius), start, sweep, false);
}

/**
 * A bar from a baseline to a value end, the value end rounded and the baseline end square. `valueEnd` says which side of the
 * rectangle is the value end: 0 top, 1 right, 2 bottom, 3 left; `radius` is the rounding, reduced to fit a short or narrow bar.
 */
export function bar(rect: RectF, valueEnd: number, radius: number): VectorPath {
  const path = new VectorPath();
  const r = Math.min(radius, Math.min(rect.width, rect.height) / 2);
  if (r <= 0.25) return path.addRect(rect);
  const l = rect.left;
  const t = rect.top;
  const rr = rect.right;
  const b = rect.bottom;
  // Corners clockwise from top left; a corner is round when it lies on the value end.
  const tl = valueEnd === 0 || valueEnd === 3;
  const tr = valueEnd === 0 || valueEnd === 1;
  const br = valueEnd === 1 || valueEnd === 2;
  const bl = valueEnd === 2 || valueEnd === 3;
  let at = { x: l + (tl ? r : 0), y: t };
  path.moveTo(at.x, at.y);
  at = { x: rr - (tr ? r : 0), y: t };
  path.lineTo(at.x, at.y);
  if (tr) {
    cornerTo(path, at, { x: rr, y: t }, { x: rr, y: t + r }, r);
    at = { x: rr, y: t + r };
  }
  at = { x: rr, y: b - (br ? r : 0) };
  path.lineTo(at.x, at.y);
  if (br) {
    cornerTo(path, at, { x: rr, y: b }, { x: rr - r, y: b }, r);
    at = { x: rr - r, y: b };
  }
  at = { x: l + (bl ? r : 0), y: b };
  path.lineTo(at.x, at.y);
  if (bl) {
    cornerTo(path, at, { x: l, y: b }, { x: l, y: b - r }, r);
    at = { x: l, y: b - r };
  }
  at = { x: l, y: t + (tl ? r : 0) };
  path.lineTo(at.x, at.y);
  if (tl) cornerTo(path, at, { x: l, y: t }, { x: l + r, y: t }, r);
  path.close();
  return path;
}

/** A rectangle from two corners in any order - in single precision, as Divooka's float rectangle holds it, so a bar thinner than a float can tell apart has no height and is not drawn, nor labelled. */
export function rectBetween(x0: number, y0: number, x1: number, y1: number): RectF {
  const f = Math.fround;
  return new RectF(f(Math.min(x0, x1)), f(Math.min(y0, y1)), f(Math.max(x0, x1)), f(Math.max(y0, y1)));
}
