// The parts of D3 a chart's axes are made with: d3-array's ticks, d3-scale's nice and tickFormat for a linear scale, and d3-format's
// number formats. Ported from Parcel NExT's Divooka.Graphics.Canvas.D3 (Arrays/Sequence.Ticks.cs, Scales/ContinuousScale.cs,
// Format/*.cs), which is itself a port of D3's JavaScript - so here the JavaScript's own number primitives (toFixed, toExponential,
// toPrecision) do what the C# reproduces of them.

// ---------------------------------------------------------------- d3-array: ticks

const e10 = Math.sqrt(50);
const e5 = Math.sqrt(10);
const e2 = Math.sqrt(2);

function tickSpec(start: number, stop: number, count: number): [number, number, number] {
  const step = (stop - start) / Math.max(0, count);
  const power = Math.floor(Math.log10(step));
  const error = step / Math.pow(10, power);
  const factor = error >= e10 ? 10 : error >= e5 ? 5 : error >= e2 ? 2 : 1;
  let i1: number;
  let i2: number;
  let inc: number;
  if (power < 0) {
    inc = Math.pow(10, -power) / factor;
    i1 = Math.round(start * inc);
    i2 = Math.round(stop * inc);
    if (i1 / inc < start) ++i1;
    if (i2 / inc > stop) --i2;
    inc = -inc;
  } else {
    inc = Math.pow(10, power) * factor;
    i1 = Math.round(start / inc);
    i2 = Math.round(stop / inc);
    if (i1 * inc < start) ++i1;
    if (i2 * inc > stop) --i2;
  }
  if (i2 < i1 && 0.5 <= count && count < 2) return tickSpec(start, stop, count * 2);
  return [i1, i2, inc];
}

/** Approximately count nicely rounded values between start and stop (inclusive where the rounding lands inside). Each tick is a power of ten times 1, 2, or 5 — d3.ticks. */
export function ticks(start: number, stop: number, count: number): number[] {
  if (!(count > 0)) return [];
  if (start === stop) return [start];
  const reverse = stop < start;
  const [i1, i2, inc] = reverse ? tickSpec(stop, start, count) : tickSpec(start, stop, count);
  if (!(i2 >= i1)) return [];
  const n = i2 - i1 + 1;
  const out = new Array<number>(n);
  if (reverse) {
    if (inc < 0) for (let i = 0; i < n; ++i) out[i] = (i2 - i) / -inc;
    else for (let i = 0; i < n; ++i) out[i] = (i2 - i) * inc;
  } else {
    if (inc < 0) for (let i = 0; i < n; ++i) out[i] = (i1 + i) / -inc;
    else for (let i = 0; i < n; ++i) out[i] = (i1 + i) * inc;
  }
  return out;
}

/** The tick increment `ticks` would use. Negative means an inverse increment: -100 stands for a step of 1/100 — d3.tickIncrement. */
export function tickIncrement(start: number, stop: number, count: number): number {
  return tickSpec(start, stop, count)[2];
}

/** The positive step between adjacent tick values (sign follows direction) — d3.tickStep. */
export function tickStep(start: number, stop: number, count: number): number {
  const reverse = stop < start;
  const inc = reverse ? tickIncrement(stop, start, count) : tickIncrement(start, stop, count);
  return (reverse ? -1 : 1) * (inc < 0 ? 1 / -inc : inc);
}

// ---------------------------------------------------------------- d3-scale: a linear scale's nice and tickFormat

/** A linear scale's domain extended to nice round values — scale.nice: at most ten passes, and the domain left as it was when they do not settle. */
export function linearNice(domain: readonly number[], count = 10): number[] {
  const d = [...domain];
  let i0 = 0;
  let i1 = d.length - 1;
  let start = d[i0];
  let stop = d[i1];
  let prestep: number | undefined;
  let maxIter = 10;
  if (stop < start) {
    [start, stop] = [stop, start];
    [i0, i1] = [i1, i0];
  }
  while (maxIter-- > 0) {
    const step = tickIncrement(start, stop, count);
    if (step === prestep) {
      d[i0] = start;
      d[i1] = stop;
      return d;
    } else if (step > 0) {
      start = Math.floor(start / step) * step;
      stop = Math.ceil(stop / step) * step;
    } else if (step < 0) {
      start = Math.ceil(start * step) / step;
      stop = Math.floor(stop * step) / step;
    } else break;
    prestep = step;
  }
  return [...domain];
}

/** d3-scale's tickFormat: a format whose precision suits the tick step. */
export function scaleTickFormat(start: number, stop: number, count: number, specifier: string | null | undefined): (value: number) => string {
  const step = tickStep(start, stop, count);
  const spec = new FormatSpecifier(specifier ?? ",f");
  let precision: number;
  switch (spec.type) {
    case "s": {
      const value = Math.max(Math.abs(start), Math.abs(stop));
      if (spec.precision === null && !Number.isNaN((precision = precisionPrefix(step, value)))) spec.precision = precision;
      return formatPrefix(spec, value);
    }
    case "":
    case "e":
    case "g":
    case "p":
    case "r": {
      if (spec.precision === null && !Number.isNaN((precision = precisionRound(step, Math.max(Math.abs(start), Math.abs(stop))))))
        spec.precision = precision - (spec.type === "e" ? 1 : 0);
      break;
    }
    case "f":
    case "%": {
      if (spec.precision === null && !Number.isNaN((precision = precisionFixed(step)))) spec.precision = precision - (spec.type === "%" ? 2 : 0);
      break;
    }
  }
  return format(spec);
}

// ---------------------------------------------------------------- d3-format

const specifierPattern = /^(?:(.)?([<>=^]))?([+\-( ])?([$#])?(0)?(\d+)?(,)?(\.\d+)?(~)?([a-z%])?$/i;

/** A parsed d3-format specifier. */
export class FormatSpecifier {
  fill = " ";
  align = ">";
  sign = "-";
  symbol = "";
  zero = false;
  width: number | null = null;
  comma = false;
  precision: number | null = null;
  trim = false;
  type = "";

  constructor(specifier = "") {
    const match = specifierPattern.exec(specifier);
    if (!match) throw new Error(`invalid format: ${specifier}`);
    if (match[1] !== undefined) this.fill = match[1];
    if (match[2] !== undefined) this.align = match[2];
    if (match[3] !== undefined) this.sign = match[3];
    if (match[4] !== undefined) this.symbol = match[4];
    this.zero = match[5] !== undefined;
    if (match[6] !== undefined) this.width = parseInt(match[6], 10);
    this.comma = match[7] !== undefined;
    if (match[8] !== undefined) this.precision = parseInt(match[8].slice(1), 10);
    this.trim = match[9] !== undefined;
    if (match[10] !== undefined) this.type = match[10];
  }

  copy(): FormatSpecifier {
    const c = new FormatSpecifier();
    Object.assign(c, this);
    return c;
  }

  toString(): string {
    return (
      this.fill +
      this.align +
      this.sign +
      this.symbol +
      (this.zero ? "0" : "") +
      (this.width === null ? "" : Math.max(1, this.width | 0)) +
      (this.comma ? "," : "") +
      (this.precision === null ? "" : "." + Math.max(0, this.precision | 0)) +
      (this.trim ? "~" : "") +
      this.type
    );
  }
}

/** The decimal coefficient digits and exponent of x with p significant digits (d3's formatDecimalParts); null for NaN, infinity and zero. */
function decimalParts(x: number, p?: number): [string, number] | null {
  if (!Number.isFinite(x) || x === 0) return null;
  const s = p ? x.toExponential(p - 1) : x.toExponential();
  const i = s.indexOf("e");
  let coefficient = s.slice(0, i);
  if (coefficient.startsWith("-")) coefficient = coefficient.slice(1);
  return [coefficient.length > 1 ? coefficient[0] + coefficient.slice(2) : coefficient, +s.slice(i + 1)];
}

/** The base-10 exponent of x (d3's exponent); NaN for zero and non-finite values. */
function exponent(x: number): number {
  const d = decimalParts(Math.abs(x));
  return d ? d[1] : NaN;
}

function formatGroup(value: string, width: number): string {
  const grouping = [3];
  const thousands = ",";
  let i = value.length;
  const t: string[] = [];
  let j = 0;
  let g = grouping[0];
  let length = 0;
  while (i > 0 && g > 0) {
    if (length + g + 1 > width) g = Math.max(1, width - length);
    t.push(value.substring((i -= g), i + g));
    if ((length += g + 1) > width) break;
    g = grouping[(j = (j + 1) % grouping.length)];
  }
  return t.reverse().join(thousands);
}

function formatTrim(s: string): string {
  const n = s.length;
  let i0 = -1;
  let i1 = -1;
  out: for (let i = 1; i < n; ++i) {
    switch (s[i]) {
      case ".":
        i0 = i1 = i;
        break;
      case "0":
        if (i0 === 0) i0 = i;
        i1 = i;
        break;
      default:
        if (!(+s[i] >= 0 && +s[i] <= 9) || s[i] === " ") break out;
        if (i0 > 0) i0 = 0;
        break;
    }
  }
  return i0 > 0 ? s.slice(0, i0) + s.slice(i1 + 1) : s;
}

let prefixExponent: number | undefined;

function formatPrefixAuto(x: number, p: number): string {
  const d = decimalParts(x, p);
  if (!d) return x + "";
  const [coefficient, exp] = d;
  const i = exp - (prefixExponent = Math.max(-8, Math.min(8, Math.floor(exp / 3))) * 3) + 1;
  const n = coefficient.length;
  return i === n ? coefficient : i > n ? coefficient + new Array(i - n + 1).join("0") : i > 0 ? coefficient.slice(0, i) + "." + coefficient.slice(i) : "0." + new Array(1 - i).join("0") + decimalParts(x, Math.max(0, p + i - 1))![0];
}

function formatRounded(x: number, p: number): string {
  const d = decimalParts(x, p);
  if (!d) return x + "";
  const [coefficient, exp] = d;
  return exp < 0 ? "0." + new Array(-exp).join("0") + coefficient : coefficient.length > exp + 1 ? coefficient.slice(0, exp + 1) + "." + coefficient.slice(exp + 1) : coefficient + new Array(exp - coefficient.length + 2).join("0");
}

function formatDecimal(x: number): string {
  return Math.abs((x = Math.round(x))) >= 1e21 ? x.toLocaleString("en").replace(/,/g, "") : x.toString(10);
}

/**
 * JavaScript's toFixed as Divooka's port computes it, with .NET's fixed-point formatting: correctly rounded like JavaScript's, except
 * at an exact decimal tie (…5 exactly at the cutoff), which JavaScript rounds up and .NET rounds to the even neighbour - so a slice of
 * 12.5% reads 12% in Divooka, and here.
 */
export function toFixed(x: number, p: number): string {
  const fixed = x.toFixed(p);
  if (!Number.isFinite(x) || Math.abs(x) >= 1e21) return fixed;
  // x is m * 2^e exactly; x * 10^p is a tie when twice it is an odd integer.
  const [m, e] = binary(Math.abs(x));
  if (e >= 0) return fixed;
  const scaled = m * 10n ** BigInt(p);
  const shift = BigInt(-e);
  const twice = scaled * 2n;
  if (twice % (1n << shift) !== 0n || (twice >> shift) % 2n === 0n) return fixed;
  // A tie: the floor of x * 10^p, and up one only when that leaves it odd.
  let n = scaled >> shift;
  if (n % 2n === 1n) n += 1n;
  const digits = n.toString().padStart(p + 1, "0");
  const text = p === 0 ? digits : `${digits.slice(0, digits.length - p)}.${digits.slice(digits.length - p)}`;
  return x < 0 ? "-" + text : text;
}

/** A positive finite double as an integer mantissa and a power of two. */
function binary(x: number): [bigint, number] {
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, x);
  const bits = view.getBigUint64(0);
  const exponent = Number((bits >> 52n) & 0x7ffn);
  const fraction = bits & ((1n << 52n) - 1n);
  return exponent === 0 ? [fraction, -1074] : [fraction | (1n << 52n), exponent - 1075];
}

const formatTypes: Record<string, (x: number, p: number) => string> = {
  "%": (x, p) => toFixed(x * 100, p),
  b: (x) => Math.round(x).toString(2),
  c: (x) => x + "",
  d: formatDecimal,
  e: (x, p) => x.toExponential(p),
  f: (x, p) => toFixed(x, p),
  g: (x, p) => x.toPrecision(p),
  o: (x) => Math.round(x).toString(8),
  p: (x, p) => formatRounded(x * 100, p),
  r: formatRounded,
  s: formatPrefixAuto,
  X: (x) => Math.round(x).toString(16).toUpperCase(),
  x: (x) => Math.round(x).toString(16),
};

const prefixes = ["y", "z", "a", "f", "p", "n", "µ", "m", "", "k", "M", "G", "T", "P", "E", "Z", "Y"];
const minus = "\u2212";

function compile(specifier: FormatSpecifier, suffixOption?: string): (value: number) => string {
  let { fill, align, sign, symbol, zero, width, comma, precision, trim, type } = specifier;

  // The "n" type is an alias for ",g".
  if (type === "n") {
    comma = true;
    type = "g";
  }
  // The "" type, and any invalid type, is an alias for ".12~g".
  else if (!formatTypes[type]) {
    if (precision === null) precision = 12;
    trim = true;
    type = "g";
  }

  // If zero fill is specified, padding goes after sign and before digits.
  if (zero || (fill === "0" && align === "=")) {
    zero = true;
    fill = "0";
    align = "=";
  }

  // Compute the prefix and suffix. For SI-prefix, the suffix is computed per value.
  const prefix = symbol === "$" ? "$" : symbol === "#" && /[boxX]/.test(type) ? "0" + type.toLowerCase() : "";
  const suffix = (symbol === "$" ? "" : /[%p]/.test(type) ? "%" : "") + (suffixOption ?? "");

  const formatType = formatTypes[type];
  const maybeSuffix = /[defgprs%]/.test(type);

  // Set the default precision, or clamp the specified precision to the supported range.
  const p = precision === null ? 6 : /[gprs]/.test(type) ? Math.max(1, Math.min(21, precision)) : Math.max(0, Math.min(20, precision));

  return (input: number): string => {
    let valuePrefix = prefix;
    let valueSuffix = suffix;
    let value: string;

    if (type === "c") {
      valueSuffix = formatType(input, p) + valueSuffix;
      value = "";
    } else {
      let v = +input;
      // Determine the sign: -0 is not less than 0, but its reciprocal is.
      let valueNegative = v < 0 || 1 / v < 0;

      // Perform the initial formatting.
      value = Number.isNaN(v) ? "NaN" : formatType(Math.abs(v), p);

      // Trim insignificant zeros.
      if (trim) value = formatTrim(value);

      // A negative value that rounds to zero hides its sign unless "+" was asked for.
      if (valueNegative && +value === 0 && sign !== "+") valueNegative = false;

      // Compute the prefix and suffix.
      valuePrefix = (valueNegative ? (sign === "(" ? sign : minus) : sign === "-" || sign === "(" ? "" : sign) + valuePrefix;
      valueSuffix = (type === "s" && !Number.isNaN(v) && prefixExponent !== undefined ? prefixes[8 + prefixExponent / 3] : "") + valueSuffix + (valueNegative && sign === "(" ? ")" : "");

      // Split the digits that can be grouped from the fractional/exponential tail.
      if (maybeSuffix) {
        for (let i = -1, n = value.length; ++i < n; ) {
          const c = value.charCodeAt(i);
          if (48 > c || c > 57) {
            valueSuffix = (c === 46 ? "." + value.slice(i + 1) : value.slice(i)) + valueSuffix;
            value = value.slice(0, i);
            break;
          }
        }
      }
      v = 0;
    }

    // If the fill character is not "0", grouping is applied before padding.
    if (comma && !zero) value = formatGroup(value, Infinity);

    // Compute the padding.
    let length = valuePrefix.length + value.length + valueSuffix.length;
    let padding = width !== null && length < width ? new Array(width - length + 1).join(fill) : "";

    // If the fill character is "0", grouping is applied after padding.
    if (comma && zero) {
      value = formatGroup(padding + value, padding.length ? width! - valueSuffix.length : Infinity);
      padding = "";
    }

    // Reconstruct the final output based on the desired alignment.
    switch (align) {
      case "<":
        return valuePrefix + value + valueSuffix + padding;
      case "=":
        return valuePrefix + padding + value + valueSuffix;
      case "^":
        length = padding.length >> 1;
        return padding.slice(0, length) + valuePrefix + value + valueSuffix + padding.slice(length);
      default:
        return padding + valuePrefix + value + valueSuffix;
    }
  };
}

/** The en-US number formatter for a d3-format specifier - d3.format. */
export function format(specifier: string | FormatSpecifier): (value: number) => string {
  return compile(typeof specifier === "string" ? new FormatSpecifier(specifier) : specifier);
}

/** A formatter for values near `value` with a fixed SI prefix - d3.formatPrefix. */
export function formatPrefix(specifier: string | FormatSpecifier, value: number): (value: number) => string {
  const spec = (typeof specifier === "string" ? new FormatSpecifier(specifier) : specifier).copy();
  spec.type = "f";
  const e = Math.max(-8, Math.min(8, Math.floor(exponent(value) / 3))) * 3;
  const k = Math.pow(10, -e);
  const f = compile(spec, prefixes[8 + e / 3]);
  return (v: number) => f(k * v);
}

export function precisionFixed(step: number): number {
  return Math.max(0, -exponent(Math.abs(step)));
}

export function precisionPrefix(step: number, value: number): number {
  return Math.max(0, Math.max(-8, Math.min(8, Math.floor(exponent(value) / 3))) * 3 - exponent(Math.abs(step)));
}

export function precisionRound(step: number, max: number): number {
  step = Math.abs(step);
  max = Math.abs(max) - step;
  return Math.max(0, exponent(max) - exponent(step)) + 1;
}
