// A trend fitted to points: a straight line, a polynomial or a smooth local fit, with its 95% confidence band and, if asked, its
// equation. Ported from Parcel NExT's Divooka.Graphics.Plotting/Layers/StatisticalLayers.cs (TrendLine; the histograms, box plots and
// densities of that file are not drawn by Dhole).

import { withOpacity } from "../color-math";
import { ChartLayerPlan, ChartPaints, xScale, yOf, type ChartTraining, type LegendCollector } from "../contracts";
import { Layer, type DrawContext, type PlanContext } from "../figure";
import { formatWith } from "../formatting";
import { Series } from "../series";
import { trend, type TrendFit, type TrendKind } from "../statistics";
import type { Colour } from "../theme";
import { Check } from "./lines";
import { polyline } from "./marks";
import { VectorPath, type Vec2 } from "../../rendering/geometry";

export class TrendLine extends Layer {
  readonly x: Series;
  readonly y: Series;
  /** What kind of curve is fitted. */
  kind: TrendKind = "linear";
  /** A polynomial's degree. */
  degree = 2;
  /** A smooth fit's span: the share of the points each local fit uses. */
  span = 0.75;
  /** Whether the 95% confidence band of a formula fit is shaded. */
  confidenceBand = true;
  /** Whether the fitted equation and R² are written at the line's end. */
  showEquation = false;

  constructor(x: readonly number[], y: readonly number[]) {
    super();
    this.x = Series.ofNumbers(x);
    this.y = Series.ofNumbers(y);
  }

  /** The fit itself, for a caller that wants the numbers rather than the line. */
  fit(): TrendFit {
    return trend(this.x.numbersOf, this.y.numbersOf, this.kind, this.degree, this.span);
  }

  plan(context: PlanContext): TrendPlan {
    Check.sameLength(this.x, this.y, "x", "y");
    Check.numbers(this.x, "trend's x values");
    Check.numbers(this.y, "trend's y values");
    return new TrendPlan(this, context.seriesColor(this), this.fit());
  }
}

class TrendPlan extends ChartLayerPlan {
  constructor(
    private readonly trendLine: TrendLine,
    private readonly color: Colour,
    private readonly fit: TrendFit,
  ) {
    super(trendLine);
  }

  override train(training: ChartTraining): void {
    const t = this.trendLine;
    const fit = this.fit;
    training.x.claim("number", t.x.name);
    const y = training.yOf(t);
    y.claim("number", t.y.name);
    for (const v of fit.x) training.x.addValue(v);
    for (const v of fit.y) y.addValue(v);
    if (t.confidenceBand && fit.lower !== null && fit.upper !== null) {
      for (const v of fit.lower) y.addValue(v);
      for (const v of fit.upper) y.addValue(v);
    }
  }

  draw(context: DrawContext): void {
    const t = this.trendLine;
    const fit = this.fit;
    const x = xScale(context);
    const y = yOf(context, t);
    const line: Vec2[] = fit.x.map((v, i) => ({ x: x.map(v), y: y.map(fit.y[i]) }));
    if (t.confidenceBand && fit.lower !== null && fit.upper !== null) {
      const band = new VectorPath();
      for (let i = 0; i < fit.x.length; i++) {
        const px = x.map(fit.x[i]);
        const py = y.map(fit.upper[i]);
        if (i === 0) band.moveTo(px, py);
        else band.lineTo(px, py);
      }
      for (let i = fit.x.length - 1; i >= 0; i--) band.lineTo(x.map(fit.x[i]), y.map(fit.lower[i]));
      band.close();
      context.sink.drawPath(band, ChartPaints.fill(withOpacity(this.color, 0.15 * t.opacity)));
    }
    context.sink.drawPath(polyline(line, "straight"), ChartPaints.stroke(withOpacity(this.color, t.opacity), context.theme.lineWidth));
    if (t.showEquation && fit.kind !== "smooth" && line.length > 0) {
      const text = `${fit.equation}   R² = ${formatWith(fit.rSquared, ".3f")}`;
      const box = context.text.bounds(text, context.plot.right - 6, context.plot.top + 6, "dataLabel", "topRight");
      context.sink.drawRect(box.inflate(4, 2), ChartPaints.fill(withOpacity(context.surface, 0.85)));
      context.text.draw(context.sink, text, context.plot.right - 6, context.plot.top + 6, "dataLabel", context.theme.secondaryInk, "topRight");
    }
  }

  override addLegend(legend: LegendCollector): void {
    legend.add(this.trendLine.label, this.color, "line");
  }
}
