// How numbers become text on a chart, culture-invariantly so a figure reads the same on every machine.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Scales/Formatting.cs.
//
// Format strings are D3's: ",.2f", ".0%", "$,.0f", "~s" - the same grammar the D3 port compiles, so one reference covers both. A
// negative number is written with a true minus sign, as D3 writes it. Times are not ported: no Dhole chart puts dates on an axis.

import { format } from "./d3";

const numberFormats = new Map<string, (value: number) => string>();

/** Rounds a decimal numeral (digits and a point, no sign) half away from zero to `decimals` places, as .NET's custom formats round the shortest digits of a double. */
function roundDecimal(text: string, decimals: number): string {
  const point = text.indexOf(".");
  if (point < 0 || text.length - point - 1 <= decimals) return text;
  const digits = (text.slice(0, point) + text.slice(point + 1, point + 1 + decimals)).split("").map(Number);
  if (+text[point + 1 + decimals] >= 5) {
    let i = digits.length - 1;
    while (i >= 0 && digits[i] === 9) digits[i--] = 0;
    if (i < 0) digits.unshift(1);
    else digits[i]++;
  }
  const whole = digits.length - decimals;
  return digits.slice(0, whole).join("") + (decimals > 0 ? "." + digits.slice(whole).join("") : "");
}

/** The shortest round-trip digits of a positive double in plain decimal notation. */
function plain(magnitude: number): string {
  const s = magnitude.toString();
  const e = s.indexOf("e");
  if (e < 0) return s;
  const exp = +s.slice(e + 1);
  const mantissa = s.slice(0, e).replace(".", "");
  const pointAt = (s.indexOf(".") < 0 ? e : s.indexOf(".")) + exp;
  if (pointAt <= 0) return "0." + "0".repeat(-pointAt) + mantissa;
  if (pointAt >= mantissa.length) return mantissa + "0".repeat(pointAt - mantissa.length);
  return mantissa.slice(0, pointAt) + "." + mantissa.slice(pointAt);
}

/** A number as .NET's custom formats "0.###" (no grouping) or "#,##0.###" (grouped thousands) write it: up to `decimals` decimals, trailing zeros dropped, rounded half away from zero on the number's shortest digits. */
export function customDecimal(value: number, decimals: number, grouping: boolean): string {
  const magnitude = Math.abs(value);
  let [whole, fraction = ""] = roundDecimal(plain(magnitude), decimals).split(".");
  fraction = fraction.replace(/0+$/, "");
  whole = whole.replace(/^0+(?=\d)/, "");
  if (grouping) whole = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  const text = fraction.length > 0 ? `${whole}.${fraction}` : whole;
  return value < 0 && text !== "0" ? "-" + text : text;
}

function grouped(magnitude: number): string {
  return customDecimal(magnitude, 3, true);
}

/** .NET's "0.###e+0": one digit, up to three decimals, and the exponent with its sign. */
function scientific(magnitude: number): string {
  let exp = Math.floor(Math.log10(magnitude));
  let mantissa = roundDecimal(plain(magnitude / Math.pow(10, exp)), 3);
  if (+mantissa >= 10) {
    exp++;
    mantissa = roundDecimal(plain(magnitude / Math.pow(10, exp)), 3);
  }
  if (mantissa.includes(".")) mantissa = mantissa.replace(/0+$/, "").replace(/\.$/, "");
  return `${mantissa}e${exp < 0 ? "-" : "+"}${Math.abs(exp)}`;
}

/** A number as a label: grouped thousands and up to three decimals, or scientific notation when that is shorter. */
export function formatNumber(value: number): string {
  if (Number.isNaN(value)) return "";
  if (!Number.isFinite(value)) return value > 0 ? "∞" : "−∞";
  const magnitude = Math.abs(value);
  const text = magnitude !== 0 && (magnitude >= 1e12 || magnitude < 1e-3) ? scientific(magnitude) : grouped(magnitude);
  return value < 0 && text !== "0" ? "−" + text : text;
}

/** A number through a D3 format specifier such as ",.2f" or ".0%". */
export function formatWith(value: number, specifier: string): string {
  return numberFormatter(specifier)(value);
}

/** The compiled formatter for a D3 number specifier, cached. */
export function numberFormatter(specifier: string | null | undefined): (value: number) => string {
  if (!specifier || !specifier.trim()) return formatNumber;
  let compiled = numberFormats.get(specifier);
  if (!compiled) {
    compiled = format(specifier);
    numberFormats.set(specifier, compiled);
  }
  return compiled;
}

/** Whether a specifier is a time format (it has a % directive) rather than a number format: a time directive is a % followed by a letter (%Y, %b); in a number format a % is the percentage type and ends the specifier. */
export function isTimeSpecifier(specifier: string | null | undefined): boolean {
  if (!specifier) return false;
  for (let i = 0; i + 1 < specifier.length; i++) if (specifier[i] === "%" && /\p{L}/u.test(specifier[i + 1])) return true;
  return false;
}
