// Dhole: charts and diagrams written as text, drawn as a figure - in Divooka through its plotting framework, here as SVG.
// Ported from Parcel NExT's Divooka.Visualization.Dhole/Dhole.cs.
//
// The language is specified in "Dhole Language.md" beside the C# package (and in the MethodoxDhole repository). A text names what to
// draw on its first line and says what it shows on the lines after; several diagrams are separated by lines of three dashes and
// drawn side by side. Reading never stops at a problem: a line that cannot be read is reported with its line, its column and a
// hint, and every other line is drawn. The same text always gives the same picture: nothing reads the clock, the culture or a
// random number.

import { readDhole, Kinds, type Built, type DiagramSpec } from "./syntax/reader";
import type { DholeProblem } from "./syntax/problems";
import { figureOf, renderFigure, sizedFor, withSize, type Chart, type Figure } from "./plot/figure";
import { getDefaultMeasurer, type TextMeasurer } from "./plot/text";
import { SvgSink } from "./plot/sink";
import type { Theme } from "./plot/theme";

/** How a text is read and drawn. */
export interface DholeOptions {
  /** What text is measured with; a canvas on a page, Open Sans's metrics elsewhere. */
  readonly measurer?: TextMeasurer;
  /** The theme a diagram has when its text names none; Light, as in Divooka, when not given. */
  readonly defaultTheme?: Theme;
  /** Every diagram's theme changed before it is laid out - how a page sets every word in its own font, or a test in one face. */
  readonly adjustTheme?: (theme: Theme) => Theme;
}

/** What reading Dhole text gave: the figure, what is wrong with the text, and what was drawn, in a sentence. */
export interface DholeResult {
  /** The figure, or null when nothing in the text could be drawn. */
  readonly figure: Figure | null;
  /** Every problem in the text, in the order of its lines. */
  readonly problems: readonly DholeProblem[];
  /** The kind of each diagram drawn - flowchart, pie - in order. */
  readonly kinds: readonly string[];
  /** What was drawn, in a sentence for each diagram: a picture's words for someone who cannot see it. */
  readonly summary: string;
  /** Whether any problem is an error rather than a warning. */
  readonly hasErrors: boolean;
  /** What the text was measured with, which drawing it must use too. */
  readonly measurer: TextMeasurer;
}

/** Thrown when Dhole text holds nothing that can be drawn; its message is the first problem, where it is and what to write instead. */
export class DholeError extends Error {
  readonly problems: readonly DholeProblem[];
  constructor(problems: readonly DholeProblem[]) {
    super(problems.length === 0 ? "There is nothing to draw." : problems[0].toString());
    this.name = "DholeError";
    this.problems = problems;
  }
}

/** Reads Dhole text: the figure it describes, its problems, and what was drawn. */
export function read(text: string | null | undefined, options: DholeOptions = {}): DholeResult {
  const measurer = options.measurer ?? getDefaultMeasurer();
  const { specs, problems } = readDhole(text, { defaultTheme: options.defaultTheme });
  if (options.adjustTheme) for (const spec of specs) spec.theme = options.adjustTheme(spec.theme);
  const built: { spec: DiagramSpec; built: Built }[] = [];
  for (const spec of specs.filter((s) => !s.isEmpty)) {
    try {
      built.push({ spec, built: spec.build(problems, { measurer }) });
    } catch (failure) {
      problems.error(spec.kindLine.content, "CouldNotDraw", spec.kind.name, failure instanceof Error ? failure.message : String(failure));
    }
  }
  const figure = built.length === 0 ? null : assemble(built, measurer);
  const all = problems.all;
  return {
    figure,
    problems: all,
    kinds: built.map((b) => b.spec.kind.word),
    summary: built.map((b) => b.built.summary).join(" "),
    hasErrors: all.some((p) => p.severity === "error"),
    measurer,
  };
}

/** The figure Dhole text describes, drawn as far as the text can be read; throws a DholeError when nothing in it can be drawn. */
export function draw(text: string | null | undefined, options: DholeOptions = {}): Figure {
  const result = read(text, options);
  if (!result.figure) throw new DholeError(result.problems);
  return result.figure;
}

/** The problems in Dhole text, without drawing it. */
export function check(text: string | null | undefined): readonly DholeProblem[] {
  return readDhole(text).problems.all;
}

/** The words that start each kind of diagram, in the order the documentation lists them. */
export const kindWords: readonly string[] = Kinds.map((k) => k.word);

/** A figure as an SVG document, its words kept as text in the faces they were measured in. */
export function toSvg(figure: Figure, options: { measurer?: TextMeasurer; title?: string | null; description?: string | null; idPrefix?: string } = {}): string {
  const sink = new SvgSink(options.idPrefix ?? `dh${nextId++}`);
  renderFigure(figure, sink, options.measurer ?? getDefaultMeasurer());
  return sink.toSvg(figure.width, figure.height, options.title ?? figure.title, options.description);
}

let nextId = 1;

/** Dhole text as an SVG document, with what was drawn as its description; null when nothing in it can be drawn. */
export function renderSvg(text: string | null | undefined, options: DholeOptions = {}): { svg: string | null; result: DholeResult } {
  const result = read(text, options);
  const svg = result.figure ? toSvg(result.figure, { measurer: result.measurer, description: result.summary }) : null;
  return { svg, result };
}

function withTitle(chart: Chart, title: string | null): Chart {
  return { ...chart, title };
}

function assemble(built: { spec: DiagramSpec; built: Built }[], measurer: TextMeasurer): Figure {
  if (built.length === 1) {
    const { spec, built: one } = built[0];
    let single: Figure = { ...figureOf(one.chart), theme: spec.theme, title: spec.title, subtitle: spec.subtitle, caption: spec.caption };
    if (one.naturalWidth !== null && one.naturalHeight !== null) single = sizedFor(single, one.naturalWidth, one.naturalHeight, measurer);
    else single = withSize(single, 640, 400);
    if (spec.width !== null && spec.height !== null) single = withSize(single, spec.width, spec.height);
    return single;
  }

  // Several diagrams: a grid of charts, each titled with its own title, in the first diagram's theme.
  const first = built[0].spec;
  const charts = built.map((b) => withTitle(b.built.chart, b.spec.title));
  const cellWidth = Math.max(...built.map((b) => b.built.naturalWidth ?? 480));
  const cellHeight = Math.max(...built.map((b) => b.built.naturalHeight ?? 320));
  let grid: Figure = {
    ...figureOf(...charts),
    theme: first.theme,
    title: null,
    subtitle: first.subtitle,
    caption: first.caption,
    columns: Math.min(built.length, built.length <= 4 ? 2 : 3),
  };
  grid = sizedFor(grid, cellWidth, cellHeight, measurer);
  if (first.width !== null && first.height !== null) grid = withSize(grid, first.width, first.height);
  return grid;
}
