// Position scales: what a chart's layers said about an axis while it was trained, the range that resolves to, and the mapping from
// values to pixels once the axis has a length. Ported from Parcel NExT's Divooka.Graphics.Plotting/Scales/PositionScale.cs.
//
// Dhole's charts put numbers and categories on their axes, never dates and never a logarithmic scale, so the linear and categorical
// scales are ported whole and the others only as far as their transforms; asking one of them for ticks says it is not here.

import { defaultAxis, type Axis, type ScaleType } from "./axis";
import { linearNice, precisionFixed, scaleTickFormat, ticks as d3Ticks } from "./d3";
import { formatNumber, isTimeSpecifier, numberFormatter } from "./formatting";
import { describeKind, type Series, type SeriesKind } from "./series";

/** One tick of a drawn axis: the value it marks (a number, or a category's position in the order), what it says (empty for a minor tick), where it is in pixels along the axis, and whether it is labelled and gets a gridline. */
export interface AxisTick {
  readonly value: number;
  readonly label: string;
  readonly position: number;
  readonly isMajor: boolean;
}

/** The forward and backward transforms of a scale type. */
export function transforms(type: ScaleType, logBase: number): [(v: number) => number, (t: number) => number] {
  switch (type) {
    case "log":
      return [(v) => (v > 0 ? Math.log(v) / Math.log(logBase) : NaN), (t) => Math.pow(logBase, t)];
    case "sqrt":
      return [(v) => (v < 0 ? -Math.sqrt(-v) : Math.sqrt(v)), (t) => (t < 0 ? -t * t : t * t)];
    case "symlog":
      return [(v) => Math.sign(v) * Math.log(1 + Math.abs(v)), (t) => Math.sign(t) * (Math.exp(Math.abs(t)) - 1)];
    default:
      return [(v) => v, (t) => t];
  }
}

/**
 * A trained position scale: the mapping from values to pixels that one axis of one rendered chart used. On a categorical axis `map`
 * takes a category's position in `categories` and answers the middle of its band.
 */
export class PositionScale {
  private readonly forward: (v: number) => number;
  private readonly backward: (t: number) => number;
  private readonly t0: number;
  private readonly t1: number;
  /** The band arithmetic, signed: a vertical axis runs from the bottom up, so its steps are negative pixels. */
  private readonly bandOrigin: number = 0;
  private readonly signedStep: number = 0;
  private readonly signedBandwidth: number = 0;

  /** How the axis maps values: never "auto" once trained. */
  readonly type: ScaleType;
  readonly min: number;
  readonly max: number;
  readonly categories: readonly string[];
  /** Whether each category is a band (bars) rather than a point (lines over categories). */
  readonly banded: boolean;
  readonly logBase: number;
  /** The pixel min maps to (the first category's side). */
  readonly rangeStart: number;
  /** The pixel max maps to (the last category's side). */
  readonly rangeEnd: number;
  /** The ticks drawn, with their pixel positions. */
  readonly ticks: readonly AxisTick[];

  constructor(domain: ScaleDomain, rangeStart: number, rangeEnd: number, ticksInValueSpace: readonly AxisTick[], bandPadding: number) {
    this.type = domain.type;
    this.min = domain.min;
    this.max = domain.max;
    this.categories = domain.categories;
    this.banded = domain.banded;
    this.logBase = domain.logBase;
    if (domain.spec.reverse) [rangeStart, rangeEnd] = [rangeEnd, rangeStart];
    this.rangeStart = rangeStart;
    this.rangeEnd = rangeEnd;

    [this.forward, this.backward] = transforms(this.type, this.logBase);
    this.t0 = this.forward(this.min);
    this.t1 = this.forward(this.max);

    if (this.type === "category") {
      const n = Math.max(1, this.categories.length);
      if (this.banded) {
        // d3.scaleBand with paddingOuter = paddingInner / 2 and align 0.5.
        const inner = Math.min(Math.max(domain.bandPadding ?? bandPadding, 0), 1);
        const outer = inner / 2;
        this.signedStep = (rangeEnd - rangeStart) / Math.max(1, n - inner + outer * 2);
        this.signedBandwidth = this.signedStep * (1 - inner);
        this.bandOrigin = rangeStart + (rangeEnd - rangeStart - this.signedStep * (n - inner)) * 0.5;
      } else {
        // d3.scalePoint with padding 0.5: each category a point, half a step from either end.
        this.signedStep = (rangeEnd - rangeStart) / n;
        this.signedBandwidth = 0;
        this.bandOrigin = rangeStart + this.signedStep / 2;
      }
    }

    this.ticks = ticksInValueSpace.map((t) => ({ ...t, position: this.map(t.value) }));
  }

  /** A category band's width in pixels; 0 on a continuous axis or a point axis. */
  get bandwidth(): number {
    return Math.abs(this.signedBandwidth);
  }
  /** The distance in pixels from one category to the next; 0 on a continuous axis. */
  get step(): number {
    return Math.abs(this.signedStep);
  }
  get isCategorical(): boolean {
    return this.type === "category";
  }

  /** The pixel for a value, or for a category's position in the order (its band's middle). Not a number for a value the scale cannot place. */
  map(value: number): number {
    if (Number.isNaN(value)) return NaN;
    if (this.type === "category") return this.bandOrigin + this.signedStep * value + this.signedBandwidth / 2;
    const t = this.forward(value);
    if (!Number.isFinite(t)) return NaN;
    if (this.t1 === this.t0) return (this.rangeStart + this.rangeEnd) / 2;
    return this.rangeStart + ((t - this.t0) / (this.t1 - this.t0)) * (this.rangeEnd - this.rangeStart);
  }

  /** The value at a pixel: the inverse of map; on a categorical axis, the fractional position in the order. */
  invert(pixel: number): number {
    if (this.type === "category") return this.signedStep === 0 ? 0 : (pixel - this.bandOrigin - this.signedBandwidth / 2) / this.signedStep;
    if (this.rangeEnd === this.rangeStart) return this.min;
    const t = this.t0 + ((pixel - this.rangeStart) / (this.rangeEnd - this.rangeStart)) * (this.t1 - this.t0);
    return this.backward(t);
  }

  /** The lower pixel edge of category `index`'s band: its left on a horizontal axis, its top on a vertical one. */
  bandStart(index: number): number {
    return Math.min(this.bandOrigin + this.signedStep * index, this.bandOrigin + this.signedStep * index + this.signedBandwidth);
  }

  /** The position of `category` in the order, or -1. */
  indexOf(category: string): number {
    return this.categories.indexOf(category);
  }

  /** The pixel for a category's middle; not a number when the axis has no such category. */
  mapCategory(category: string): number {
    const index = this.indexOf(category);
    return index < 0 ? NaN : this.map(index);
  }

  toString(): string {
    return this.type === "category"
      ? `Category scale: ${this.categories.length} categories over ${this.rangeStart.toFixed(1)}..${this.rangeEnd.toFixed(1)} px`
      : `${this.type} scale: ${this.min}..${this.max} over ${this.rangeStart.toFixed(1)}..${this.rangeEnd.toFixed(1)} px`;
  }
}

/** Everything a chart's layers said about one axis while it was being trained: the kinds of value bound to it, their extent, their categories, and whether something wants a zero or bands. */
export class AxisTraining {
  private readonly seen = new Set<string>();
  readonly spec: Axis;
  readonly name: string;
  kind: SeriesKind | null = null;
  low = Number.POSITIVE_INFINITY;
  high = Number.NEGATIVE_INFINITY;
  lowPositive = Number.POSITIVE_INFINITY;
  nonPositiveCount = 0;
  readonly categories: string[] = [];
  banded = false;
  wantsZero = false;
  used = false;
  /** Whether a vertical axis of categories should list them from the top down, as horizontal bars read. */
  topDown = false;
  /** A label format a layer would like when the axis states none: percentages for a percent-stacked bar. */
  preferredFormat: string | null = null;
  /** The share of each band left empty, when a layer needs other than the theme's. */
  bandPadding: number | null = null;
  /** Whether the fitted range should end exactly at the data, with no margin. */
  tight = false;

  constructor(spec: Axis, name: string) {
    this.spec = spec;
    this.name = name;
  }

  /** Bind a series to this axis. */
  add(series: Series): void {
    this.claim(series.kind, series.name);
    if (series.kind === "text") {
      for (const category of series.textsOf) this.addCategory(category);
      return;
    }
    for (let i = 0; i < series.count; i++) this.addValue(series.position(i));
  }

  /** Bind one more value of the axis' own kind (a stacked total, a fitted line's end). */
  addValue(value: number): void {
    this.used = true;
    if (!Number.isFinite(value)) return;
    if (value < this.low) this.low = value;
    if (value > this.high) this.high = value;
    if (value > 0 && value < this.lowPositive) this.lowPositive = value;
    if (value <= 0) this.nonPositiveCount++;
  }

  /** Bind a category, keeping the order of first appearance. */
  addCategory(category: string): void {
    this.claim("text", null);
    if (!this.seen.has(category)) {
      this.seen.add(category);
      this.categories.push(category);
    }
  }

  /** Say what kind of value the axis carries, refusing a second kind. */
  claim(kind: SeriesKind, seriesName: string | null): void {
    this.used = true;
    if (this.kind === null) {
      this.kind = kind;
      return;
    }
    if (this.kind !== kind)
      throw new Error(
        `The ${this.name} axis was given ${describeKind(this.kind)} and then ${describeKind(kind)}${seriesName ? ` ('${seriesName}')` : ""}; one axis shows one kind of value. Put the second on a chart of its own, or convert it.`,
      );
  }
}

const DefaultMargin = 0.04;

/**
 * An axis' resolved range, before it has a length in pixels: the scale type, the extent shown, and the categories. Separate from
 * PositionScale because the range is decided by the data and the axis' settings alone, and the layout needs to measure the tick
 * labels it implies before it knows how long the axis will be.
 */
export class ScaleDomain {
  type: ScaleType = "linear";
  min = 0;
  max = 1;
  categories: readonly string[] = [];
  banded = false;
  logBase = 10;
  spec: Axis = defaultAxis;
  empty = false;
  /** Whether a layer grows from zero on this axis (bars, areas), so zero is its baseline. */
  wantsZero = false;
  /** The share of each category band left empty, when a layer said; otherwise the theme's. */
  bandPadding: number | null = null;

  private static make(fields: Partial<ScaleDomain>): ScaleDomain {
    return Object.assign(new ScaleDomain(), fields);
  }

  /** Resolve an axis from what its layers said about it. */
  static resolve(training: AxisTraining, notes: string[]): ScaleDomain {
    let spec = training.spec;
    if (spec.format === null && spec.formatter === null && training.preferredFormat !== null) spec = { ...spec, format: training.preferredFormat };
    if (training.topDown) spec = { ...spec, reverse: !spec.reverse };
    let type = spec.scale;
    if (type === "auto") type = training.kind === "text" ? "category" : training.kind === "time" ? "time" : spec.tickLabels !== null && spec.tickValues === null ? "category" : "linear";

    if (type === "category") {
      const categories: string[] = [];
      if (spec.categories !== null) for (const c of spec.categories) if (!categories.includes(c)) categories.push(c);
      for (const category of training.categories) if (!categories.includes(category)) categories.push(category);
      if (training.kind === "number" && categories.length === 0 && spec.tickLabels !== null) categories.push(...spec.tickLabels);
      if ((training.kind === "number" || training.kind === "time") && training.categories.length === 0 && categories.length === 0)
        throw new Error(`The ${training.name} axis was set to show categories but was given ${describeKind(training.kind)}; give it text, or another scale.`);
      return ScaleDomain.make({
        type,
        min: 0,
        max: Math.max(0, categories.length - 1),
        categories,
        banded: training.banded,
        spec,
        empty: categories.length === 0,
        bandPadding: training.bandPadding,
      });
    }

    if (training.kind === "text") throw new Error(`The ${training.name} axis was set to ${type} but was given text; text can only be shown as categories.`);
    if (type === "time" && training.kind === "number") type = "linear";

    const empty = !Number.isFinite(training.low);
    let low = empty ? 0 : training.low;
    let high = empty ? 1 : training.high;

    let statedMin = spec.min;
    const statedMax = spec.max;

    if (type === "log") {
      if (training.nonPositiveCount > 0)
        notes.push(`${training.nonPositiveCount} value${training.nonPositiveCount === 1 ? " was" : "s were"} at or below zero and could not be placed on the logarithmic ${training.name} axis.`);
      const anyPositive = Number.isFinite(training.lowPositive);
      low = anyPositive ? training.lowPositive : 1;
      high = anyPositive ? Math.max(training.high, low) : 10;
      if (statedMin !== null && statedMin <= 0) {
        notes.push(`The logarithmic ${training.name} axis cannot start at ${statedMin}; it starts at the smallest positive value instead.`);
        statedMin = null;
      }
    }

    const zero = (type === "linear" || type === "sqrt" || type === "symlog") && (spec.includeZero ?? training.wantsZero);
    if (zero) {
      low = Math.min(low, 0);
      high = Math.max(high, 0);
    }
    if (statedMin !== null) low = statedMin;
    if (statedMax !== null) high = statedMax;
    if (low > high) [low, high] = [high, low];

    if (low === high) {
      if (type === "log") {
        low /= 10;
        high *= 10;
      } else if (type === "time") {
        low -= 43_200_000;
        high += 43_200_000;
      } else if (low === 0) {
        high = 1;
        if (!zero) low = -1;
      } else {
        const pad = Math.abs(low) * 0.1;
        if (statedMin === null && !(zero && low === 0)) low -= pad;
        if (statedMax === null) high += pad;
      }
    }

    const nice = spec.nice || (spec.margin === null && statedMin === null && statedMax === null && !training.tight && (training.wantsZero || type === "log"));
    const margin = spec.margin ?? (nice || training.tight ? 0 : DefaultMargin);
    if (margin > 0) {
      const [forward, backward] = transforms(type, spec.logBase);
      const tl = forward(low);
      const th = forward(high);
      const span = th - tl;
      const lowPinned = statedMin !== null || (zero && low === 0);
      const highPinned = statedMax !== null || (zero && high === 0);
      if (!lowPinned) low = backward(tl - span * margin);
      if (!highPinned) high = backward(th + span * margin);
    }
    if (nice) {
      const [niceLow, niceHigh] = nicen(type, low, high);
      if (statedMin === null) low = niceLow;
      if (statedMax === null) high = niceHigh;
    }

    return ScaleDomain.make({ type, min: low, max: high, logBase: spec.logBase, spec, empty, wantsZero: training.wantsZero });
  }

  /** A domain stated outright rather than trained: a polar radius. */
  static continuous(type: ScaleType, min: number, max: number, spec: Axis): ScaleDomain {
    return ScaleDomain.make({ type, min, max, spec, logBase: spec.logBase });
  }

  /** The ticks for about `count` divisions, with labels, in value space (positions are filled in by the scale). */
  ticks(count: number): AxisTick[] {
    count = Math.max(1, count);
    const spec = this.spec;

    if (this.type === "category") {
      return this.categories.map((category, i) => ({
        value: i,
        label: spec.tickLabels !== null && spec.tickValues === null && i < spec.tickLabels.length ? spec.tickLabels[i] : category,
        position: 0,
        isMajor: true,
      }));
    }

    if (this.empty && spec.tickValues === null) return [];

    if (spec.tickValues !== null) {
      const stated = this.labelFormatter();
      const out: AxisTick[] = [];
      for (let i = 0; i < spec.tickValues.length; i++) {
        const value = spec.tickValues[i];
        if (value < Math.min(this.min, this.max) - 1e-9 * Math.abs(this.max - this.min) || value > Math.max(this.min, this.max) + 1e-9 * Math.abs(this.max - this.min)) continue;
        const label = spec.tickLabels !== null && i < spec.tickLabels.length ? spec.tickLabels[i] : stated(value);
        out.push({ value, label, position: 0, isMajor: true });
      }
      return out;
    }

    if (spec.tickStep !== null && spec.tickStep > 0 && this.type !== "log") {
      const step = spec.tickStep;
      if (this.type === "time") throw new Error("Time axes are not drawn on this page.");
      const stepFormat = spec.formatter ?? (spec.format !== null && !isTimeSpecifier(spec.format) ? numberFormatter(spec.format) : stepFormatter(step));
      const out: AxisTick[] = [];
      const first = Math.ceil(this.min / step - 1e-9) * step;
      for (let i = 0; i < 1000; i++) {
        let value = first + i * step;
        if (value > this.max + step * 1e-9) break;
        if (Math.abs(value) < step * 1e-9) value = 0;
        out.push({ value, label: stepFormat(value), position: 0, isMajor: true });
      }
      return out;
    }

    if (this.type !== "linear") throw new Error(`A ${this.type} axis is not drawn on this page.`);
    const values = d3Ticks(this.min, this.max, count);
    const format = spec.formatter ?? scaleTickFormat(this.min, this.max, count, spec.format);
    return values.map((v) => ({ value: v, label: format(v), position: 0, isMajor: true }));
  }

  /** How a stated tick value is labelled when no label is stated with it. */
  private labelFormatter(): (value: number) => string {
    if (this.spec.formatter !== null) return this.spec.formatter;
    if (this.spec.format !== null) return numberFormatter(this.spec.format);
    return formatNumber;
  }
}

function nicen(type: ScaleType, low: number, high: number): [number, number] {
  if (type !== "linear") throw new Error(`A ${type} axis is not drawn on this page.`);
  const d = linearNice([low, high]);
  return [d[0], d[d.length - 1]];
}

/** A label format with just enough decimals to tell ticks `step` apart. */
function stepFormatter(step: number): (value: number) => string {
  const decimals = precisionFixed(step);
  return numberFormatter(`,.${Math.trunc(Math.min(decimals, 12))}f`);
}
