/** The kind a word names - its own word or one of its others - or null. */
export function findKind(word: string): KindInfo | null {
  const key = Scan.key(word);
  if (key.length === 0) return null;
  return Kinds.find((k) => k.word === key) ?? Kinds.find((k) => k.aliases.includes(key)) ?? null;
}

/** The small words a summary needs: "a" or "an", one or many. */
export const Grammar = {
  /** "a" or "an" before a word. */
  a(word: string): string {
    return word.length > 0 && "aeiouAEIOU".includes(word[0]) ? "an" : "a";
  },
  /** A count with its noun, the noun made plural by `plural` when the count is not one. */
  count(count: number, one: string, plural?: string): string {
    return `${count} ${count === 1 ? one : plural ?? one + "s"}`;
  },
};

/** What a diagram builds into: one chart of the figure, the size its content wants when it has one, and a sentence saying what it holds. */
export interface Built {
  readonly chart: Chart;
  readonly naturalWidth: number | null;
  readonly naturalHeight: number | null;
  readonly summary: string;
}

/** What building a diagram has to hand: what its text is measured with. */
export interface BuildContext {
  readonly measurer: TextMeasurer;
}

/** One diagram as read: its kind, its titles, its theme and size, and how it becomes a chart. */
export abstract class DiagramSpec {
  readonly kind: KindInfo;
  readonly kindLine: SourceLine;
  title: string | null = null;
  subtitle: string | null = null;
  caption: string | null = null;
  theme: Theme = Light;
  width: number | null = null;
  height: number | null = null;

  constructor(kind: KindInfo, kindLine: SourceLine) {
    this.kind = kind;
    this.kindLine = kindLine;
  }

  /** The diagram as a chart. */
  abstract build(problems: ProblemList, context: BuildContext): Built;

  /** Whether the text gave the diagram nothing to draw - no slices, no steps - so the text draws nothing rather than an empty frame. */
  get isEmpty(): boolean {
    return false;
  }
}

/** A setting a kind takes: the words it answers to and what it does with its value. */
export interface Setting {
  readonly names: readonly string[];
  apply(value: Span): void;
}

export function setting(names: readonly string[], apply: (value: Span) => void): Setting {
  return { names, apply };
}

function answers(s: Setting, key: string): boolean {
  return s.names.some((n) => Scan.key(n) === key);
}

/** What every kind's parser has: the settings every diagram takes, the readers for setting values, and the order lines are read in. */
export abstract class KindParser {
  private readonly set = new Set<string>();
  protected readonly context: ReadContext;
  protected readonly problems: ProblemList;
  private font: string | null = null;

  constructor(context: ReadContext) {
    this.context = context;
    this.problems = context.problems;
  }

  abstract get spec(): DiagramSpec;

  /** The settings of this kind, besides the ones every kind takes. */
  protected get settings(): Setting[] {
    return [];
  }

  /** Reads the lines after the kind's own line. */
  read(roots: Block[]): void {
    this.spec.title = this.context.title;
    this.titled();
    const top = roots.length === 0 ? 0 : Math.min(...roots.map((r) => r.line.indent));
    for (const block of roots) {
      if (block.line.indent === top && this.trySetting(block)) continue;
      this.content(block);
    }
    this.finish();
  }

  /** Called once the first line's title is known, for a kind that reads something else there. */
  protected titled(): void {}
  /** Reads one line at the top - and the lines under it - that is not a setting. */
  protected abstract content(block: Block): void;
  /** Called once every line is read. */
  protected finish(): void {}

  private get common(): Setting[] {
    return [
      setting(["title"], (v) => (this.spec.title = this.text(v))),
      setting(["subtitle"], (v) => (this.spec.subtitle = this.text(v))),
      setting(["caption", "source", "note"], (v) => (this.spec.caption = this.text(v))),
      setting(["theme", "style", "look"], (v) => this.readTheme(v)),
      setting(["font", "typeface", "face"], (v) => (this.font = this.text(v))),
      setting(["size"], (v) => this.readSize(v)),
    ];
  }

  /** The words every setting of this kind answers to, for a hint. */
  protected get settingNames(): string[] {
    return [...this.common, ...this.settings].map((s) => s.names[0]);
  }

  /** Reads a line as a setting when its words before the colon name one; false when they do not. */
  protected trySetting(block: Block): boolean {
    const { head, tail } = Scan.splitColon(block.content);
    if (tail === null || head.isEmpty || head.text.includes('"')) return false;
    const key = Scan.key(head.text);
    const found = this.settings.find((s) => answers(s, key)) ?? this.common.find((s) => answers(s, key));
    if (!found) return false;
    // A kind's own lines may look like a setting - a pie's slice called "title" - and an arrow on the line says it is not one.
    if (Scan.arrows(head, ArrowSet.plain).arrows.length > 0) return false;
    const name = found.names[0];
    if (this.set.has(name)) this.problems.warning(head, "SettingRepeated", name);
    this.set.add(name);
    if (tail.isEmpty) {
      this.problems.error(head, "SettingNeedsValue", name);
      return true;
    }
    found.apply(tail);
    for (const child of block.children) this.problems.warning(child.content, "IndentedUnderNothing");
    return true;
  }

  protected text(value: Span): string {
    return Scan.name(value, this.problems);
  }

  /** Whether a line of data is a setting with a slip in its name - "titel: Sales" - which it says, so the caller leaves the line out: its name is near a setting's, and its value has no digit for data to be read from. */
  protected settingSlip(head: Span, value: Span): boolean {
    if ([...value.text].some(Scan.isDigit)) return false;
    const nearest = Scan.nearest(head.text, this.settingNames);
    if (nearest === null) return false;
    this.problems.error(head, "SettingGuessed", head.text.trim(), nearest);
    return true;
  }

  /** Warns of an attribute no word answers to: with the word it was probably meant to be when one is near, or else with the words it can be. */
  protected unknownAttribute(attribute: Span, what: Said, choices: readonly string[], hint?: readonly string[]): void {
    const word = attribute.text.trim();
    const nearest = Scan.nearest(word, choices);
    if (nearest !== null) this.problems.warning(attribute, "AttributeGuessed", word, what, nearest);
    else this.problems.warning(attribute, "UnknownAttribute", word, what, hint ?? choices);
  }

  /** Sets the font a font setting named on the diagram's theme, whichever line came first. */
  applyFont(): void {
    if (this.font && this.font.trim()) this.spec.theme = withFont(this.spec.theme, this.font);
  }

  private readTheme(value: Span): void {
    const theme = findTheme(value.text);
    if (!theme) {
      this.problems.error(value, "BadTheme", value.text, Presets.map((t) => t.name.toLowerCase()));
      return;
    }
    this.spec.theme = theme;
  }

  private readSize(value: Span): void {
    const size = Scan.trySize(value.text);
    if (size) {
      this.spec.width = size.width;
      this.spec.height = size.height;
    } else this.problems.error(value, "BadSize", value.text);
  }

  /** A direction: down, right, up or left, in the words people use for them. */
  protected readDirection(value: Span): Direction | null {
    let direction: Direction | null = null;
    switch (Scan.key(value.text)) {
      case "down":
      case "td":
      case "tb":
      case "topdown":
      case "toptobottom":
      case "vertical":
      case "south":
        direction = "down";
        break;
      case "right":
      case "lr":
      case "leftright":
      case "lefttoright":
      case "horizontal":
      case "across":
      case "east":
        direction = "right";
        break;
      case "up":
      case "bt":
      case "bottomup":
      case "bottomtotop":
      case "north":
        direction = "up";
        break;
      case "left":
      case "rl":
      case "rightleft":
      case "righttoleft":
      case "west":
        direction = "left";
        break;
    }
    if (direction === null) this.problems.error(value, "BadDirection", value.text);
    return direction;
  }

  /** On or off. */
  protected readSwitch(value: Span): boolean | null {
    const on = Scan.switchValue(value.text);
    if (on === null) this.problems.error(value, "BadSwitch", value.text);
    return on;
  }

  /** A number, or null when it is not one (said). */
  protected readNumber(value: Span, percentAsFraction = false): number | null {
    const n = Scan.tryNumber(value.text, percentAsFraction);
    if (!Number.isNaN(n)) return n;
    this.problems.error(value, "BadNumber", value.text);
    return null;
  }

  /** A range: 0..100. */
  protected readRange(value: Span): { low: number; high: number } | null {
    const r = Scan.tryRange(value.text);
    if (r) return r;
    this.problems.error(value, "BadRange", value.text);
    return null;
  }

  /** One of a setting's choices, by any of its words. */
  protected readChoice<T>(value: Span, settingName: string, ...choices: [readonly string[], T][]): T | null {
    const key = Scan.key(value.text);
    for (const [words, choice] of choices) if (words.some((w) => Scan.key(w) === key)) return choice;
    this.problems.error(value, "BadChoice", value.text, settingName, choices.map((c) => c[0][0]));
    return null;
  }

  /** Reads the lines under a line that holds nothing as if they were not indented, and says so once. */
  protected unindent(block: Block, read: (b: Block) => void): void {
    if (block.children.length === 0) return;
    this.problems.warning(block.children[0].content, "IndentedUnderNothing");
    for (const child of block.children) {
      read(new Block(child.line));
      this.unindent(child, read);
    }
  }
}

// ---------------------------------------------------------------- the kinds' parsers

type ParserFactory = (context: ReadContext) => KindParser;
const parsers = new Map<string, ParserFactory>();

/** Registers the parser of a kind, by its word: each kind's module does, so the reader knows only the kinds a page loaded. */
export function registerKind(word: string, create: ParserFactory): void {
  parsers.set(word, create);
}

/** The words of the kinds this page can draw. */
export function drawnKinds(): string[] {
  return Kinds.filter((k) => parsers.has(k.word)).map((k) => k.word);
}

/**
 * A kind Divooka draws that this page does not: its first line is said (NotDrawnHere, a problem of this port's own, since
 * Divooka has no such case), and it draws nothing - so a text with one in it still draws its other diagrams.
 */
class NotHereParser extends KindParser {
  private readonly own: DiagramSpec;
  constructor(context: ReadContext) {
    super(context);
    const problems = context.problems;
    this.own = new (class extends DiagramSpec {
      // Nothing to draw, so the figure leaves it out, and the problem says why.
      override get isEmpty(): boolean {
        return true;
      }
      build(): Built {
        throw new Error("A kind this page does not draw is never built.");
      }
    })(context.kind, context.kindLine);
    problems.error(context.kindLine.content, "NotDrawnHere", context.kind.name);
  }
  get spec(): DiagramSpec {
    return this.own;
  }
  protected content(): void {}
}

const kindWordPattern = /^(?<word>\p{L}[\p{L}\p{Nd}\-_]*)/u;

/** How a text is read. */
export interface ReadOptions {
  /** The theme a diagram has when its text names none - Light, as in Divooka, unless a page says otherwise. */
  readonly defaultTheme?: Theme;
}

/** Reads Dhole text: the diagrams it describes, and every problem in it. */
export function readDhole(text: string | null | undefined, options: ReadOptions = {}): { specs: DiagramSpec[]; problems: ProblemList } {
  const problems = new ProblemList();
  const specs: DiagramSpec[] = [];
  const raw = (text ?? "").replaceAll("\r\n", "\n").replaceAll("\r", "\n").split("\n");
  const lines = raw.map((t, i) => new SourceLine(i + 1, t));
  for (const line of lines)
    if (line.hasTab && line.hasSpace && !line.isBlank && !line.isComment) problems.warningAt(line.number, 1, Math.max(1, line.content.start), "MixedIndentation");

  const segments: SourceLine[][] = [[]];
  const separators: SourceLine[] = [];
  for (const line of lines) {
    if (line.isSeparator) {
      segments.push([]);
      separators.push(line);
    } else segments[segments.length - 1].push(line);
  }

  for (let s = 0; s < segments.length; s++) {
    const content = segments[s].filter((l) => !l.isBlank && !l.isComment);
    if (content.length === 0) {
      // An empty stretch between two separators says nothing was meant there; one before the first or after the last is only tidiness.
      if (s > 0 && s < segments.length - 1) problems.warning(separators[s - 1].content, "SeparatorWithoutDiagram");
      continue;
    }
    const spec = readOne(content, problems, options);
    if (spec) specs.push(spec);
  }
  if (specs.length === 0 && problems.count === 0) problems.errorAt(1, 1, 1, "Empty");
  return { specs, problems };
}

function readOne(content: SourceLine[], problems: ProblemList, options: ReadOptions): DiagramSpec | null {
  const first = content[0];
  const line = first.content;
  const word = kindWordPattern.exec(line.text);
  const kindWords: ProblemArgument = Kinds.map((k) => k.word);
  if (!word) {
    problems.error(line, "NoKind", line.text, kindWords);
    return null;
  }
  const firstWord = word.groups!.word;
  let rest = line.from(firstWord.length);
  let kind = findKind(firstWord);
  // Two words for one kind - "mind map", "state machine", "pie chart" - are read as one before the first is read alone, so "chart" is not taken for the title.
  const second = kindWordPattern.exec(rest.trim().text);
  if (second) {
    const pair = findKind(firstWord + second.groups!.word);
    if (pair) {
      kind = pair;
      const trimmed = rest.trim();
      rest = trimmed.from(second.groups!.word.length);
    }
  }
  if (!kind) {
    const guess = Scan.nearest(firstWord, [...Kinds.map((k) => k.word), ...Kinds.flatMap((k) => k.aliases)]);
    const guessed = guess === null ? null : findKind(guess);
    if (!guessed) {
      problems.error(line.slice(0, firstWord.length), "NoKind", firstWord, kindWords);
      return null;
    }
    problems.error(line.slice(0, firstWord.length), "KindGuessed", firstWord, guessed.name, guessed.word);
    kind = guessed;
  }

  let titleText = rest.trim().text;
  if (titleText.startsWith(":") || titleText.startsWith("\uFF1A")) titleText = titleText.slice(1).trim();
  const trimmedRest = rest.trim();
  const context: ReadContext = {
    problems,
    kind,
    kindLine: first,
    title: titleText.length === 0 ? null : Scan.name(trimmedRest.from(trimmedRest.text.length - titleText.length), problems),
    kindWord: Scan.key(firstWord),
  };
  const create = parsers.get(kind.word) ?? ((c: ReadContext) => new NotHereParser(c));
  const parser = create(context);
  if (options.defaultTheme) parser.spec.theme = options.defaultTheme;
  parser.read(Block.forest(content.slice(1)));
  parser.applyFont();
  return parser.spec;
}
