// Bars from zero, one per category: a bar chart, grouped or stacked bars.
// Ported from Parcel NExT's Divooka.Graphics.Plotting/Layers/Bars.cs.
//
// Each category gets a band on the category axis, in order of first appearance; numbers given as categories are written as text, so
// years make a band each. A category given twice adds up. With `colorBy` each category holds a bar per group - side by side, piled up,
// or piled to 100% as `mode` says - each group in its colour. Bars grow from a single baseline with their value end rounded; touching
// bars are parted by a gap of the background colour rather than an outline.

import { inkOn, withOpacity } from "../color-math";
import { ChartLayerPlan, ChartPaints, chartContext, xScale, yOf, type ChartTraining, type LegendCollector } from "../contracts";
import { Layer, type DrawContext, type PlanContext, type TextPainter } from "../figure";
import { formatNumber, formatWith } from "../formatting";
import type { PositionScale } from "../scales";
import { Series } from "../series";
import type { Colour } from "../theme";
import { Check, type StackMode } from "./lines";
import { bar, rectBetween } from "./marks";
import { RectF } from "../../rendering/geometry";

export class Bars extends Layer {
  /** The categories, one per bar (or per group of bars). */
  readonly categories: Series;
  /** The bars' lengths. */
  readonly values: Series;
  /** Splits each category into a bar per group, coloured by group. */
  colorBy: Series | null = null;
  /** How the groups of a category are combined. */
  mode: StackMode = "grouped";
  /** Whether the bars run left to right, with the categories down the side. */
  horizontal = false;
  /** Whether each bar's value is written at its end. */
  valueLabels = false;
  /** How value labels are written: a D3 number format. */
  labelFormat: string | null = null;

  constructor(categories: Series | readonly string[], values: Series | readonly number[]) {
    super();
    this.categories = categories instanceof Series ? categories : Series.ofTexts(categories as readonly string[]);
    this.values = Series.of(values);
  }

  plan(context: PlanContext): BarsPlan {
    Check.sameLength(this.categories, this.values, "category", "value");
    Check.numbers(this.values, "bar values");
    if (this.colorBy !== null) Check.sameLength(this.categories, this.colorBy, "category", "colour");
    return new BarsPlan(this, this.colorBy === null ? context.seriesColor(this) : { r: 0, g: 0, b: 0, a: 0 });
  }
}

class BarsPlan extends ChartLayerPlan {
  private readonly categories: string[] = [];
  private readonly groups: string[] = [];
  private readonly values: number[][];
  private readonly spans: [number, number][][];

  constructor(
    private readonly bars: Bars,
    private readonly color: Colour,
  ) {
    super(bars);
    const seenCategories = new Set<string>();
    const seenGroups = new Set<string>();
    for (let i = 0; i < bars.categories.count; i++) {
      const category = bars.categories.text(i);
      if (!seenCategories.has(category)) {
        seenCategories.add(category);
        this.categories.push(category);
      }
      const group = bars.colorBy?.text(i) ?? "";
      if (!seenGroups.has(group)) {
        seenGroups.add(group);
        this.groups.push(group);
      }
    }
    const ci = new Map(this.categories.map((c, i) => [c, i]));
    const gi = new Map(this.groups.map((g, i) => [g, i]));
    this.values = this.groups.map(() => this.categories.map(() => 0));
    const present = this.groups.map(() => this.categories.map(() => false));
    for (let i = 0; i < bars.categories.count; i++) {
      const v = bars.values.numbersOf[i];
      const c = ci.get(bars.categories.text(i))!;
      const g = gi.get(bars.colorBy?.text(i) ?? "")!;
      if (!Number.isFinite(v)) continue;
      this.values[g][c] += v;
      present[g][c] = true;
    }

    const mode: StackMode = this.groups.length === 1 && bars.mode === "grouped" ? "grouped" : bars.mode;
    this.spans = this.groups.map(() => this.categories.map((): [number, number] => [0, 0]));
    for (let c = 0; c < this.categories.length; c++) {
      let total = 0;
      for (let g = 0; g < this.groups.length; g++) total += Math.abs(this.values[g][c]);
      let positive = 0;
      let negative = 0;
      for (let g = 0; g < this.groups.length; g++) {
        let v = this.values[g][c];
        if (mode === "percent") v = total === 0 ? 0 : v / total;
        if (mode === "grouped") this.spans[g][c] = present[g][c] ? [Math.min(0, v), Math.max(0, v)] : [NaN, NaN];
        else if (v >= 0) {
          this.spans[g][c] = [positive, positive + v];
          positive += v;
        } else {
          this.spans[g][c] = [negative + v, negative];
          negative += v;
        }
      }
    }
  }

  private get stacked(): boolean {
    return this.bars.mode !== "grouped" && this.groups.length > 1;
  }

  override train(training: ChartTraining): void {
    const bars = this.bars;
    const categoryAxis = training.categoryAxisOf(bars, bars.horizontal);
    const valueAxis = training.valueAxisOf(bars, bars.horizontal);
    for (const category of this.categories) categoryAxis.addCategory(category);
    categoryAxis.banded = true;
    if (bars.horizontal) categoryAxis.topDown = true;
    valueAxis.claim("number", bars.values.name);
    valueAxis.wantsZero = true;
    if (bars.mode === "percent" && this.groups.length > 1) valueAxis.preferredFormat = ".0%";
    let low = 0;
    let high = 0;
    for (const row of this.spans)
      for (const [lo, hi] of row) {
        valueAxis.addValue(lo);
        valueAxis.addValue(hi);
        if (Number.isFinite(lo)) low = Math.min(low, lo);
        if (Number.isFinite(hi)) high = Math.max(high, hi);
      }
    // A label written past the end of a horizontal bar needs room on the value axis; a vertical bar's label takes it from the space above the plotting area instead.
    if (bars.valueLabels && bars.horizontal && !this.stacked) {
      valueAxis.addValue(high + (high - low) * 0.15);
      if (low < 0) valueAxis.addValue(low - (high - low) * 0.15);
    }
    if (bars.colorBy !== null) for (const group of this.groups) training.color.addCategory(group);
  }

  draw(context: DrawContext): void {
    const bars = this.bars;
    const theme = context.theme;
    const categoryScale = bars.horizontal ? yOf(context, bars) : xScale(context);
    const valueScale = bars.horizontal ? xScale(context) : yOf(context, bars);
    const gap = theme.barGap;
    let band = categoryScale.bandwidth;
    if (band <= 0) band = Math.max(1, categoryScale.step * (1 - theme.barPadding));
    const groups = this.groups.length;
    const maxWidth = theme.maxBarWidth > 0 ? theme.maxBarWidth : Number.POSITIVE_INFINITY;

    for (let c = 0; c < this.categories.length; c++) {
      const center = categoryScale.mapCategory(this.categories[c]);
      if (!Number.isFinite(center)) continue;
      if (this.stacked) {
        const width = Math.min(band, maxWidth * 1.5);
        // Which segment ends each pile, so only the outer end is rounded.
        let topPositive = -1;
        let bottomNegative = -1;
        for (let g = 0; g < groups; g++) {
          const [lo, hi] = this.spans[g][c];
          if (hi > lo && hi > 0) topPositive = g;
          if (hi > lo && lo < 0 && bottomNegative < 0) bottomNegative = g;
        }
        for (let g = 0; g < groups; g++) {
          const [lo, hi] = this.spans[g][c];
          if (!(hi > lo)) continue;
          const outer = g === topPositive || g === bottomNegative;
          this.drawBar(context, valueScale, center, width, lo, hi, this.fill(context, g), outer, gap / 2, g, c);
        }
      } else {
        let width = (band - gap * (groups - 1)) / groups;
        width = Math.max(1, Math.min(width, maxWidth));
        const total = width * groups + gap * (groups - 1);
        for (let g = 0; g < groups; g++) {
          const [lo, hi] = this.spans[g][c];
          if (Number.isNaN(lo)) continue;
          const offset = -total / 2 + width / 2 + g * (width + gap);
          this.drawBar(context, valueScale, center + offset, width, lo, hi, this.fill(context, g), true, 0, g, c);
        }
      }
    }
  }

  private fill(context: DrawContext, group: number): Colour {
    return withOpacity(this.bars.colorBy === null ? this.color : chartContext(context).colors.forCategory(this.groups[group]), this.bars.opacity);
  }

  private drawBar(context: DrawContext, valueScale: PositionScale, center: number, width: number, lo: number, hi: number, fill: Colour, roundEnd: boolean, inset: number, group: number, category: number): void {
    const bars = this.bars;
    let p0 = valueScale.map(lo);
    const p1 = valueScale.map(hi);
    if (valueScale.type === "log") {
      // A logarithmic axis has no zero: bars grow from its bottom.
      if (lo <= 0) p0 = valueScale.rangeStart;
      if (!(hi > 0)) return;
    }
    if (!Number.isFinite(p0) || !Number.isFinite(p1)) return;
    const negative = hi <= 0 && lo < 0;
    let rect: RectF;
    let valueEnd: number;
    if (bars.horizontal) {
      rect = rectBetween(Math.min(p0, p1), center - width / 2, Math.max(p0, p1), center + width / 2);
      rect = new RectF(rect.left + (inset > 0 && lo !== 0 ? inset : 0), rect.top, rect.right - (inset > 0 ? inset : 0), rect.bottom);
      valueEnd = negative ? 3 : 1;
    } else {
      rect = rectBetween(center - width / 2, Math.min(p0, p1), center + width / 2, Math.max(p0, p1));
      rect = new RectF(rect.left, rect.top + (inset > 0 ? inset : 0), rect.right, rect.bottom - (inset > 0 && lo !== 0 ? inset : 0));
      valueEnd = negative ? 2 : 0;
    }
    if (rect.width <= 0 || rect.height <= 0) return;
    const radius = roundEnd ? context.theme.barRadius : 0;
    context.sink.drawPath(bar(rect, valueEnd, radius), ChartPaints.fill(fill));

    if (!bars.valueLabels) return;
    const value = this.values[group][category];
    const label = bars.labelFormat !== null ? formatWith(value, bars.labelFormat) : bars.mode === "percent" && this.stacked ? formatWith(hi - lo, ".0%") : formatNumber(value);
    const text = context.text;
    if (this.stacked) {
      // Inside the segment, only when it fits with room to spare.
      const size = text.measure(label, "dataLabel");
      if (size.width + 6 <= rect.width && size.height + 4 <= rect.height) text.draw(context.sink, label, rect.midX, rect.midY, "dataLabel", inkOn(fill, context.theme.ink, context.surface), "center");
      return;
    }
    if (bars.horizontal) text.draw(context.sink, label, negative ? rect.left - 4 : rect.right + 4, rect.midY, "dataLabel", context.theme.secondaryInk, negative ? "right" : "left");
    else text.draw(context.sink, label, rect.midX, negative ? rect.bottom + 3 : rect.top - 3, "dataLabel", context.theme.secondaryInk, negative ? "top" : "bottom");
  }

  override get clipToPlot(): boolean {
    return !this.bars.valueLabels;
  }

  override overhang(text: TextPainter): number {
    return this.bars.valueLabels && !this.bars.horizontal && !this.stacked ? text.lineHeight("dataLabel") + 4 : 0;
  }

  override addLegend(legend: LegendCollector): void {
    if (this.bars.colorBy === null) legend.add(this.bars.label, this.color, "fill");
    else legend.addCategories(this.groups, "fill");
  }
}
